// Messages
pub fn show_sexp(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s, at_file, at_pos) => {
            s
        }
        Sexp::Str(s, at_file, at_pos) => {
            string_append(str_lit("\""), string_append(s, str_lit("\"")))
        }
        Sexp::Num(k, num_file, num_pos) => {
            i64_to_string(k)
        }
        Sexp::Big(text, f, p) => {
            text
        }
        Sexp::Chr(c, at_file, at_pos) => {
            string_append(str_lit("#\\"), char_to_string(c))
        }
        Sexp::Real(t, at_file, at_pos) => {
            t
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            string_append(str_lit("("), string_append(show_sexps(xs), str_lit(")")))
        }
    }
}

pub fn show_sexps(xs: Sexps) -> Str {
    if null_p(xs) {
        str_lit("")
    } else if null_p(cdr(xs)) {
        show_sexp(car(xs))
    } else {
        string_append(show_sexp(car(xs)), string_append(str_lit(" "), show_sexps(cdr(xs))))
    }
}

pub fn cv_where(v: &'static Cv) -> Str {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            here
        }
    }
}

/// What a refusal says, past `kfx: `: where, the innermost list being
/// checked and the definition, then `message`.
pub fn refusal_text(v: &'static Cv, message: Str) -> Str {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            string_append(if i64_eq(line, 0i64) {
                str_lit("")
            } else if string_eq_p(file, str_lit("<draft>")) {
                string_append(str_lit("<draft>@"), string_append(i64_to_string(at), str_lit(": ")))
            } else {
                string_append(file, string_append(str_lit(":"), string_append(i64_to_string(line), str_lit(": "))))
            }, string_append(str_lit("in "), string_append(here, string_append(str_lit(": "), message))))
        }
    }
}

/// An error, said where: the innermost list being checked, and the
/// definition.
pub fn refuse(v: &'static Cv, message: Str) -> Void {
    error(string_append(str_lit("kfx: "), refusal_text(v, message)))
}

/// A name, where one is expected: refused, saying where, if `e` is none.
pub fn name_of(v: &'static Cv, e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s, at_file, at_pos) => {
            s
        }
        _ => {
            let other = tagcase_;
            match refuse(v, string_append(str_lit("a name is expected here, not "), show_sexp(other))) {}
        }
    }
}

// Effects
pub fn take_chars(cs: List<char>, n: i64) -> List<char> {
    if (null_p(cs) || i64_eq(n, 0i64)) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), take_chars(cdr(cs), i64_minus(n, 1i64)))
    }
}

pub fn substring_of(x: Str, n: i64) -> Str {
    list_to_string(take_chars(string_to_list(x), n))
}

pub fn same_from_p(x: Str, p: Str, i: i64, n: i64) -> bool {
    (i64_eq(i, n) || (char_eq_p(string_ref_i64(x, i), string_ref_i64(p, i)) && same_from_p(x, p, i64_plus(i, 1i64), n)))
}

/// Whether `x` begins `p`: compared in place, making nothing (the compiler
/// asks it of every fact it searches).
pub fn has_prefix_p(x: Str, p: Str) -> bool {
    (not(i64_lt(string_length_i64(x), string_length_i64(p))) && same_from_p(x, p, 0i64, string_length_i64(p)))
}

pub fn drop_chars(mut cs: List<char>, mut n: i64) -> List<char> {
    loop {
        if (null_p(cs) || i64_eq(n, 0i64)) {
            return cs;
        } else {
            (cs, n) = (cdr(cs), i64_minus(n, 1i64));
            continue;
        }
    }
}

pub fn after_prefix(x: Str, p: Str) -> Str {
    list_to_string(drop_chars(string_to_list(x), string_length_i64(p)))
}

pub fn chars_after_dots(mut cs: List<char>) -> List<char> {
    loop {
        if (null_p(cs) || null_p(cdr(cs))) {
            return nil::<char>();
        } else if (char_eq_p(car(cs), '.') && char_eq_p(car(cdr(cs)), '.')) {
            return cdr(cdr(cs));
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn chars_before_dots(cs: List<char>) -> List<char> {
    if (null_p(cs) || null_p(cdr(cs))) {
        cs
    } else if (char_eq_p(car(cs), '.') && char_eq_p(car(cdr(cs)), '.')) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), chars_before_dots(cdr(cs)))
    }
}

/// What precedes the first `..` of `x`.
pub fn before_dots(x: Str) -> Str {
    list_to_string(chars_before_dots(string_to_list(x)))
}

/// What follows the first `..` of `x`.
pub fn after_dots(x: Str) -> Str {
    list_to_string(chars_after_dots(string_to_list(x)))
}

pub fn char_from_p(s: Str, c: char, i: i64, n: i64) -> bool {
    (i64_lt(i, n) && (char_eq_p(string_ref_i64(s, i), c) || char_from_p(s, c, i64_plus(i, 1i64), n)))
}

pub fn has_char_in_p(s: Str, c: char) -> bool {
    char_from_p(s, c, 0i64, string_length_i64(s))
}

pub fn repeated_p(xs: Strings) -> bool {
    (not(null_p(xs)) && (string_member_p(car(xs), cdr(xs)) || repeated_p(cdr(xs))))
}

/// The first of `xs` that is there again later, or ``.
pub fn first_repeated(mut xs: Strings) -> Str {
    loop {
        if null_p(xs) {
            return str_lit("");
        } else if string_member_p(car(xs), cdr(xs)) {
            return car(xs);
        } else {
            xs = cdr(xs);
            continue;
        }
    }
}

pub fn strings_eq_p(a: Strings, b: Strings) -> bool {
    if null_p(a) {
        null_p(b)
    } else if null_p(b) {
        false
    } else {
        (string_eq_p(car(a), car(b)) && strings_eq_p(cdr(a), cdr(b)))
    }
}

/// A product's label or a sum's tag, as written: a name or a number.
pub fn label_of(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, at_file, at_pos) => {
            n
        }
        Sexp::Num(k, f, p) => {
            i64_to_string(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// Whether effect `es` may abort: a `goto` on some region, or suspend, a
/// `comefrom` (C45), which aborts to its prompt. Such a procedure, in
/// Rust, returns a `Result` (emit.kfx).
pub fn escapes_p(es: Strings) -> bool {
    any_p(lambda1s(move |x: Str| {
        (has_prefix_p(x, str_lit("goto:")) || has_prefix_p(x, str_lit("comefrom:")) || has_prefix_p(x, str_lit("~")))
    }), es)
}

/// Whether effect `es` may suspend: a `comefrom` on some region, or an
/// effect variable, which may stand for one (C46). Such a procedure, in
/// Rust, is an `async fn` (C45).
pub fn suspends_p(es: Strings) -> bool {
    any_p(lambda1s(move |x: Str| {
        (has_prefix_p(x, str_lit("comefrom:")) || has_prefix_p(x, str_lit("~")))
    }), es)
}

/// An effect on `acyclic`: making and reading frozen data are pure, in
/// FX-26; writing it is refused where its type is read.
pub fn frozen_atom_p(x: Str) -> bool {
    (string_eq_p(x, str_lit("read:acyclic")) || string_eq_p(x, str_lit("alloc:acyclic")) || string_eq_p(x, str_lit("write:acyclic")) || string_eq_p(x, str_lit("read:const")) || string_eq_p(x, str_lit("read:%fresh")) || string_eq_p(x, str_lit("alloc:%fresh")))
}

pub fn effs_union(mut a: Strings, mut b: Strings) -> Strings {
    loop {
        if null_p(a) {
            if any_p(lambda1s(move |x: Str| {
                frozen_atom_p(x)
            }), b) {
                (a, b) = (b, nil::<Str>());
                continue;
            } else {
                return b;
            }
        } else if (frozen_atom_p(car(a)) || string_member_p(car(a), b)) {
            a = cdr(a);
            continue;
        } else {
            (a, b) = (cdr(a), kayak_rt::heap_cons(car(a), b));
            continue;
        }
    }
}

/// A read of one global, `g:name`; not a `goto:`.
pub fn global_atom_p(x: Str) -> bool {
    (i64_gt(string_length_i64(x), 1i64) && char_eq_p(string_ref_i64(x, 0i64), 'g') && char_eq_p(string_ref_i64(x, 1i64), ':'))
}

/// Whether effect `a` is within `b`: a read of one global is within a
/// read of all of them, and an I-cell's fill within a write of its region
/// (C101: FX's `init`, told apart from a write by `par` alone).
pub fn effs_within_p(a: Strings, b: Strings) -> bool {
    (null_p(a) || ((string_member_p(car(a), b) || string_eq_p(car(a), str_lit("~!")) || (global_atom_p(car(a)) && string_member_p(str_lit("@globals"), b)) || (has_prefix_p(car(a), str_lit("init:")) && string_member_p(string_append(str_lit("write:"), after_prefix(car(a), str_lit("init:"))), b))) && effs_within_p(cdr(a), b)))
}

pub fn words_of(xs: Strings) -> Str {
    if null_p(xs) {
        str_lit("")
    } else if null_p(cdr(xs)) {
        car(xs)
    } else {
        string_append(car(xs), string_append(str_lit(" "), words_of(cdr(xs))))
    }
}

// The kinds of an effect atom on a region, `read:@a`: FX-26's store
// effects and control effects, and its processes' (C101): a message sent
// to a mailbox at a region, taken from one, an I-cell filled, awaited.
pub fn region_kinds() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit("read"), kayak_rt::heap_cons(str_lit("write"), kayak_rt::heap_cons(str_lit("alloc"), kayak_rt::heap_cons(str_lit("goto"), kayak_rt::heap_cons(str_lit("comefrom"), kayak_rt::heap_cons(str_lit("send"), kayak_rt::heap_cons(str_lit("receive"), kayak_rt::heap_cons(str_lit("init"), kayak_rt::heap_cons(str_lit("await"), kayak_rt::nil())))))))))
    })
}

pub fn after_colon(mut cs: List<char>) -> List<char> {
    loop {
        if null_p(cs) {
            return nil::<char>();
        } else if char_eq_p(car(cs), ':') {
            return cdr(cs);
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

// Each of `region-kinds` with its colon, as an atom begins.
pub fn region_prefixes() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit("read:"), kayak_rt::heap_cons(str_lit("write:"), kayak_rt::heap_cons(str_lit("alloc:"), kayak_rt::heap_cons(str_lit("goto:"), kayak_rt::heap_cons(str_lit("comefrom:"), kayak_rt::heap_cons(str_lit("send:"), kayak_rt::heap_cons(str_lit("receive:"), kayak_rt::heap_cons(str_lit("init:"), kayak_rt::heap_cons(str_lit("await:"), kayak_rt::nil())))))))))
    })
}

pub fn region_atom_p(x: Str) -> bool {
    any_p(lambda1s(move |k: Str| {
        has_prefix_p(x, k)
    }), region_prefixes())
}

pub fn atom_kind(x: Str) -> Str {
    substring_of(x, i64_minus(string_length_i64(x), size(after_colon(string_to_list(x)))))
}

pub fn atom_region(x: Str) -> Str {
    list_to_string(after_colon(string_to_list(x)))
}

/// Whether atom `a` is one a process may have that is seen outside it:
/// a send, a fill or an await, I/O, `spin`, `nondet`, reading globals'
/// bindings or data frozen in the heap, allocating at a region that is
/// no place (a constant, or the heap); or anything on a binder in
/// `bound`, which a caller gives (`crossing_atom`).
pub fn crossing_atom_p(bound: Strings, a: Str) -> bool {
    (string_eq_p(a, str_lit("spin")) || string_eq_p(a, str_lit("nondet")) || string_eq_p(a, str_lit("@globals")) || string_eq_p(a, str_lit("~!")) || global_atom_p(a) || has_prefix_p(a, str_lit("io:")) || has_prefix_p(a, str_lit("send:")) || has_prefix_p(a, str_lit("init:")) || has_prefix_p(a, str_lit("await:")) || string_eq_p(a, str_lit("read:acyclic")) || string_eq_p(a, str_lit("read:%fresh")) || string_eq_p(a, str_lit("read:const")) || string_member_p(a, bound) || (has_prefix_p(a, str_lit("alloc:")) && {
        let r = after_prefix(a, str_lit("alloc:"));
        (has_prefix_p(r, str_lit("@")) || string_eq_p(r, str_lit("acyclic")) || string_eq_p(r, str_lit("%fresh")))
    }) || (region_atom_p(a) && string_member_p(atom_region(a), bound)))
}

/// Whether a latent effect is one a process may have (C101), so that a
/// procedure of it may be held on another thread: its closure, in Rust, is
/// `Send + Sync` (C102).
pub fn crossing_p(es: Strings) -> bool {
    not(any_p(lambda1s(move |a: Str| {
        not(crossing_atom_p(nil::<Str>(), a))
    }), es))
}

/// An effect atom as FX-26 writes it; a read of one global is gathered
/// by `show-effs`.
pub fn atom_written(x: Str) -> Str {
    let at = lambda1s(move |p: Str| {
        let r = after_prefix(x, p);
        if has_prefix_p(r, str_lit("'")) {
            after_prefix(r, str_lit("'"))
        } else {
            r
        }
    });
    if string_eq_p(x, str_lit("spin")) {
        str_lit("spin")
    } else if string_eq_p(x, str_lit("nondet")) {
        str_lit("nondet")
    } else if string_eq_p(x, str_lit("@globals")) {
        str_lit("(read @globals)")
    } else if has_prefix_p(x, str_lit("io:")) {
        string_append(str_lit("(io "), string_append(after_prefix(x, str_lit("io:")), str_lit(")")))
    } else if region_atom_p(x) {
        string_append(str_lit("("), string_append(substring_of(atom_kind(x), i64_minus(string_length_i64(atom_kind(x)), 1i64)), string_append(str_lit(" "), string_append(at(atom_kind(x)), str_lit(")")))))
    } else if has_prefix_p(x, str_lit("~")) {
        after_prefix(x, str_lit("~"))
    } else {
        x
    }
}

/// An effect as FX-26 writes it: `pure`, an atom, or `(maxeff ...)`, the
/// globals read gathered, `(read (globals f g))`; its atoms, and the
/// globals' names, in order, as Fixpt writes them (TODO §30).
pub fn show_effs(es: Strings) -> Str {
    let globals = sorted_strings(concat(map(lambda1s(move |x: Str| {
        if global_atom_p(x) {
            the::<Strings>(kayak_rt::heap_cons(after_prefix(x, str_lit("g:")), kayak_rt::nil()))
        } else {
            nil::<Str>()
        }
    }), es)));
    let others = concat(map(lambda1s(move |x: Str| {
        if (global_atom_p(x) || string_eq_p(x, str_lit("~!"))) {
            nil::<Str>()
        } else {
            the::<Strings>(kayak_rt::heap_cons(atom_written(x), kayak_rt::nil()))
        }
    }), es));
    let parts = sorted_strings(if null_p(globals) {
        others
    } else {
        onto(others, kayak_rt::heap_cons(string_append(str_lit("(read (globals "), string_append(words_of(globals), str_lit("))"))), kayak_rt::nil()))
    });
    if null_p(parts) {
        str_lit("pure")
    } else if null_p(cdr(parts)) {
        car(parts)
    } else {
        string_append(str_lit("(maxeff "), string_append(words_of(parts), str_lit(")")))
    }
}

pub fn find_effdef(mut v: &'static Cv, mut name: Str, mut es: Effdefs) -> Strings {
    loop {
        if null_p(es) {
            return match refuse(v, string_append(str_lit("an effect KFX does not have: "), name)) {};
        } else {
            let tagcase_ = car(es);
            match *tagcase_ {
                Effdef::Effdef(n, atoms) => {
                    if string_eq_p(n, name) {
                        return atoms;
                    } else {
                        es = cdr(es);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn cv_effdefs(v: &'static Cv) -> Effdefs {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            es
        }
    }
}

/// A region's name: a constant, `@a`, or a poly's region binder, `'r`.
pub fn region_name(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> Str {
    let s = {
        let tagcase_ = r;
        match *tagcase_ {
            Sexp::Sym(n, at_file, at_pos) => {
                n
            }
            Sexp::Lst(xs, f, l, p) => {
                if (i64_eq(size(xs), 2i64) && (sym_is_p(car(xs), str_lit("const")) || sym_is_p(car(xs), str_lit("acyclic"))) && sym_is_p(second(xs), str_lit("heap"))) {
                    sym_name(car(xs))
                } else {
                    match refuse(v, string_append(str_lit("a region KFX does not have: "), show_sexp(r))) {}
                }
            }
            _ => {
                let other = tagcase_;
                match refuse(v, string_append(str_lit("a region KFX does not have: "), show_sexp(other))) {}
            }
        }
    };
    if string_eq_p(s, str_lit("@globals")) {
        match refuse(v, str_lit("globals are a region only in effects: (read @globals), (read (globals g))")) {}
    } else if char_eq_p(string_ref_i64(s, 0i64), '@') {
        s
    } else if string_eq_p(s, str_lit("acyclic")) {
        s
    } else if string_eq_p(s, str_lit("const")) {
        // Data frozen into the heap, which nothing may write any more; it may
        // have been written before, so may be cyclic (Fixpt's
        // acyclic-regions.md; C161).
        s
    } else if string_member_p(string_append(str_lit("'"), s), tvars) {
        string_append(str_lit("'"), s)
    } else if (char_eq_p(string_ref_i64(s, 0i64), '\'') && string_member_p(s, tvars)) {
        s
    } else if string_eq_p(s, str_lit("heap")) {
        // The heap place, a region as any place is (C34): `@heap` (C171;
        // Fixpt's `with-shadows-applied.fx`).
        str_lit("@heap")
    } else {
        match refuse(v, string_append(str_lit("a region KFX-0 does not have: "), s)) {}
    }
}

pub fn parse_region(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> &'static Ty {
    let name = region_name(v, tvars, r);
    if char_eq_p(string_ref_i64(name, 0i64), '\'') {
        ty_var(name)
    } else {
        ty_rconst(name)
    }
}

/// The region of data that may be written: not `acyclic` nor `const`, which
/// are frozen.
pub fn parse_mutable_region(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> &'static Ty {
    if (sym_is_p(r, str_lit("acyclic")) || sym_is_p(r, str_lit("const"))) {
        match refuse(v, str_lit("mutable data at acyclic, which is frozen and never written")) {}
    } else {
        parse_region(v, tvars, r)
    }
}

// FX-26's standard type `io-error` (Fixpt 17ac0c5, C49): an I/O failure's
// kind, for a `tagcase`, and the system's words.
pub fn io_error_text() -> Str {
    str_lit("(productof (kind (sumof (not-found unit) (permission-denied unit) (already-exists unit) (not-a-directory unit)\n                           (is-a-directory unit) (broken-pipe unit) (invalid-data unit) (other unit)))\n              (detail string))")
}

/// The `io` effects' kinds, a fixed family (C49).
pub fn io_kind_p(k: Str) -> bool {
    string_member_p(k, kayak_rt::heap_cons(str_lit("stdin"), kayak_rt::heap_cons(str_lit("stdout"), kayak_rt::heap_cons(str_lit("stderr"), kayak_rt::heap_cons(str_lit("fs-read"), kayak_rt::heap_cons(str_lit("fs-write"), kayak_rt::heap_cons(str_lit("clock"), kayak_rt::heap_cons(str_lit("args"), kayak_rt::heap_cons(str_lit("exit"), kayak_rt::heap_cons(str_lit("terminal"), kayak_rt::heap_cons(str_lit("native"), kayak_rt::nil())))))))))))
}

