/// The innermost binding of `name`, as a list of one, or none.
pub fn find_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    if string_eq_p(n, name) {
                        return kayak_rt::heap_cons(car(bs), kayak_rt::nil());
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

// First-class modules (C170; Fixpt's `docs/research/first-class-modules.md`):
// a module's type, `(ty-data "%mtype" (item ...))`, each item `%abs t`, a
// description `%desc t` of its type, an effect's `%edesc e` (its atoms a
// `ty-proc`'s effect), or a value `%val x` of its type. An abstract type
// inside is `ID..t`, `ID` the moduleof's or the module's own (`mt@POS`),
// renamed `p..t` once the module is bound to `p`. A name a module gives as
// a type, in a `with` or inside the module, is a binding `%type t`.
pub fn type_bind(n: Str, t: &'static Ty) -> &'static Bind {
    bind(string_append(str_lit("%type "), n), scheme(nil::<Str>(), t), str_lit("type"))
}

pub fn with_type_binds(v: &'static Cv, tbs: Binds, eds: Effdefs) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            cv(onto(tbs, bs), ds, als, onto(eds, es), here, group, file, line, fs, tv, at)
        }
    }
}

pub fn mtype_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            string_eq_p(d, str_lit("%mtype"))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn mitem_kind(x: &'static Ty) -> Str {
    let tagcase_ = x;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if has_prefix_p(d, str_lit("%abs ")) {
                str_lit("%abs")
            } else if has_prefix_p(d, str_lit("%desc ")) {
                str_lit("%desc")
            } else if has_prefix_p(d, str_lit("%edesc ")) {
                str_lit("%edesc")
            } else if has_prefix_p(d, str_lit("%val ")) {
                str_lit("%val")
            } else {
                str_lit("")
            }
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

pub fn mitem_name(x: &'static Ty) -> Str {
    let tagcase_ = x;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            after_prefix(d, string_append(mitem_kind(x), str_lit(" ")))
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

pub fn mtype_items(t: &'static Ty) -> Tys {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%mtype")) {
                args
            } else {
                nil::<&'static Ty>()
            }
        }
        _ => {
            let other = tagcase_;
            nil::<&'static Ty>()
        }
    }
}

/// The item of module type `t` of `kind` (`%abs`, `%desc`, ...) named `n`.
pub fn mtype_find(t: &'static Ty, kind: Str, n: Str) -> Tys {
    filter(lambda1s(move |x: &'static Ty| {
        (string_eq_p(mitem_kind(x), kind) && string_eq_p(mitem_name(x), n))
    }), mtype_items(t))
}

pub fn string_index(mut x: Str, mut xs: Strings, mut i: i64) -> i64 {
    loop {
        if null_p(xs) {
            return -1i64;
        } else if string_eq_p(car(xs), x) {
            return i;
        } else {
            (xs, i) = (cdr(xs), i64_plus(i, 1i64));
            continue;
        }
    }
}

pub fn string_nth(mut xs: Strings, mut i: i64) -> Str {
    loop {
        if i64_eq(i, 0i64) {
            return car(xs);
        } else {
            (xs, i) = (cdr(xs), i64_minus(i, 1i64));
            continue;
        }
    }
}

/// `t`, each type named one of `from` (of no arguments) replaced by the
/// type of `to` in its place.
pub fn data_replaced(from: Strings, to: Tys, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if null_p(args) {
                let i = string_index(d, from, 0i64);
                if i64_lt(i, 0i64) {
                    t
                } else {
                    ty_nth(to, i)
                }
            } else {
                ty_data(d, map(lambda1s(move |x: &'static Ty| {
                    data_replaced(from, to, x)
                }), args))
            }
        }
        Ty::TyList(e, r) => {
            ty_list(data_replaced(from, to, e), r)
        }
        Ty::TyRef(e, r) => {
            ty_ref(data_replaced(from, to, e), r)
        }
        Ty::TyFlat(e, r) => {
            ty_flat(data_replaced(from, to, e), r)
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(es, map(lambda1s(move |x: &'static Ty| {
                data_replaced(from, to, x)
            }), ps), data_replaced(from, to, r))
        }
        Ty::TyShape(p, ls, ts) => {
            ty_shape(p, ls, map(lambda1s(move |x: &'static Ty| {
                data_replaced(from, to, x)
            }), ts))
        }
        Ty::TyTag(a, h, es, r) => {
            ty_tag(data_replaced(from, to, a), data_replaced(from, to, h), es, r)
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn ty_nth(mut xs: Tys, mut i: i64) -> &'static Ty {
    loop {
        if i64_eq(i, 0i64) {
            return car(xs);
        } else {
            (xs, i) = (cdr(xs), i64_minus(i, 1i64));
            continue;
        }
    }
}

/// The names of the types of no arguments in `t` that begin `pre`.
pub fn data_names_with(mut pre: Str, mut t: &'static Ty) -> Strings {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if (null_p(args) && has_prefix_p(d, pre)) {
                    return the::<Strings>(kayak_rt::heap_cons(d, kayak_rt::nil()));
                } else {
                    return concat(map(lambda1s(move |x: &'static Ty| {
                        data_names_with(pre, x)
                    }), args));
                }
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyFlat(e, r) => {
                t = e;
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                return concat(map(lambda1s(move |x: &'static Ty| {
                    data_names_with(pre, x)
                }), kayak_rt::heap_cons(r, ps)));
            }
            Ty::TyShape(p, ls, ts) => {
                return concat(map(lambda1s(move |x: &'static Ty| {
                    data_names_with(pre, x)
                }), ts));
            }
            Ty::TyTag(a, h, es, r) => {
                return onto(data_names_with(pre, a), data_names_with(pre, h));
            }
            _ => {
                let other = tagcase_;
                return nil::<Str>();
            }
        }
    }
}

pub fn data_renamed(from: Strings, to: Strings, t: &'static Ty) -> &'static Ty {
    data_replaced(from, map(lambda1s(move |n: Str| {
        ty_data(n, nil::<&'static Ty>())
    }), to), t)
}

pub fn abs_ref(x: &'static Ty) -> &'static Ty {
    let tagcase_ = x;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if null_p(args) {
                x
            } else {
                car(args)
            }
        }
        _ => {
            let other = tagcase_;
            x
        }
    }
}

/// A module type bound to `p`: its abstract types named `p..t` for the
/// binding, opaque, equal to no other (Fixpt's `k-name-module`; Sheldon's
/// `let` rule, `modules/let-opaque.fx`); any other type as it is.
pub fn mtype_named(p: Str, t: &'static Ty) -> &'static Ty {
    if not(mtype_p(t)) {
        t
    } else {
        let refs = concat(map(lambda1s(move |x: &'static Ty| {
            if string_eq_p(mitem_kind(x), str_lit("%abs")) {
                let tagcase_ = x;
                match *tagcase_ {
                    Ty::TyData(d, args) => {
                        let tagcase_ = car(args);
                        match *tagcase_ {
                            Ty::TyData(r, a2) => {
                                the::<Strings>(kayak_rt::heap_cons(r, kayak_rt::nil()))
                            }
                            _ => {
                                let other = tagcase_;
                                nil::<Str>()
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            } else {
                nil::<Str>()
            }
        }), mtype_items(t)));
        if null_p(refs) {
            t
        } else {
            data_renamed(refs, map(lambda1s(move |r: Str| {
                string_append(p, string_append(str_lit(".."), after_dots(r)))
            }), refs), t)
        }
    }
}

/// The first type `p..t` in `t` of a module `p` of `ps`, or "".
pub fn mentions_module_of_p(mut t: &'static Ty, mut ps: Strings) -> Str {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if (null_p(args) && any_p(lambda1s(move |p: Str| {
                    has_prefix_p(d, string_append(p, str_lit("..")))
                }), ps)) {
                    return d;
                } else {
                    return mentions_module_in(args, ps);
                }
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyFlat(e, r) => {
                t = e;
                continue;
            }
            Ty::TyProc(es, ps2, r) => {
                return mentions_module_in(kayak_rt::heap_cons(r, ps2), ps);
            }
            Ty::TyShape(p, ls, ts) => {
                return mentions_module_in(ts, ps);
            }
            Ty::TyTag(a, h, es, r) => {
                return mentions_module_in(kayak_rt::heap_cons(a, kayak_rt::heap_cons(h, kayak_rt::nil())), ps);
            }
            _ => {
                let other = tagcase_;
                return str_lit("");
            }
        }
    }
}

pub fn mentions_module_in(mut ts: Tys, mut ps: Strings) -> Str {
    loop {
        if null_p(ts) {
            return str_lit("");
        } else {
            let m = mentions_module_of_p(car(ts), ps);
            if string_eq_p(m, str_lit("")) {
                ts = cdr(ts);
                continue;
            } else {
                return m;
            }
        }
    }
}

/// The type of the value named `n` in scope, or `unit` if none is.
pub fn bound_type(v: &'static Cv, n: Str) -> &'static Ty {
    let found = find_bind(n, cv_binds(v));
    if null_p(found) {
        ty_unit()
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(m, sc, w) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tv, t) => {
                        t
                    }
                }
            }
        }
    }
}

pub fn selected_type(v: &'static Cv, p: Str, t: &'static Ty, n: Str) -> &'static Ty {
    let d = mtype_find(t, str_lit("%desc"), n);
    if not(null_p(d)) {
        let tagcase_ = car(d);
        match *tagcase_ {
            Ty::TyData(k, args) => {
                car(args)
            }
            _ => {
                let other = tagcase_;
                ty_unit()
            }
        }
    } else if not(null_p(mtype_find(t, str_lit("%abs"), n))) {
        let tagcase_ = car(mtype_find(t, str_lit("%abs"), n));
        match *tagcase_ {
            Ty::TyData(k, args) => {
                car(args)
            }
            _ => {
                let other = tagcase_;
                ty_unit()
            }
        }
    } else {
        match refuse(v, string_append(p, string_append(str_lit(" gives no type "), n))) {}
    }
}

pub fn parse_effect(v: &'static Cv, tvars: Strings, e: &'static Sexp) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s, at_file, at_pos) => {
            if string_eq_p(s, str_lit("pure")) {
                nil::<Str>()
            } else if string_eq_p(s, str_lit("spin")) {
                kayak_rt::heap_cons(str_lit("spin"), kayak_rt::nil())
            } else if string_eq_p(s, str_lit("%found")) {
                match refuse(v, str_lit("`(->* (param ...) result)` is only the type a definition declares (`define`, `define-rec`)")) {}
            } else if string_eq_p(s, str_lit("nondet")) {
                // That an answer may differ from run to run (C101): no region, so
                // never masked, as `spin`.
                kayak_rt::heap_cons(str_lit("nondet"), kayak_rt::nil())
            } else if string_member_p(string_append(str_lit("~"), s), tvars) {
                // A poly's effect binder (C46): an atom of its own, `~e`.
                kayak_rt::heap_cons(string_append(str_lit("~"), s), kayak_rt::nil())
            } else {
                find_effdef(v, s, cv_effdefs(v))
            }
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            if sym_is_p(car(xs), str_lit("maxeff")) {
                parse_effects(v, tvars, cdr(xs))
            } else if (sym_is_p(car(xs), str_lit("select")) && i64_eq(size(xs), 3i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } && mtype_p(bound_type(v, sym_name(second(xs))))) {
                // An effect a module value gives (C170).
                let found = mtype_find(bound_type(v, sym_name(second(xs))), str_lit("%edesc"), name_of(v, third(xs)));
                if null_p(found) {
                    match refuse(v, string_append(sym_name(second(xs)), string_append(str_lit(" gives no effect "), name_of(v, third(xs))))) {}
                } else {
                    let tagcase_ = car(found);
                    match *tagcase_ {
                        Ty::TyData(d, args) => {
                            let tagcase_ = car(args);
                            match *tagcase_ {
                                Ty::TyProc(es, ps, r) => {
                                    es
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                }
            } else if (sym_is_p(car(xs), str_lit("select")) && i64_eq(size(xs), 3i64)) {
                // A module's effect, as the module defined at the top level gives it.
                find_effdef(v, string_append(name_of(v, second(xs)), string_append(str_lit(" "), name_of(v, third(xs)))), cv_effdefs(v))
            } else if (sym_is_p(car(xs), str_lit("io")) && i64_eq(size(xs), 2i64) && io_kind_p({
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            })) {
                // An I/O effect (C49), `io:` and its kind: no region, so never masked.
                kayak_rt::heap_cons(string_append(str_lit("io:"), sym_name(second(xs))), kayak_rt::nil())
            } else if (sym_is_p(car(xs), str_lit("read")) && sym_is_p(second(xs), str_lit("@globals"))) {
                kayak_rt::heap_cons(str_lit("@globals"), kayak_rt::nil())
            } else if (sym_is_p(car(xs), str_lit("read")) && head_is_p(second(xs), str_lit("globals"))) {
                map(lambda1s(move |g: &'static Sexp| {
                    string_append(str_lit("g:"), name_of(v, g))
                }), cdr(items(second(xs))))
            } else if (i64_eq(size(xs), 2i64) && any_p(lambda1s(move |k: Str| {
                sym_is_p(car(xs), k)
            }), region_kinds())) {
                kayak_rt::heap_cons(string_append(name_of(v, car(xs)), string_append(str_lit(":"), region_name(v, tvars, second(xs)))), kayak_rt::nil())
            } else {
                match refuse(v, string_append(str_lit("an effect KFX does not have: "), show_sexp(e))) {}
            }
        }
        _ => {
            let other = tagcase_;
            match refuse(v, string_append(str_lit("an effect KFX does not have: "), show_sexp(e))) {}
        }
    }
}

pub fn parse_effects(v: &'static Cv, tvars: Strings, es: Sexps) -> Strings {
    if null_p(es) {
        nil::<Str>()
    } else {
        effs_union(parse_effect(v, tvars, car(es)), parse_effects(v, tvars, cdr(es)))
    }
}

/// Effect atoms on region `from` made atoms on region `to`.
pub fn rename_atoms(es: Strings, from: Str, to: Str) -> Strings {
    map(lambda1s(move |x: Str| {
        if (region_atom_p(x) && string_eq_p(atom_region(x), from)) {
            string_append(atom_kind(x), to)
        } else if (has_prefix_p(from, str_lit("~")) && string_eq_p(x, from)) {
            if has_prefix_p(to, str_lit("~")) {
                to
            } else {
                string_append(str_lit("~"), to)
            }
        } else {
            x
        }
    }), es)
}

pub fn remove_atom(mut x: Str, mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if string_eq_p(car(es), x) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), remove_atom(x, cdr(es)));
        }
    }
}

/// An effect as a type, where an effect binder is given one (C46): the
/// row of its atoms, held as a procedure's latent effect.
pub fn effect_row(atoms: Strings) -> &'static Ty {
    ty_proc(atoms, nil::<&'static Ty>(), ty_unit())
}

/// Effects on region `name`, made effects on the region `m` stands for.
pub fn rename_region(es: Strings, name: Str, m: &'static Ty) -> Strings {
    let tagcase_ = m;
    match *tagcase_ {
        Ty::TyMeta(k) => {
            rename_atoms(es, name, string_append(str_lit("?"), i64_to_string(k)))
        }
        Ty::TyRconst(n) => {
            rename_atoms(es, name, n)
        }
        Ty::TyVar(n) => {
            rename_atoms(es, name, n)
        }
        Ty::TyProc(r#as, ps, r) => {
            // An effect binder given an effect, a row (C46): its atoms in its place.
            if string_member_p(name, es) {
                effs_union(r#as, remove_atom(name, es))
            } else {
                es
            }
        }
        _ => {
            let other = tagcase_;
            es
        }
    }
}

pub fn meta_name(k: i64) -> Str {
    string_append(str_lit("?"), i64_to_string(k))
}

pub fn replace_var(name: Str, m: &'static Ty, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyVar(n) => {
            if string_eq_p(n, name) {
                m
            } else {
                t
            }
        }
        Ty::TyList(e, r) => {
            ty_list(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyFlat(e, r) => {
            ty_flat(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyShape(p, ls, ts) => {
            ty_shape(p, ls, map(lambda1s(move |x: &'static Ty| {
                replace_var(name, m, x)
            }), ts))
        }
        Ty::TyTag(a, h, d, r) => {
            ty_tag(replace_var(name, m, a), replace_var(name, m, h), rename_region(d, name, m), replace_var(name, m, r))
        }
        Ty::TyData(d, args) => {
            ty_data(d, map(lambda1s(move |x: &'static Ty| {
                replace_var(name, m, x)
            }), args))
        }
        Ty::TyRef(e, r) => {
            ty_ref(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(rename_region(es, name, m), map(lambda1s(move |p: &'static Ty| {
                replace_var(name, m, p)
            }), ps), replace_var(name, m, r))
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// Each binder `n` of a poly type written at `pos`, its kind's mark first
/// (`'n` a region's, `#n` a size's, a type's none), named `n@pos` (C107,
/// C158).
pub fn fold_renames(mut names: Strings, mut pos: i64, mut t: &'static Ty) -> &'static Ty {
    loop {
        if null_p(names) {
            return t;
        } else {
            (names, t) = (cdr(names), replace_var(car(names), ty_var(string_append(car(names), string_append(str_lit("@"), i64_to_string(pos)))), t));
            continue;
        }
    }
}

pub fn binder_kind(n: Str) -> Str {
    if has_prefix_p(n, str_lit("'")) {
        str_lit("region")
    } else if has_prefix_p(n, str_lit("#")) {
        str_lit("size")
    } else {
        str_lit("type")
    }
}

pub fn all_regions_p(ns: Strings) -> bool {
    not(any_p(lambda1s(move |n: Str| {
        not(has_prefix_p(n, str_lit("'")))
    }), ns))
}

/// A poly type's binders' names: all its parts but the last, its body.
pub fn poly_binders_of(args: Tys) -> Strings {
    if (null_p(args) || null_p(cdr(args))) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons({
            let tagcase_ = car(args);
            match *tagcase_ {
                Ty::TyVar(n) => {
                    n
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, poly_binders_of(cdr(args)))
    }
}

pub fn poly_body(args: Tys) -> &'static Ty {
    last(args)
}

pub fn taken_before(cs: Chars, c: char) -> Chars {
    if (null_p(cs) || char_eq_p(car(cs), c)) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), taken_before(cdr(cs), c))
    }
}

/// A poly type's binder as written: `'r@P` is `r`, `#n@P` `n`.
pub fn written_binder(n: Str) -> Str {
    let cs = string_chars(if has_prefix_p(n, str_lit("'")) {
        after_prefix(n, str_lit("'"))
    } else if has_prefix_p(n, str_lit("#")) {
        after_prefix(n, str_lit("#"))
    } else {
        n
    });
    list_to_string(taken_before(cs, '@'))
}

pub fn substitute_each(mut params: Strings, mut args: Tys, mut t: &'static Ty) -> &'static Ty {
    loop {
        if (null_p(params) || null_p(args)) {
            return t;
        } else {
            (params, args, t) = (cdr(params), cdr(args), replace_var(car(params), car(args), t));
            continue;
        }
    }
}

/// `t`, each of `params` replaced by its argument, all at once: first each
/// by a name no argument has, so that an argument naming a parameter is
/// not replaced again.
pub fn substitute(params: Strings, args: Tys, t: &'static Ty) -> &'static Ty {
    let temps = map(lambda1s(move |p: Str| {
        string_append(if has_prefix_p(p, str_lit("~")) {
            str_lit("~%subst ")
        } else {
            str_lit("%subst ")
        }, p)
    }), params);
    substitute_each(temps, args, substitute_each(params, map(lambda1s(move |p: Str| {
        ty_var(p)
    }), temps), t))
}

pub fn i64s_below(n: i64) -> List<i64> {
    if i64_lt_eq(n, 0i64) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(i64_minus(n, 1i64), i64s_below(i64_minus(n, 1i64)))
    }
}

/// A poly type's body, its binders given `regions` (C107).
pub fn poly_instance(args: Tys, regions: Tys) -> &'static Ty {
    substitute(poly_binders_of(args), regions, poly_body(args))
}

/// A poly type's binders, as written.
pub fn binders_shown(ns: Strings) -> Str {
    if null_p(ns) {
        str_lit("")
    } else if null_p(cdr(ns)) {
        string_append(str_lit("("), string_append(written_binder(car(ns)), string_append(str_lit(" "), string_append(binder_kind(car(ns)), str_lit(")")))))
    } else {
        string_append(str_lit("("), string_append(written_binder(car(ns)), string_append(str_lit(" "), string_append(binder_kind(car(ns)), string_append(str_lit(") "), binders_shown(cdr(ns)))))))
    }
}

/// A poly type's body, its binders as written, `'r` (C107).
pub fn poly_written(args: Tys) -> &'static Ty {
    poly_instance(args, map(lambda1s(move |n: Str| {
        ty_var(if has_prefix_p(n, str_lit("'")) {
            string_append(str_lit("'"), written_binder(n))
        } else if has_prefix_p(n, str_lit("#")) {
            string_append(str_lit("#"), written_binder(n))
        } else {
            written_binder(n)
        })
    }), poly_binders_of(args)))
}

// Types
/// `v`, with the type and region variables `names` in scope.
pub fn with_tvars(v: &'static Cv, names: Strings) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            cv(bs, ds, als, es, here, group, file, line, fs, onto(names, tv), at)
        }
    }
}

pub fn dt_named_p(name: Str, ds: Dts) -> bool {
    any_p(lambda1s(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                string_eq_p(n, name)
            }
        }
    }), ds)
}

/// A datatype, its parameters and variants, or `nil` (C84: a union, where
/// it had been a list of one or none).
pub fn find_family(mut name: Str, mut ds: Dts) -> kayak_rt::value::Value {
    loop {
        if null_p(ds) {
            return kayak_rt::value::Value::Nil;
        } else if {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    string_eq_p(n, name)
                }
            }
        } {
            return kayak_rt::value::other(car(ds), kayak_rt::value::Shape::Sum);
        } else {
            ds = cdr(ds);
            continue;
        }
    }
}

/// A type abbreviation, its parameters and what it stands for, as a list
/// of one, or none.
pub fn find_alias(mut name: Str, mut als: Aliases) -> List<&'static Alias> {
    loop {
        if null_p(als) {
            return nil::<&'static Alias>();
        } else {
            let tagcase_ = car(als);
            match *tagcase_ {
                Alias::Alias(n, ps, t) => {
                    if string_eq_p(n, name) {
                        return kayak_rt::heap_cons(car(als), kayak_rt::nil());
                    } else {
                        als = cdr(als);
                        continue;
                    }
                }
            }
        }
    }
}

/// The type abbreviations being expanded, which `tvars` carries, marked,
/// so that one that mentions itself is found.
pub fn expanding(mut tvars: Strings) -> Strings {
    loop {
        if null_p(tvars) {
            return nil::<Str>();
        } else if (i64_gt(string_length_i64(car(tvars)), 0i64) && char_eq_p(string_ref_i64(car(tvars), 0i64), '%')) {
            return kayak_rt::heap_cons(car(tvars), expanding(cdr(tvars)));
        } else {
            tvars = cdr(tvars);
            continue;
        }
    }
}

/// A generative type's conversion, the global or item `name`: not a local
/// that hides it.
pub fn conversion_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else if {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    (string_eq_p(n, name) && (string_eq_p(w, str_lit("global")) || string_eq_p(w, str_lit("item"))))
                }
            }
        } {
            return the::<Binds>(kayak_rt::heap_cons(car(bs), kayak_rt::nil()));
        } else {
            bs = cdr(bs);
            continue;
        }
    }
}

pub fn char_lower_p(c: char) -> bool {
    has_char_in_p(str_lit("abcdefghijklmnopqrstuvwxyz"), c)
}

pub fn same_at_p(s: Str, part: Str, at: i64, i: i64, n: i64) -> bool {
    (i64_eq(i, n) || (char_eq_p(string_ref_i64(s, i64_plus(at, i)), string_ref_i64(part, i)) && same_at_p(s, part, at, i64_plus(i, 1i64), n)))
}

pub fn has_from_p(s: Str, part: Str, at: i64) -> bool {
    (not(i64_lt(i64_minus(string_length_i64(s), at), string_length_i64(part))) && (same_at_p(s, part, at, 0i64, string_length_i64(part)) || has_from_p(s, part, i64_plus(at, 1i64))))
}

/// Whether `part` is in `s`: compared in place, making nothing.
pub fn string_has_p(s: Str, part: Str) -> bool {
    has_from_p(s, part, 0i64)
}

/// Whether `n` is a Rust keyword no raw identifier may be, `self`, `super`,
/// `crate`, or one as a type's name (`Self`): KFX names none so. The
/// others are Rust's `r#loop` (C41).
pub fn rust_keyword_clash_p(n: Str) -> bool {
    (string_member_p(n, kayak_rt::heap_cons(str_lit("self"), kayak_rt::heap_cons(str_lit("super"), kayak_rt::heap_cons(str_lit("crate"), kayak_rt::nil())))) || string_eq_p(camel(n), str_lit("Self")))
}

/// The types Rust or kayak-rt has that the emitter writes: no KFX type and
/// no type variable is named so, camel-cased, which would hide it.
pub fn rust_type_names() -> Strings {
    kayak_rt::heap_cons(str_lit("Str"), kayak_rt::heap_cons(str_lit("List"), kayak_rt::heap_cons(str_lit("Cons"), kayak_rt::heap_cons(str_lit("Int"), kayak_rt::heap_cons(str_lit("Tag"), kayak_rt::heap_cons(str_lit("Unwind"), kayak_rt::heap_cons(str_lit("Ref"), kayak_rt::heap_cons(str_lit("FlatArray"), kayak_rt::heap_cons(str_lit("Knot"), kayak_rt::heap_cons(str_lit("Show"), kayak_rt::heap_cons(str_lit("OnceCell"), kayak_rt::heap_cons(str_lit("Fn"), kayak_rt::heap_cons(str_lit("Result"), kayak_rt::heap_cons(str_lit("Ok"), kayak_rt::heap_cons(str_lit("Err"), kayak_rt::heap_cons(str_lit("String"), kayak_rt::heap_cons(str_lit("Copy"), kayak_rt::heap_cons(str_lit("Clone"), kayak_rt::heap_cons(str_lit("Self"), kayak_rt::heap_cons(str_lit("Module"), kayak_rt::heap_cons(str_lit("Void"), kayak_rt::heap_cons(str_lit("Bloblet"), kayak_rt::heap_cons(str_lit("BlobRef"), kayak_rt::heap_cons(str_lit("Arena"), kayak_rt::heap_cons(str_lit("Holds"), kayak_rt::heap_cons(str_lit("ListAt"), kayak_rt::heap_cons(str_lit("RefAt"), kayak_rt::heap_cons(str_lit("TBloblet"), kayak_rt::heap_cons(str_lit("FlatArr"), kayak_rt::heap_cons(str_lit("Flat"), kayak_rt::heap_cons(str_lit("Owner"), kayak_rt::heap_cons(str_lit("Default"), kayak_rt::heap_cons(str_lit("Procedure"), kayak_rt::heap_cons(str_lit("Native"), kayak_rt::heap_cons(str_lit("NativeFields"), kayak_rt::heap_cons(str_lit("Sealed"), kayak_rt::heap_cons(str_lit("Written"), kayak_rt::nil())))))))))))))))))))))))))))))))))))))
}

/// Whether `n` may be a KFX name (C27): a lower-case letter or an operator's
/// character first, then those, digits and `-`; no `--` (the emitter's
/// `__`); and none whose Rust name kayak-rt or the emitter writes.
pub fn kfx_name_p(n: Str) -> bool {
    let cs = string_chars(n);
    (not(null_p(cs)) && not(rust_keyword_clash_p(n)) && (char_lower_p(car(cs)) || has_char_in_p(str_lit("?!<>=+*/%-"), car(cs))) && not(any_p(lambda1s(move |c: char| {
        not((char_lower_p(c) || char_numeric_p(c) || has_char_in_p(str_lit("?!<>=+*/%-"), c)))
    }), cs)) && not(string_has_p(n, str_lit("--"))) && not(string_member_p(mangle(n), kayak_rt::heap_cons(str_lit("str_lit"), kayak_rt::heap_cons(str_lit("int_lit"), kayak_rt::heap_cons(str_lit("int_text"), kayak_rt::heap_cons(str_lit("unreachable_unwind"), kayak_rt::heap_cons(str_lit("kfx_toplevel"), kayak_rt::heap_cons(str_lit("once"), kayak_rt::heap_cons(str_lit("alloc"), kayak_rt::heap_cons(str_lit("the"), kayak_rt::heap_cons(str_lit("unwind"), kayak_rt::heap_cons(str_lit("knot"), kayak_rt::heap_cons(str_lit("lambda0"), kayak_rt::heap_cons(str_lit("lambda1"), kayak_rt::heap_cons(str_lit("lambda2"), kayak_rt::heap_cons(str_lit("lambda3"), kayak_rt::heap_cons(str_lit("lambda4"), kayak_rt::heap_cons(str_lit("leak_string"), kayak_rt::heap_cons(str_lit("with_big_stack"), kayak_rt::heap_cons(str_lit("fail"), kayak_rt::heap_cons(str_lit("make_continuation_prompt_tag"), kayak_rt::heap_cons(str_lit("nil"), kayak_rt::heap_cons(str_lit("cons"), kayak_rt::heap_cons(str_lit("bloblet_written"), kayak_rt::heap_cons(str_lit("native_procedure0"), kayak_rt::heap_cons(str_lit("native_procedure1"), kayak_rt::heap_cons(str_lit("native_procedure2"), kayak_rt::heap_cons(str_lit("native_procedure3"), kayak_rt::heap_cons(str_lit("native_procedure4"), kayak_rt::nil()))))))))))))))))))))))))))))))
}

/// Whether `n` may be a product's or a sum's label: as a KFX name (C27),
/// but those kayak-rt's functions have, which a Rust field or variant is
/// apart from (`cons`, C116: Fixpt's `convention-types.fx`).
pub fn label_name_p(n: Str) -> bool {
    (kfx_name_p(n) || string_member_p(n, kayak_rt::heap_cons(str_lit("nil"), kayak_rt::heap_cons(str_lit("cons"), kayak_rt::heap_cons(str_lit("once"), kayak_rt::heap_cons(str_lit("alloc"), kayak_rt::heap_cons(str_lit("the"), kayak_rt::heap_cons(str_lit("unwind"), kayak_rt::heap_cons(str_lit("knot"), kayak_rt::heap_cons(str_lit("fail"), kayak_rt::nil()))))))))))
}

// A knot through the store (FX-26's `no_knot`): a procedure kept in
// storage at a region, whose latent effect reads that region and does not
// say `spin`, could be fetched from there by a procedure fetched from
// there, a loop with no recursive call, which only its type shows. The
// regions a type keeps things in: a `ref`'s, a list's not `acyclic`; a
// datatype keeps where its fields do; what a generative type is given, KFX
// takes as kept everywhere, more cautious than FX-26. `res` resolves an
// effect's inference variables.
pub fn region_name_of(r: &'static Ty) -> Str {
    let tagcase_ = r;
    match *tagcase_ {
        Ty::TyVar(n) => {
            n
        }
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyMeta(k) => {
            meta_name(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

pub fn reads_kept(atoms: Strings, kept: Strings, every: bool) -> Strings {
    if string_member_p(str_lit("spin"), atoms) {
        nil::<Str>()
    } else {
        concat(map(lambda1s(move |x: Str| {
            if (has_prefix_p(x, str_lit("read:")) && (string_member_p(after_prefix(x, str_lit("read:")), kept) || (every && not(string_eq_p(after_prefix(x, str_lit("read:")), str_lit("acyclic")))))) {
                the::<Strings>(kayak_rt::heap_cons(after_prefix(x, str_lit("read:")), kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }), atoms))
    }
}

/// The region of a knot `t` ties, kept in `kept` (everywhere, if
/// `every`); or none.
pub fn knot_in(mut v: &'static Cv, mut res: &'static (dyn Fn(Str) -> Str + Send + Sync), mut t: &'static Ty, mut kept: Strings, mut every: bool, mut seen: Strings) -> Strings {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyRef(a, r) => {
                (t, kept) = (a, kayak_rt::heap_cons(region_name_of(r), kept));
                continue;
            }
            Ty::TyList(a, r) => {
                (t, kept) = (a, if (string_eq_p(region_name_of(r), str_lit("acyclic")) || string_eq_p(region_name_of(r), str_lit("%fresh"))) {
                    kept
                } else {
                    kayak_rt::heap_cons(region_name_of(r), kept)
                });
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                let found = reads_kept(map(res, es), kept, every);
                if null_p(found) {
                    return first_knot(v, res, kayak_rt::heap_cons(r, ps), nil::<Str>(), false, seen);
                } else {
                    return found;
                }
            }
            Ty::TyTag(a, h, d, r) => {
                return first_knot(v, res, kayak_rt::heap_cons(a, kayak_rt::heap_cons(h, kayak_rt::nil())), nil::<Str>(), false, seen);
            }
            Ty::TyShape(p, ls, ts) => {
                return first_knot(v, res, ts, kept, every, seen);
            }
            Ty::TyData(d, args) => {
                if ((string_eq_p(d, str_lit("%array")) || string_eq_p(d, str_lit("%icell"))) && i64_eq(size(args), 2i64)) {
                    // An array's elements and an I-cell's value, kept at its region, as
                    // Fixpt's `knot_in` has them (C119: arrays went unchecked before).
                    (t, kept) = (car(args), kayak_rt::heap_cons(region_name_of(car(cdr(args))), kept));
                    continue;
                } else if (string_eq_p(d, str_lit("%bloblet")) && not(null_p(args))) {
                    // A bloblet's fields, kept at its region (C119), as a ref's value.
                    return first_knot(v, res, cdr(args), kayak_rt::heap_cons(region_name_of(car(args)), kept), every, seen);
                } else if string_member_p(d, seen) {
                    return nil::<Str>();
                } else {
                    let found = find_family(d, cv_dts(v));
                    if kayak_rt::value::null_p(found) {
                        return nil::<Str>();
                    } else {
                        let tagcase_ = kayak_rt::value::unbox_other::<&'static Dt>(found);
                        match *tagcase_ {
                            Dt::Dt(n, ps, vs) => {
                                if null_p(vs) {
                                    let down = conversion_bind(string_append(str_lit("down-"), d), cv_binds(v));
                                    return first_knot(v, res, onto(if null_p(down) {
                                        nil::<&'static Ty>()
                                    } else {
                                        let tagcase_ = car(down);
                                        match *tagcase_ {
                                            Bind::Bind(n, sc, w) => {
                                                let tagcase_ = sc;
                                                match *tagcase_ {
                                                    Scheme::Scheme(tvars, t) => {
                                                        let tagcase_ = t;
                                                        match *tagcase_ {
                                                            Ty::TyProc(es, xs, r) => {
                                                                the::<Tys>(kayak_rt::heap_cons(substitute(ps, args, r), kayak_rt::nil()))
                                                            }
                                                            _ => {
                                                                let other = tagcase_;
                                                                nil::<&'static Ty>()
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }, args), kept, true, kayak_rt::heap_cons(d, seen));
                                } else {
                                    return first_knot(v, res, concat(map(lambda1s(move |x: &'static Variant| {
                                        let tagcase_ = x;
                                        match *tagcase_ {
                                            Variant::Variant(tag, fs) => {
                                                map(lambda1s(move |f: &'static Ty| {
                                                    substitute(ps, args, f)
                                                }), fs)
                                            }
                                        }
                                    }), vs)), kept, every, kayak_rt::heap_cons(d, seen));
                                }
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return nil::<Str>();
            }
        }
    }
}

pub fn first_knot(mut v: &'static Cv, mut res: &'static (dyn Fn(Str) -> Str + Send + Sync), mut ts: Tys, mut kept: Strings, mut every: bool, mut seen: Strings) -> Strings {
    loop {
        if null_p(ts) {
            return nil::<Str>();
        } else {
            let found = knot_in(v, res, car(ts), kept, every, seen);
            if null_p(found) {
                ts = cdr(ts);
                continue;
            } else {
                return found;
            }
        }
    }
}

pub fn no_knot(v: &'static Cv, res: &'static (dyn Fn(Str) -> Str + Send + Sync), t: &'static Ty) -> &'static Ty {
    let found = knot_in(v, res, t, nil::<Str>(), false, nil::<Str>());
    if null_p(found) {
        t
    } else {
        match refuse(v, string_append(str_lit("a procedure kept in "), string_append(car(found), string_append(str_lit(" reads "), string_append(car(found), str_lit(", so it could reach itself: it must say spin")))))) {}
    }
}

// Flats (C31): what a blobref points to, raw bytes in a bloblet's suffix,
// laid out as C lays them out: a scalar at its size, a product's fields in
// order each at its alignment and the whole padded to the widest, an
// array's elements one after another. KFX's scalars are FX-26's but `f32`,
// which KFX has not yet.
pub fn run_together(xs: Strings) -> Str {
    if null_p(xs) {
        str_lit("")
    } else {
        string_append(car(xs), run_together(cdr(xs)))
    }
}

pub fn key_range(key: Str) -> i64 {
    if string_eq_p(key, str_lit("u8")) {
        256i64
    } else if string_eq_p(key, str_lit("u16")) {
        65536i64
    } else {
        4294967296i64
    }
}

pub fn key_width(k: &'static Ty) -> i64 {
    let tagcase_ = k;
    match *tagcase_ {
        Ty::TyRconst(n) => {
            if string_eq_p(n, str_lit("u8")) {
                1i64
            } else if string_eq_p(n, str_lit("u16")) {
                2i64
            } else {
                4i64
            }
        }
        _ => {
            let other = tagcase_;
            4i64
        }
    }
}

pub enum Fvar {
    Fvar(Str, &'static Ty),
}

pub fn fvar(f0: Str, f1: &'static Ty) -> &'static Fvar {
    kayak_rt::heap_alloc(Fvar::Fvar(f0, f1))
}

pub type Fvars = List<&'static Fvar>;

pub fn fvars_of(ts: Tys) -> Fvars {
    if (null_p(ts) || null_p(cdr(ts))) {
        nil::<&'static Fvar>()
    } else {
        kayak_rt::heap_cons(fvar({
            let tagcase_ = car(ts);
            match *tagcase_ {
                Ty::TyRconst(n) => {
                    n
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, car(cdr(ts))), fvars_of(cdr(cdr(ts))))
    }
}

/// A keyed flat sum's variants, its type's arguments after the key.
pub fn flat_sum_variants(args: Tys) -> Fvars {
    fvars_of(cdr(args))
}

pub fn flat_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            true
        }
        Ty::TyF64() => {
            true
        }
        Ty::TyData(d, args) => {
            ((null_p(args) && (string_eq_p(d, str_lit("i32")) || string_eq_p(d, str_lit("u32")) || string_eq_p(d, str_lit("u64")) || string_eq_p(d, str_lit("f32")))) || (string_eq_p(d, str_lit("%flat-array")) && flat_p(car(args))) || (has_prefix_p(d, str_lit("%named ")) && flat_p(car(args))) || string_eq_p(d, str_lit("%flat-sum")))
        }
        Ty::TyShape(p, ls, ts) => {
            (p && not(null_p(ts)) && not(any_p(lambda1s(move |x: &'static Ty| {
                not(flat_p(x))
            }), ts)))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub enum Layout {
    Layout(i64, i64),
}

pub fn layout(f0: i64, f1: i64) -> &'static Layout {
    kayak_rt::heap_alloc(Layout::Layout(f0, f1))
}

pub fn round_up(n: i64, a: i64) -> i64 {
    i64_star(i64_quotient(i64_plus(n, i64_minus(a, 1i64)), a), a)
}

/// A flat's size and alignment, in bytes.
pub fn flat_layout(t: &'static Ty) -> &'static Layout {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%flat-array")) {
                let tagcase_ = flat_layout(car(args));
                match *tagcase_ {
                    Layout::Layout(size, align) => {
                        layout(i64_star(size, {
                            let tagcase_ = car(cdr(args));
                            match *tagcase_ {
                                Ty::TyRconst(n) => {
                                    i64_minus(0i64, digits_value(string_chars(n), 0i64, str_lit(""), 0i64))
                                }
                                _ => {
                                    let other = tagcase_;
                                    0i64
                                }
                            }
                        }), align)
                    }
                }
            } else if string_eq_p(d, str_lit("u64")) {
                layout(8i64, 8i64)
            } else if string_eq_p(d, str_lit("%flat-sum")) {
                let k = key_width(car(args));
                let vs = flat_sum_variants(args);
                let widest = any_layout(map(lambda1s(move |f: &'static Fvar| {
                    let tagcase_ = f;
                    match *tagcase_ {
                        Fvar::Fvar(l, x) => {
                            x
                        }
                    }
                }), vs), 0i64, 1i64);
                let tagcase_ = widest;
                match *tagcase_ {
                    Layout::Layout(size, align) => {
                        let (at, whole) = (round_up(k, align), if i64_gt(align, k) {
                            align
                        } else {
                            k
                        });
                        layout(round_up(i64_plus(at, size), whole), whole)
                    }
                }
            } else {
                layout(4i64, 4i64)
            }
        }
        Ty::TyShape(p, ls, ts) => {
            let tagcase_ = fields_layout(ts, 0i64, 1i64);
            match *tagcase_ {
                Layout::Layout(end, align) => {
                    layout(round_up(end, align), align)
                }
            }
        }
        _ => {
            let other = tagcase_;
            layout(8i64, 8i64)
        }
    }
}

/// The widest of flats `ts` and their widest alignment: a sum's variant's room.
pub fn any_layout(mut ts: Tys, mut size: i64, mut align: i64) -> &'static Layout {
    loop {
        if null_p(ts) {
            return layout(size, align);
        } else {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(s, a) => {
                    (ts, size, align) = (cdr(ts), if i64_gt(s, size) {
                        s
                    } else {
                        size
                    }, if i64_gt(a, align) {
                        a
                    } else {
                        align
                    });
                    continue;
                }
            }
        }
    }
}

/// The end of fields `ts` laid out from `at`, and their widest alignment.
pub fn fields_layout(mut ts: Tys, mut at: i64, mut align: i64) -> &'static Layout {
    loop {
        if null_p(ts) {
            return layout(at, align);
        } else {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(size, a) => {
                    (ts, at, align) = (cdr(ts), i64_plus(round_up(at, a), size), if i64_gt(a, align) {
                        a
                    } else {
                        align
                    });
                    continue;
                }
            }
        }
    }
}

/// Where a keyed flat sum's variant begins: after its tag, at the widest
/// variant's alignment.
pub fn variant_offset(args: Tys) -> i64 {
    let tagcase_ = any_layout(map(lambda1s(move |f: &'static Fvar| {
        let tagcase_ = f;
        match *tagcase_ {
            Fvar::Fvar(l, x) => {
                x
            }
        }
    }), flat_sum_variants(args)), 0i64, 1i64);
    match *tagcase_ {
        Layout::Layout(size, align) => {
            round_up(key_width(car(args)), align)
        }
    }
}

/// The offset of a flat product's field `l`.
pub fn field_offset(ls: Strings, ts: Tys, l: Str) -> i64 {
    let go__knot = knot::<&'static (dyn Fn(Strings, Tys, i64) -> i64 + Send + Sync)>();
    let go = lambda3s(move |mut ls: Strings, mut ts: Tys, mut at: i64| {
        loop {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(size, a) => {
                    if string_eq_p(car(ls), l) {
                        return round_up(at, a);
                    } else {
                        (ls, ts, at) = (cdr(ls), cdr(ts), i64_plus(round_up(at, a), size));
                        continue;
                    }
                }
            }
        }
    });
    go__knot.set(go);
    go(ls, ts, 0i64)
}

/// A flat scalar's name, as its blobref's read and write are named; or ``.
pub fn scalar_name(t: &'static Ty) -> Str {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("i64")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyData(d, args) => {
            if null_p(args) {
                d
            } else {
                str_lit("")
            }
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// FX-26's fixed-width integers beside `i64` (`u8` and `i8` since Fixpt 17ac0c5), whose arithmetic wraps: a type
/// named so, as a datatype is, of no variants; in Rust, Rust's.
pub fn fixed_width_p(s: Str) -> bool {
    (string_eq_p(s, str_lit("i32")) || string_eq_p(s, str_lit("u32")) || string_eq_p(s, str_lit("u64")) || string_eq_p(s, str_lit("u8")) || string_eq_p(s, str_lit("i8")))
}

// Unions of shapes (C62; FX-26's, docs/fx26.md "Unions of shapes"): a
// value of any of its members, whose shapes at run time differ, so that a
// test tells them apart. A `(ty-data "%union" members)`, flattened, each
// member once; `false`, the type of `#f` alone, below `bool`, a
// `(ty-data "false" nil)`. Never Rust's (C57): the restriction pass's.
/// A member's shape at run time, or `` if it has none known.
pub fn shape_of(t: &'static Ty) -> Str {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("int")
        }
        Ty::TyInt() => {
            str_lit("int")
        }
        Ty::TyNat() => {
            str_lit("int")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyChar() => {
            str_lit("char")
        }
        Ty::TyBool() => {
            str_lit("bool")
        }
        Ty::TyString() => {
            str_lit("string")
        }
        Ty::TyUnit() => {
            str_lit("symbol")
        }
        Ty::TyList(e, r) => {
            str_lit("list")
        }
        Ty::TyProc(es, ps, r) => {
            str_lit("procedure")
        }
        Ty::TyRef(e, r) => {
            str_lit("box")
        }
        Ty::TyFlat(e, r) => {
            str_lit("bloblet")
        }
        Ty::TyShape(p, ls, ts) => {
            if p {
                str_lit("product")
            } else {
                str_lit("sum")
            }
        }
        Ty::TyData(d, args) => {
            if (string_eq_p(d, str_lit("i32")) || string_eq_p(d, str_lit("u32")) || string_eq_p(d, str_lit("u64")) || string_eq_p(d, str_lit("u8")) || string_eq_p(d, str_lit("i8"))) {
                str_lit("int")
            } else if string_eq_p(d, str_lit("f32")) {
                str_lit("f32")
            } else if string_eq_p(d, str_lit("false")) {
                str_lit("bool")
            } else if string_eq_p(d, str_lit("nil")) {
                str_lit("nil")
            } else if string_eq_p(d, str_lit("%pairof")) {
                str_lit("pair")
            } else if string_eq_p(d, str_lit("symbol")) {
                str_lit("symbol")
            } else if string_eq_p(d, str_lit("%array")) {
                str_lit("bloblet")
            } else if string_eq_p(d, str_lit("%bytes")) {
                str_lit("bytevector")
            } else if string_eq_p(d, str_lit("%union")) {
                str_lit("union")
            } else if string_eq_p(d, str_lit("datum")) {
                str_lit("union")
            } else if string_eq_p(d, str_lit("vector")) {
                str_lit("vector")
            } else if (has_prefix_p(d, str_lit("%")) || has_char_in_p(d, '.') || has_char_in_p(d, ' ')) {
                str_lit("")
            } else {
                // A datatype's value (C84): FX-26's shape `sum`. A generative
                // type is named so too, which a union's parse refuses.
                str_lit("sum")
            }
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// Members flattened: a union in a union is its members.
pub fn union_members(ts: Tys) -> Tys {
    if null_p(ts) {
        nil::<&'static Ty>()
    } else {
        let tagcase_ = car(ts);
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if string_eq_p(d, str_lit("%union")) {
                    onto(union_members(args), union_members(cdr(ts)))
                } else {
                    kayak_rt::heap_cons(car(ts), union_members(cdr(ts)))
                }
            }
            _ => {
                let other = tagcase_;
                kayak_rt::heap_cons(car(ts), union_members(cdr(ts)))
            }
        }
    }
}

// `datum` (C77), FX-26's union of what a reader reads, `(union int f64
// char bool string symbol nil (pairof datum datum acyclic) vector)`: a
// name, its members found when they are wanted, since it mentions itself.
// FX-26's has `bytevector` too, which KFX's has not yet.
pub fn datum_members() -> Tys {
    kayak_rt::heap_cons(ty_int(), kayak_rt::heap_cons(ty_f64(), kayak_rt::heap_cons(ty_char(), kayak_rt::heap_cons(ty_bool(), kayak_rt::heap_cons(ty_string(), kayak_rt::heap_cons(ty_data(str_lit("symbol"), nil::<&'static Ty>()), kayak_rt::heap_cons(ty_data(str_lit("nil"), nil::<&'static Ty>()), kayak_rt::heap_cons(ty_data(str_lit("%pairof"), kayak_rt::heap_cons(ty_data(str_lit("datum"), nil::<&'static Ty>()), kayak_rt::heap_cons(ty_data(str_lit("datum"), nil::<&'static Ty>()), kayak_rt::heap_cons(ty_rconst(str_lit("acyclic")), kayak_rt::nil())))), kayak_rt::heap_cons(ty_data(str_lit("vector"), nil::<&'static Ty>()), kayak_rt::nil())))))))))
}

/// A union's members; `datum`'s; or none.
pub fn members_of(t: &'static Ty) -> Tys {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%union")) {
                args
            } else if string_eq_p(d, str_lit("datum")) {
                datum_members()
            } else {
                nil::<&'static Ty>()
            }
        }
        _ => {
            let other = tagcase_;
            nil::<&'static Ty>()
        }
    }
}

/// A generative type: among the datatypes, with no variants; its shape
/// is its representation's, which FX-26 keeps unknown (C84).
pub fn generative_p(v: &'static Cv, t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            let found = find_family(d, cv_dts(v));
            if kayak_rt::value::null_p(found) {
                false
            } else {
                let tagcase_ = kayak_rt::value::unbox_other::<&'static Dt>(found);
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        null_p(vs)
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn member_of_shape(mut ts: Tys, mut shape: Str) -> Tys {
    loop {
        if null_p(ts) {
            return nil::<&'static Ty>();
        } else if string_eq_p(shape_of(car(ts)), shape) {
            return kayak_rt::heap_cons(car(ts), kayak_rt::nil());
        } else {
            ts = cdr(ts);
            continue;
        }
    }
}

// Sizes' facts (C157; Fixpt's `sizes.rs`, `check-test-facts.fx`, N5b, N5c):
// a linear expression over local names, a constant and each name's
// coefficient; a fact that one is `= 0`, `>= 0`, or `/= 0`, learned in a
// branch of a test, kept in the environment as a binding of no name a
// program writes, `wher` `fact KIND C N K ...`.
pub enum Lterm {
    Lterm(Str, i64),
}

pub fn lterm(f0: Str, f1: i64) -> &'static Lterm {
    kayak_rt::heap_alloc(Lterm::Lterm(f0, f1))
}

pub enum Lin {
    Lin(i64, List<&'static Lterm>),
}

pub fn lin(f0: i64, f1: List<&'static Lterm>) -> &'static Lin {
    kayak_rt::heap_alloc(Lin::Lin(f0, f1))
}

pub type Lins = List<&'static Lin>;

pub fn lterms_added(ts: List<&'static Lterm>, n: Str, k: i64) -> List<&'static Lterm> {
    if null_p(ts) {
        if i64_eq(k, 0i64) {
            nil::<&'static Lterm>()
        } else {
            kayak_rt::heap_cons(lterm(n, k), kayak_rt::nil())
        }
    } else if {
        let tagcase_ = car(ts);
        match *tagcase_ {
            Lterm::Lterm(m, j) => {
                string_eq_p(m, n)
            }
        }
    } {
        let tagcase_ = car(ts);
        match *tagcase_ {
            Lterm::Lterm(m, j) => {
                if i64_eq(i64_plus(j, k), 0i64) {
                    cdr(ts)
                } else {
                    kayak_rt::heap_cons(lterm(m, i64_plus(j, k)), cdr(ts))
                }
            }
        }
    } else {
        kayak_rt::heap_cons(car(ts), lterms_added(cdr(ts), n, k))
    }
}

pub fn lin_terms_onto(mut ts: List<&'static Lterm>, mut acc: List<&'static Lterm>, mut k: i64) -> List<&'static Lterm> {
    loop {
        if null_p(ts) {
            return acc;
        } else {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Lterm::Lterm(n, j) => {
                    (ts, acc) = (cdr(ts), lterms_added(acc, n, i64_star(j, k)));
                    continue;
                }
            }
        }
    }
}

/// `a + k b`.
pub fn lin_add(a: &'static Lin, b: &'static Lin, k: i64) -> &'static Lin {
    let tagcase_ = a;
    match *tagcase_ {
        Lin::Lin(ca, ta) => {
            let tagcase_ = b;
            match *tagcase_ {
                Lin::Lin(cb, tb) => {
                    lin(i64_plus(ca, i64_star(k, cb)), lin_terms_onto(tb, ta, k))
                }
            }
        }
    }
}

pub fn lin_scaled(a: &'static Lin, k: i64) -> &'static Lin {
    lin_add(lin(0i64, nil::<&'static Lterm>()), a, k)
}

pub fn lin_coef(a: &'static Lin, n: Str) -> i64 {
    let tagcase_ = a;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            let found = filter(lambda1s(move |t: &'static Lterm| {
                let tagcase_ = t;
                match *tagcase_ {
                    Lterm::Lterm(m, j) => {
                        string_eq_p(m, n)
                    }
                }
            }), ts);
            if null_p(found) {
                0i64
            } else {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Lterm::Lterm(m, j) => {
                        j
                    }
                }
            }
        }
    }
}

pub fn lin_names(a: &'static Lin) -> Strings {
    let tagcase_ = a;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            map(lambda1s(move |t: &'static Lterm| {
                let tagcase_ = t;
                match *tagcase_ {
                    Lterm::Lterm(n, j) => {
                        n
                    }
                }
            }), ts)
        }
    }
}

pub fn lin_text(a: &'static Lin) -> Str {
    let tagcase_ = a;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            words_of(kayak_rt::heap_cons(i64_to_string(c), concat(map(lambda1s(move |t: &'static Lterm| {
                let tagcase_ = t;
                match *tagcase_ {
                    Lterm::Lterm(n, j) => {
                        the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::heap_cons(i64_to_string(j), kayak_rt::nil())))
                    }
                }
            }), ts))))
        }
    }
}

pub fn digits_i64_of(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            (cs, n) = (cdr(cs), i64_plus(i64_star(n, 10i64), i64_minus(char_to_i64(car(cs)), 48i64)));
            continue;
        }
    }
}

pub fn string_to_i64(t: Str) -> i64 {
    let cs = string_chars(t);
    if (not(null_p(cs)) && char_eq_p(car(cs), '-')) {
        i64_minus(0i64, digits_i64_of(cdr(cs), 0i64))
    } else {
        digits_i64_of(cs, 0i64)
    }
}

pub fn fact_words_from(mut cs: Chars, mut w: Chars, mut acc: Strings) -> Strings {
    loop {
        if null_p(cs) {
            return reverse(if null_p(w) {
                acc
            } else {
                the::<Strings>(kayak_rt::heap_cons(list_to_string(reverse(w)), acc))
            });
        } else if char_eq_p(car(cs), ' ') {
            (cs, w, acc) = (cdr(cs), nil::<char>(), if null_p(w) {
                acc
            } else {
                the::<Strings>(kayak_rt::heap_cons(list_to_string(reverse(w)), acc))
            });
            continue;
        } else {
            (cs, w) = (cdr(cs), kayak_rt::heap_cons(car(cs), w));
            continue;
        }
    }
}

pub fn text_words(t: Str) -> Strings {
    fact_words_from(string_chars(t), nil::<char>(), nil::<Str>())
}

pub fn second_word(ws: Strings) -> Str {
    car(cdr(ws))
}

pub fn lterms_read(ws: Strings) -> List<&'static Lterm> {
    if (null_p(ws) || null_p(cdr(ws))) {
        nil::<&'static Lterm>()
    } else {
        kayak_rt::heap_cons(lterm(car(ws), string_to_i64(second_word(ws))), lterms_read(cdr(cdr(ws))))
    }
}

pub fn lin_read(ws: Strings) -> &'static Lin {
    lin(string_to_i64(car(ws)), lterms_read(cdr(ws)))
}

// Whether inequalities `ls`, each `l >= 0`, have no solution, by
// Fourier-Motzkin elimination over the rationals: sound for the integers,
// not complete. Too many, and the answer is that they may have one.
pub fn no_solution_p(mut ls: Lins, mut budget: i64) -> bool {
    loop {
        if i64_gt(size(ls), 400i64) {
            return false;
        } else if any_p(lambda1s(move |l: &'static Lin| {
            let tagcase_ = l;
            match *tagcase_ {
                Lin::Lin(c, ts) => {
                    (null_p(ts) && i64_lt(c, 0i64))
                }
            }
        }), ls) {
            return true;
        } else {
            let open = filter(lambda1s(move |l: &'static Lin| {
                let tagcase_ = l;
                match *tagcase_ {
                    Lin::Lin(c, ts) => {
                        not(null_p(ts))
                    }
                }
            }), ls);
            if (null_p(open) || i64_lt_eq(budget, 0i64)) {
                return false;
            } else {
                let x = car(lin_names(car(open)));
                let pos = filter(lambda1s(move |l: &'static Lin| {
                    i64_gt(lin_coef(l, x), 0i64)
                }), open);
                let neg = filter(lambda1s(move |l: &'static Lin| {
                    i64_lt(lin_coef(l, x), 0i64)
                }), open);
                let rest = filter(lambda1s(move |l: &'static Lin| {
                    i64_eq(lin_coef(l, x), 0i64)
                }), open);
                (ls, budget) = (onto(rest, concat(map(lambda1s(move |p: &'static Lin| {
                    map(lambda1s(move |q: &'static Lin| {
                        lin_add(lin_scaled(p, i64_minus(0i64, lin_coef(q, x))), q, lin_coef(p, x))
                    }), neg)
                }), pos))), i64_minus(budget, 1i64));
                continue;
            }
        }
    }
}

/// Whether facts `ges` (each `>= 0`) and `nes` (each `/= 0`, split into
/// `>= 1` and `<= -1`) show `goal >= 0`.
pub fn lin_shown_p(ges: Lins, nes: Lins, goal: &'static Lin) -> bool {
    if null_p(nes) {
        no_solution_p(kayak_rt::heap_cons(lin_add(lin(-1i64, nil::<&'static Lterm>()), goal, -1i64), ges), 64i64)
    } else {
        (lin_shown_p(kayak_rt::heap_cons(lin_add(car(nes), lin(-1i64, nil::<&'static Lterm>()), 1i64), ges), cdr(nes), goal) && lin_shown_p(kayak_rt::heap_cons(lin_add(lin(-1i64, nil::<&'static Lterm>()), car(nes), -1i64), ges), cdr(nes), goal))
    }
}

// Sizes in types (C158; Fixpt's `docs/research/sizes.md`): a size is
// `finite`, the top, some size not known; a size variable, a binder of
// kind `size` (`#n`) or an inference variable; or a linear one, a constant
// and each variable's coefficient: `(ty-data "%sz" (k t ...))`, `k` its
// constant (`%k C`) and each `t` a variable times its coefficient (`%t
// K`), so that instantiating and solving see the variables. `(nat s)` is
// `%natof`, `nat` itself `(nat finite)`; `(nlist T s)`, a list of
// exactly `s` elements, frozen, `%nlist`.
pub fn size_finite() -> &'static Ty {
    ty_data(str_lit("%finite"), nil::<&'static Ty>())
}

pub fn size_term_var(n: Str) -> &'static Ty {
    if has_prefix_p(n, str_lit("?")) {
        ty_meta(string_to_i64(after_prefix(n, str_lit("?"))))
    } else {
        ty_var(n)
    }
}

pub fn size_of_lin(l: &'static Lin) -> &'static Ty {
    let tagcase_ = l;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            if (i64_eq(c, 0i64) && not(null_p(ts)) && null_p(cdr(ts)) && {
                let tagcase_ = car(ts);
                match *tagcase_ {
                    Lterm::Lterm(n, k) => {
                        i64_eq(k, 1i64)
                    }
                }
            }) {
                let tagcase_ = car(ts);
                match *tagcase_ {
                    Lterm::Lterm(n, k) => {
                        size_term_var(n)
                    }
                }
            } else {
                ty_data(str_lit("%sz"), kayak_rt::heap_cons(ty_data(string_append(str_lit("%k "), i64_to_string(c)), nil::<&'static Ty>()), map(lambda1s(move |t: &'static Lterm| {
                    let tagcase_ = t;
                    match *tagcase_ {
                        Lterm::Lterm(n, k) => {
                            ty_data(string_append(str_lit("%t "), i64_to_string(k)), kayak_rt::heap_cons(size_term_var(n), kayak_rt::nil()))
                        }
                    }
                }), ts)))
            }
        }
    }
}

/// A size as written (C158), as a linear expression; none for `finite`: a
/// literal, `finite`, a size variable, `(+ s ...)`, `(- s k)`.
pub fn parse_size_lin(v: &'static Cv, tvars: Strings, z: &'static Sexp) -> Lins {
    let tagcase_ = z;
    match *tagcase_ {
        Sexp::Num(k, f, p) => {
            if i64_lt(k, 0i64) {
                match refuse(v, str_lit("a size is never negative")) {}
            } else {
                kayak_rt::heap_cons(lin(k, nil::<&'static Lterm>()), kayak_rt::nil())
            }
        }
        Sexp::Sym(n, f, p) => {
            if string_eq_p(n, str_lit("finite")) {
                nil::<&'static Lin>()
            } else if string_member_p(string_append(str_lit("#"), n), tvars) {
                kayak_rt::heap_cons(lin(0i64, kayak_rt::heap_cons(lterm(string_append(str_lit("#"), n), 1i64), kayak_rt::nil())), kayak_rt::nil())
            } else {
                match refuse(v, string_append(str_lit("a size: a natural, finite, a size variable, (+ s ...), (- s k): "), n)) {}
            }
        }
        Sexp::Lst(xs, f, l, p) => {
            if (sym_is_p(car(xs), str_lit("+")) && not(null_p(cdr(xs)))) {
                sizes_summed(v, tvars, cdr(xs), lin(0i64, nil::<&'static Lterm>()))
            } else if (sym_is_p(car(xs), str_lit("-")) && i64_eq(size(xs), 3i64) && {
                let tagcase_ = third(xs);
                match *tagcase_ {
                    Sexp::Num(k, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let a = parse_size_lin(v, tvars, second(xs));
                if null_p(a) {
                    nil::<&'static Lin>()
                } else {
                    kayak_rt::heap_cons(lin_add(car(a), lin({
                        let tagcase_ = third(xs);
                        match *tagcase_ {
                            Sexp::Num(k, f2, p2) => {
                                k
                            }
                            _ => {
                                let other = tagcase_;
                                0i64
                            }
                        }
                    }, nil::<&'static Lterm>()), -1i64), kayak_rt::nil())
                }
            } else {
                match refuse(v, string_append(str_lit("a size: a natural, finite, a size variable, (+ s ...), (- s k): "), show_sexp(z))) {}
            }
        }
        _ => {
            let other = tagcase_;
            match refuse(v, str_lit("a size: a natural, finite, a size variable, (+ s ...), (- s k)")) {}
        }
    }
}

pub fn sizes_summed(mut v: &'static Cv, mut tvars: Strings, mut zs: Sexps, mut acc: &'static Lin) -> Lins {
    loop {
        if null_p(zs) {
            return kayak_rt::heap_cons(acc, kayak_rt::nil());
        } else {
            let l = parse_size_lin(v, tvars, car(zs));
            if null_p(l) {
                return nil::<&'static Lin>();
            } else {
                (zs, acc) = (cdr(zs), lin_add(acc, car(l), 1i64));
                continue;
            }
        }
    }
}

pub fn parse_size(v: &'static Cv, tvars: Strings, z: &'static Sexp) -> &'static Ty {
    let l = parse_size_lin(v, tvars, z);
    if null_p(l) {
        size_finite()
    } else {
        size_of_lin(car(l))
    }
}

// Specifications (C162; Fixpt's `check-specs.fx`, `check-logic.fx`): a
// procedure type's `(subr E ((x T) ...) R (requires P) (ensures r Q))`,
// propositions of its `int`s, `nat`s and `bool`s, and of `pure` global
// procedures' values. FX-26's checker reads them, prints them, and holds a
// procedure to the one its type expected (behavioural subtyping, by a
// prover); it proves no body. A specified type is its procedure's, wrapped:
// `(ty-data "%spec TEXT" (P))`, `TEXT` the specification written plainly,
// `(spec (NAME ...) RESULT REQUIRES ENSURES)`, each name `%none` where a
// parameter has none; an integer `(lit k)`, `(p i)` (parameter `i`),
// `(res)`, `(add a b)`, `(sub a b)`, `(mul a b)`, `(call f a ...)`; a
// proposition `(true)`, `(false)`, `(rel R a b)` (0 `<`, 1 `<=`, 2 `=`, 3
// not `=`), `(holds a)`, `(not p)`, `(and p ...)`, `(or p ...)`,
// `(implies p q)`.
pub enum Sname {
    Sname(Str, Str, &'static Ty),
}

pub fn sname(f0: Str, f1: Str, f2: &'static Ty) -> &'static Sname {
    kayak_rt::heap_alloc(Sname::Sname(f0, f1, f2))
}

pub type Snames = List<&'static Sname>;

