/// A moduleof's items, each seeing the types and effects before it; an
/// abstract type `ID..t`.
pub fn parse_moduleof(v: &'static Cv, tvars: Strings, its: Sexps, id: Str) -> Tys {
    if null_p(its) {
        nil::<&'static Ty>()
    } else {
        let x = car(its);
        let ys = items(x);
        let hd = logic_head(x);
        let n = if (i64_eq(size(ys), 3i64) && {
            let tagcase_ = second(ys);
            match *tagcase_ {
                Sexp::Sym(m, f, p) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }) {
            sym_name(second(ys))
        } else {
            str_lit("")
        };
        if (string_eq_p(hd, str_lit("abs")) && i64_eq(size(ys), 3i64) && sym_is_p(third(ys), str_lit("type"))) {
            let names = {
                let tagcase_ = second(ys);
                match *tagcase_ {
                    Sexp::Sym(m, f, p) => {
                        the::<Strings>(kayak_rt::heap_cons(m, kayak_rt::nil()))
                    }
                    Sexp::Lst(ns, f, l, p) => {
                        map(&sym_name, ns)
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            };
            onto(map(lambda1s(move |m: Str| {
                ty_data(string_append(str_lit("%abs "), m), kayak_rt::heap_cons(ty_data(string_append(id, string_append(str_lit(".."), m)), nil::<&'static Ty>()), kayak_rt::nil()))
            }), names), parse_moduleof(with_type_binds(v, map(lambda1s(move |m: Str| {
                type_bind(m, ty_data(string_append(id, string_append(str_lit(".."), m)), nil::<&'static Ty>()))
            }), names), nil::<&'static Effdef>()), tvars, cdr(its), id))
        } else if (string_eq_p(hd, str_lit("desc")) && not(string_eq_p(n, str_lit(""))) && effect_written_p(v, third(ys))) {
            let atoms = parse_effect(v, tvars, third(ys));
            kayak_rt::heap_cons(ty_data(string_append(str_lit("%edesc "), n), kayak_rt::heap_cons(ty_proc(atoms, nil::<&'static Ty>(), ty_unit()), kayak_rt::nil())), parse_moduleof(with_type_binds(v, nil::<&'static Bind>(), kayak_rt::heap_cons(effdef(n, atoms), kayak_rt::nil())), tvars, cdr(its), id))
        } else if (string_eq_p(hd, str_lit("desc")) && not(string_eq_p(n, str_lit("")))) {
            let u = parse_type(v, tvars, third(ys));
            kayak_rt::heap_cons(ty_data(string_append(str_lit("%desc "), n), kayak_rt::heap_cons(u, kayak_rt::nil())), parse_moduleof(with_type_binds(v, kayak_rt::heap_cons(type_bind(n, u), kayak_rt::nil()), nil::<&'static Effdef>()), tvars, cdr(its), id))
        } else if (string_eq_p(hd, str_lit("val")) && not(string_eq_p(n, str_lit("")))) {
            kayak_rt::heap_cons(ty_data(string_append(str_lit("%val "), n), kayak_rt::heap_cons(parse_type(v, tvars, third(ys)), kayak_rt::nil())), parse_moduleof(v, tvars, cdr(its), id))
        } else {
            match refuse(v, string_append(str_lit("a module type's item KFX does not have: "), show_sexp(x))) {}
        }
    }
}

pub fn parse_types(v: &'static Cv, tvars: Strings, ts: Sexps) -> Tys {
    map(lambda1s(move |t: &'static Sexp| {
        parse_type(v, tvars, t)
    }), ts)
}

/// Where a procedure type's parameters after a module parameter named,
/// and its result, are read (a dependent procedure, C170; Fixpt's M5):
/// that parameter's types `(select m t)` are the `i`th parameter's,
/// `$i..t`, its argument's at a call.
pub fn dep_scope(mut v: &'static Cv, mut tvars: Strings, mut ps: Sexps, mut i: i64) -> &'static Cv {
    loop {
        if null_p(ps) {
            return v;
        } else {
            let n = param_name_written(v, tvars, car(ps));
            if string_eq_p(n, str_lit("")) {
                (ps, i) = (cdr(ps), i64_plus(i, 1i64));
                continue;
            } else {
                let t = as_mtype(v, parse_type(v, tvars, param_type_written(v, tvars, car(ps))));
                (v, ps, i) = (if mtype_p(t) {
                    with_type_binds(v, kayak_rt::heap_cons(bind(n, scheme(nil::<Str>(), mtype_named(string_append(str_lit("$"), i64_to_string(i)), t)), str_lit("local")), kayak_rt::nil()), nil::<&'static Effdef>())
                } else {
                    v
                }, cdr(ps), i64_plus(i, 1i64));
                continue;
            }
        }
    }
}

/// A module type named by a `define-type` (C24), as a module value's.
pub fn as_mtype(v: &'static Cv, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if has_prefix_p(d, str_lit("%module ")) {
                let found = find_alias(after_prefix(d, str_lit("%module ")), cv_aliases(v));
                if null_p(found) {
                    t
                } else {
                    let tagcase_ = car(found);
                    match *tagcase_ {
                        Alias::Alias(n, ps, body) => {
                            parse_type(v, nil::<Str>(), body)
                        }
                    }
                }
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// A procedure type's parameters, each named or not (C162).
pub fn parse_params(v: &'static Cv, tvars: Strings, ts: Sexps) -> Tys {
    map(lambda1s(move |t: &'static Sexp| {
        parse_type(v, tvars, param_type_written(v, tvars, t))
    }), ts)
}

/// A family's arguments, each read as its parameter's kind says: a
/// region for a name beginning `'`, a type otherwise.
pub fn parse_arguments(v: &'static Cv, tvars: Strings, params: Strings, args: Sexps) -> Tys {
    if (null_p(params) && null_p(args)) {
        nil::<&'static Ty>()
    } else if (null_p(params) || null_p(args)) {
        match refuse(v, str_lit("a type given the wrong number of arguments")) {}
    } else {
        kayak_rt::heap_cons(if char_eq_p(string_ref_i64(car(params), 0i64), '\'') {
            parse_region(v, tvars, car(args))
        } else if char_eq_p(string_ref_i64(car(params), 0i64), '~') {
            // An effect argument (C46): a row, its atoms, and `~!`, which
            // says the procedures there are of an effect binder's, and so
            // are in Rust as the family's own are, whatever is given.
            effect_row(kayak_rt::heap_cons(str_lit("~!"), parse_effect(v, tvars, car(args))))
        } else {
            parse_type(v, tvars, car(args))
        }, parse_arguments(v, tvars, cdr(params), cdr(args)))
    }
}

/// The `(select m u)` an abbreviation with no parameters stands for,
/// through others with none (a module's `t` is its `m..t`, C119); or
/// none.
pub fn select_behind(mut v: &'static Cv, mut name: Str, mut depth: i64) -> Sexps {
    loop {
        let named = find_alias(name, cv_aliases(v));
        if (null_p(named) || i64_gt(depth, 16i64)) {
            return nil::<&'static Sexp>();
        } else {
            let tagcase_ = car(named);
            match *tagcase_ {
                Alias::Alias(n, ps, body) => {
                    if not(null_p(ps)) {
                        return nil::<&'static Sexp>();
                    } else if head_is_p(body, str_lit("select")) {
                        return the::<Sexps>(kayak_rt::heap_cons(body, kayak_rt::nil()));
                    } else {
                        let tagcase_ = body;
                        match *tagcase_ {
                            Sexp::Sym(m, f, p) => {
                                (name, depth) = (m, i64_plus(depth, 1i64));
                                continue;
                            }
                            _ => {
                                let other = tagcase_;
                                return nil::<&'static Sexp>();
                            }
                        }
                    }
                }
            }
        }
    }
}

/// `(name arg ...)`: a datatype with parameters, applied; or a type
/// abbreviation with them, what it stands for with its arguments; or an
/// abbreviation of a module's family, `(define-type t (select m u))`,
/// that family applied (C89).
pub fn parse_application(v: &'static Cv, tvars: Strings, name: Str, args: Sexps) -> &'static Ty {
    let found = find_family(name, cv_dts(v));
    let behind = if kayak_rt::value::null_p(found) {
        select_behind(v, name, 0i64)
    } else {
        nil::<&'static Sexp>()
    };
    if not(null_p(behind)) {
        parse_type(v, tvars, lst(kayak_rt::heap_cons(car(behind), args), str_lit(""), 0i64, 0i64))
    } else {
        if not(kayak_rt::value::null_p(found)) {
            let tagcase_ = kayak_rt::value::unbox_other::<&'static Dt>(found);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    ty_data(name, parse_arguments(v, tvars, ps, args))
                }
            }
        } else {
            let tagcase_ = car(find_alias(name, cv_aliases(v)));
            match *tagcase_ {
                Alias::Alias(n, ps, body) => {
                    if string_member_p(string_append(str_lit("%expanding "), name), tvars) {
                        match refuse(v, string_append(str_lit("a type abbreviation that mentions itself, "), string_append(name, str_lit(": Rust's type aliases cannot; a datatype can")))) {}
                    } else {
                        substitute(ps, parse_arguments(v, tvars, ps, args), parse_type(v, kayak_rt::heap_cons(string_append(str_lit("%expanding "), name), onto(map(lambda1s(move |p: Str| {
                            string_append(str_lit("%place "), p)
                        }), concat(map(lambda1s(move |p: Str| {
                            if has_prefix_p(p, str_lit("'")) {
                                the::<Strings>(kayak_rt::heap_cons(p, kayak_rt::nil()))
                            } else {
                                nil::<Str>()
                            }
                        }), ps))), onto(ps, expanding(tvars)))), body))
                    }
                }
            }
        }
    }
}

/// A family's parameters, from its head `(name (p kind) ...)`: a type's
/// named as written, a region's with `'` first; none for a bare name.
pub fn family_params(v: &'static Cv, head: &'static Sexp) -> Strings {
    let tagcase_ = head;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            map(lambda1s(move |b: &'static Sexp| {
                let b = items(b);
                if (i64_eq(size(b), 3i64) && sym_is_p(second(b), str_lit("region")) && not(sym_is_p(third(b), str_lit("distinct")))) {
                    // A region within a place, `(r region p)` (C40).
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if not(i64_eq(size(b), 2i64)) {
                    match refuse(v, string_append(str_lit("a variance mark, which KFX does not have (its families are invariant): "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
                } else if sym_is_p(second(b), str_lit("type")) {
                    name_of(v, car(b))
                } else if sym_is_p(second(b), str_lit("region")) {
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if sym_is_p(second(b), str_lit("place")) {
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if sym_is_p(second(b), str_lit("effect")) {
                    string_append(str_lit("~"), name_of(v, car(b)))
                } else {
                    match refuse(v, string_append(str_lit("a family over a kind KFX does not have: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
                }
            }), cdr(xs))
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// A type's name as its own Rust scope writes it: `m t` and `m..t` are `t`.
pub fn bare_type_name(mut cs: Chars, mut acc: Chars) -> Str {
    loop {
        if null_p(cs) {
            return rev_to_string(acc);
        } else if (char_eq_p(car(cs), ' ') || char_eq_p(car(cs), '.')) {
            (cs, acc) = (cdr(cs), nil::<char>());
            continue;
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

/// Type variables, a poly's or a family's, each a Rust type parameter of
/// its name camel-cased: each a KFX name (C27), none named as a type the
/// Rust names, as another of them, or as a type `types` has, which it
/// would hide in Rust and not in FX-26. A region's, with `'`, is none, nor
/// an effect's, with `~`, which Rust does not see (C46).
pub fn type_binders_apart(v: &'static Cv, tvars: Strings, types: Strings) -> () {
    let (reserved, theirs, tvars) = (rust_type_names(), map(lambda1s(move |t: Str| {
        camel(bare_type_name(string_chars(t), nil::<char>()))
    }), types), concat(map(lambda1s(move |n: Str| {
        if (has_prefix_p(n, str_lit("'")) || has_prefix_p(n, str_lit("~")) || has_prefix_p(n, str_lit("#"))) {
            nil::<Str>()
        } else {
            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
        }
    }), tvars)));
    map(lambda1s(move |n: Str| {
        if not(kfx_name_p(n)) {
            match refuse(v, string_append(str_lit("a type variable's name KFX's names are not (C27): "), n)) {}
        } else if string_member_p(camel(n), reserved) {
            match refuse(v, string_append(str_lit("a type variable named as a type the Rust names: "), n)) {}
        } else if string_member_p(camel(n), theirs) {
            match refuse(v, string_append(str_lit("a type variable named as a type, which it would hide in Rust: "), n)) {}
        } else {
            ()
        }
    }), tvars);
    if repeated_p(map(&camel, tvars)) {
        match refuse(v, str_lit("two type variables named alike in Rust (camel-cased, as `a` and `a-`)")) {}
    } else {
        ()
    }
}

/// A definition's type's variables: a poly at its top, over types, and
/// regions, whose names begin with `'`; the program's `own`, held apart
/// from its types (a primitive's not).
pub fn poly_binders(v: &'static Cv, t: &'static Sexp, own: bool) -> Strings {
    if head_is_p(t, str_lit("poly")) {
        let tvars = map(lambda1s(move |b: &'static Sexp| {
            let b = items(b);
            if (i64_eq(size(b), 3i64) && sym_is_p(second(b), str_lit("region")) && not(sym_is_p(third(b), str_lit("distinct")))) {
                // A region within a place, `(r region p)` (C40): its data may be
                // made in the place, which it will not outlive.
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if not(i64_eq(size(b), 2i64)) {
                match refuse(v, string_append(str_lit("a binder KFX-0 does not have (distinct regions are to come): "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
            } else if sym_is_p(second(b), str_lit("type")) {
                name_of(v, car(b))
            } else if sym_is_p(second(b), str_lit("region")) {
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if sym_is_p(second(b), str_lit("place")) {
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if sym_is_p(second(b), str_lit("effect")) {
                string_append(str_lit("~"), name_of(v, car(b)))
            } else if sym_is_p(second(b), str_lit("size")) {
                string_append(str_lit("#"), name_of(v, car(b)))
            } else {
                match refuse(v, string_append(str_lit("KFX's poly is over types, effects, regions and places: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
            }
        }), items(second(items(t))));
        if own {
            type_binders_apart(v, tvars, onto(map(lambda1s(move |d: &'static Dt| {
                let tagcase_ = d;
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        n
                    }
                }
            }), cv_dts(v)), map(lambda1s(move |a: &'static Alias| {
                let tagcase_ = a;
                match *tagcase_ {
                    Alias::Alias(n, ps, body) => {
                        n
                    }
                }
            }), cv_aliases(v))))
        } else {
            ()
        };
        tvars
    } else {
        nil::<Str>()
    }
}

/// A poly's place binders, `%place 'p` each: where `(place p)` may be
/// written (C34). A place is a region too, `'p`.
pub fn place_marks(t: &'static Sexp) -> Strings {
    if head_is_p(t, str_lit("poly")) {
        concat(map(lambda1s(move |b: &'static Sexp| {
            let xs = items(b);
            if (i64_eq(size(xs), 2i64) && sym_is_p(second(xs), str_lit("place"))) {
                the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%place '"), sym_name(car(xs))), kayak_rt::nil()))
            } else if (i64_eq(size(xs), 3i64) && sym_is_p(second(xs), str_lit("region")) && not(sym_is_p(third(xs), str_lit("distinct")))) {
                the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%within '"), string_append(sym_name(car(xs)), string_append(str_lit(" '"), sym_name(third(xs))))), kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }), items(second(items(t)))))
    } else {
        nil::<Str>()
    }
}

/// A `poly` directly in a `poly`, as FX-26 writes a primitive's binders by
/// kind (C70): one `poly`, the binders in order, which means the same.
pub fn flat_poly(t: &'static Sexp) -> &'static Sexp {
    if (head_is_p(t, str_lit("poly")) && i64_eq(size(items(t)), 3i64) && head_is_p(third(items(t)), str_lit("poly"))) {
        let inner = flat_poly(third(items(t)));
        lst(kayak_rt::heap_cons(car(items(t)), kayak_rt::heap_cons(lst(onto(items(second(items(t))), items(second(items(inner)))), str_lit(""), 0i64, 0i64), kayak_rt::heap_cons(third(items(inner)), kayak_rt::nil()))), datum_file(t), 0i64, datum_pos(t))
    } else {
        t
    }
}

pub fn parse_scheme_of(v: &'static Cv, t0: &'static Sexp, own: bool) -> &'static Scheme {
    let t = flat_poly(t0);
    let tvars = poly_binders(v, t, own);
    scheme(tvars, parse_type(v, onto(place_marks(t), tvars), if head_is_p(t, str_lit("poly")) {
        third(items(t))
    } else {
        t
    }))
}

pub fn parse_scheme(v: &'static Cv, t: &'static Sexp) -> &'static Scheme {
    parse_scheme_of(v, t, true)
}

/// Size `t` as a linear expression, its variables named (`#n`, `?k`), an
/// inference variable solved looked through; none if it is `finite`.
pub fn size_lin(s: &'static St, t: &'static Ty) -> Lins {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVar(n) => {
            kayak_rt::heap_cons(lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil())), kayak_rt::nil())
        }
        Ty::TyMeta(k) => {
            kayak_rt::heap_cons(lin(0i64, kayak_rt::heap_cons(lterm(string_append(str_lit("?"), i64_to_string(k)), 1i64), kayak_rt::nil())), kayak_rt::nil())
        }
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%sz")) {
                size_terms_lin(s, cdr(args), lin(string_to_i64(after_prefix({
                    let tagcase_ = car(args);
                    match *tagcase_ {
                        Ty::TyData(k, a) => {
                            k
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("%k 0")
                        }
                    }
                }, str_lit("%k "))), nil::<&'static Lterm>()))
            } else {
                nil::<&'static Lin>()
            }
        }
        _ => {
            let other = tagcase_;
            nil::<&'static Lin>()
        }
    }
}

pub fn size_terms_lin(mut s: &'static St, mut ts: List<&'static Ty>, mut acc: &'static Lin) -> Lins {
    loop {
        if null_p(ts) {
            return kayak_rt::heap_cons(acc, kayak_rt::nil());
        } else {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Ty::TyData(d, args) => {
                    let inner = size_lin(s, car(args));
                    if null_p(inner) {
                        return nil::<&'static Lin>();
                    } else {
                        (ts, acc) = (cdr(ts), lin_add(acc, car(inner), string_to_i64(after_prefix(d, str_lit("%t ")))));
                        continue;
                    }
                }
                _ => {
                    let other = tagcase_;
                    return nil::<&'static Lin>();
                }
            }
        }
    }
}

pub fn size_finite_p(s: &'static St, t: &'static Ty) -> bool {
    null_p(size_lin(s, t))
}

/// As FX-26 writes a size: `3`, `n`, `(+ n 1)`, `(- n 1)`, `(+ n m)`.
pub fn size_text(l: &'static Lin) -> Str {
    let tagcase_ = l;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            let vars = concat(map(lambda1s(move |t: &'static Lterm| {
                let tagcase_ = t;
                match *tagcase_ {
                    Lterm::Lterm(n, k) => {
                        let x = if has_prefix_p(n, str_lit("#")) {
                            after_prefix(n, str_lit("#"))
                        } else {
                            n
                        };
                        if i64_eq(k, 1i64) {
                            the::<Strings>(kayak_rt::heap_cons(x, kayak_rt::nil()))
                        } else {
                            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(* "), string_append(i64_to_string(k), string_append(str_lit(" "), string_append(x, str_lit(")"))))), kayak_rt::nil()))
                        }
                    }
                }
            }), ts));
            if null_p(vars) {
                i64_to_string(c)
            } else if (null_p(cdr(vars)) && i64_eq(c, 0i64)) {
                car(vars)
            } else if i64_lt(c, 0i64) {
                string_append(str_lit("(- "), string_append(words_of(vars), string_append(str_lit(" "), string_append(i64_to_string(i64_minus(0i64, c)), str_lit(")")))))
            } else if i64_eq(c, 0i64) {
                string_append(str_lit("(+ "), string_append(words_of(vars), str_lit(")")))
            } else {
                string_append(str_lit("(+ "), string_append(words_of(vars), string_append(str_lit(" "), string_append(i64_to_string(c), str_lit(")")))))
            }
        }
    }
}

pub fn show_size(s: &'static St, t: &'static Ty) -> Str {
    let l = size_lin(s, t);
    if null_p(l) {
        str_lit("finite")
    } else {
        size_text(car(l))
    }
}

pub fn show_ty(s: &'static St, t: &'static Ty) -> Str {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("i64")
        }
        Ty::TyInt() => {
            str_lit("int")
        }
        Ty::TyNat() => {
            str_lit("nat")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyBool() => {
            str_lit("bool")
        }
        Ty::TyChar() => {
            str_lit("char")
        }
        Ty::TyUnit() => {
            str_lit("unit")
        }
        Ty::TyString() => {
            str_lit("string")
        }
        Ty::TyVoid() => {
            str_lit("void")
        }
        Ty::TyList(e, r) => {
            string_append(str_lit("(listof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyData(d, args) => {
            if has_prefix_p(d, str_lit("%module ")) {
                // A module type, by its abbreviation's name (C166).
                after_prefix(d, str_lit("%module "))
            } else if has_prefix_p(d, str_lit("mt@")) {
                // A module type's own abstract type, by its name (C170).
                after_dots(d)
            } else if (has_prefix_p(d, str_lit("$")) && null_p(args)) {
                // A dependent parameter's type (C170).
                string_append(str_lit("(select "), string_append(before_dots(d), string_append(str_lit(" "), string_append(after_dots(d), str_lit(")")))))
            } else if null_p(args) {
                d
            } else if string_eq_p(d, str_lit("%mtype")) {
                string_append(str_lit("(moduleof"), string_append(run_together(map(lambda1s(move |x: &'static Ty| {
                    string_append(str_lit(" "), show_mitem(s, x))
                }), onto(filter(lambda1s(move |x: &'static Ty| {
                    not(string_eq_p(mitem_kind(x), str_lit("%val")))
                }), args), filter(lambda1s(move |x: &'static Ty| {
                    string_eq_p(mitem_kind(x), str_lit("%val"))
                }), args)))), str_lit(")")))
            } else if has_prefix_p(d, str_lit("%spec ")) {
                show_specified(s, d, car(args))
            } else if string_eq_p(d, str_lit("%bloblet")) {
                string_append(str_lit("(bloblet (fields"), string_append(if null_p(cdr(args)) {
                    str_lit("")
                } else {
                    string_append(str_lit(" "), show_tys(s, cdr(args)))
                }, string_append(str_lit(") "), string_append(show_ty(s, car(args)), str_lit(")")))))
            } else if has_prefix_p(d, str_lit("%named ")) {
                // A type abbreviation, by its name (C164): its expansion first, then
                // its arguments.
                if null_p(cdr(args)) {
                    after_prefix(d, str_lit("%named "))
                } else {
                    string_append(str_lit("("), string_append(after_prefix(d, str_lit("%named ")), string_append(str_lit(" "), string_append(show_tys(s, cdr(args)), str_lit(")")))))
                }
            } else if string_eq_p(d, str_lit("%blobref")) {
                string_append(str_lit("(blobref "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%bytes")) {
                string_append(str_lit("(bytevectorof "), string_append(show_ty(s, car(args)), str_lit(")")))
            } else if string_eq_p(d, str_lit("%array")) {
                string_append(str_lit("(arrayof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%union")) {
                string_append(str_lit("(union "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%pairof")) {
                string_append(str_lit("(pairof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%mark-key")) {
                string_append(str_lit("(mark-key "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%escape-tag")) {
                string_append(str_lit("(escape-tag "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%nlist")) {
                string_append(str_lit("(nlist "), string_append(show_ty(s, car(args)), string_append(str_lit(" "), string_append(show_size(s, car(cdr(args))), str_lit(")")))))
            } else if string_eq_p(d, str_lit("%natof")) {
                string_append(str_lit("(nat "), string_append(show_size(s, car(args)), str_lit(")")))
            } else if (string_eq_p(d, str_lit("%sz")) || string_eq_p(d, str_lit("%finite"))) {
                show_size(s, t)
            } else if string_eq_p(d, str_lit("%poly")) {
                string_append(str_lit("(poly ("), string_append(binders_shown(poly_binders_of(args)), string_append(str_lit(") "), string_append(show_ty(s, poly_written(args)), str_lit(")")))))
            } else if (string_eq_p(d, str_lit("%addr")) || string_eq_p(d, str_lit("%inbox")) || string_eq_p(d, str_lit("%icell"))) {
                string_append(str_lit("("), string_append(after_prefix(d, str_lit("%")), string_append(str_lit(" "), string_append(show_tys(s, args), str_lit(")")))))
            } else if (string_eq_p(d, str_lit("%native")) || string_eq_p(d, str_lit("%fx"))) {
                string_append(str_lit("(subr (conv "), string_append(after_prefix(d, str_lit("%")), string_append(str_lit(") "), after_prefix(show_ty(s, car(args)), str_lit("(subr ")))))
            } else if string_eq_p(d, str_lit("%vsubr")) {
                string_append(str_lit("(vsubr "), string_append({
                    let tagcase_ = car(args);
                    match *tagcase_ {
                        Ty::TyProc(es, ps, r) => {
                            show_effs(es)
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("?")
                        }
                    }
                }, string_append(str_lit(" "), string_append(show_tys(s, cdr(args)), str_lit(")")))))
            } else if (string_eq_p(d, str_lit("%composable")) || string_eq_p(d, str_lit("%oneshot"))) {
                string_append(if string_eq_p(d, str_lit("%oneshot")) {
                    str_lit("(oneshot ")
                } else {
                    str_lit("(composable ")
                }, string_append(show_ty(s, car(args)), string_append(str_lit(" "), string_append(show_ty(s, car(cdr(args))), string_append(str_lit(" "), string_append({
                    let tagcase_ = car(cdr(cdr(args)));
                    match *tagcase_ {
                        Ty::TyProc(es, ps, r) => {
                            show_effs(es)
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("?")
                        }
                    }
                }, string_append(str_lit(" "), string_append(show_ty(s, car(cdr(cdr(cdr(args))))), str_lit(")")))))))))
            } else if string_eq_p(d, str_lit("%flat-array")) {
                string_append(str_lit("(flat-arrayof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%flat-sum")) {
                string_append(str_lit("(sumof "), string_append(show_ty(s, car(args)), string_append(run_together(map(lambda1s(move |f: &'static Fvar| {
                    let tagcase_ = f;
                    match *tagcase_ {
                        Fvar::Fvar(l, x) => {
                            string_append(str_lit(" ("), string_append(l, string_append(str_lit(" "), string_append(show_ty(s, x), str_lit(")")))))
                        }
                    }
                }), flat_sum_variants(args))), str_lit(")"))))
            } else if string_eq_p(d, str_lit("%place")) {
                string_append(str_lit("(place "), string_append(show_tys(s, args), str_lit(")")))
            } else {
                string_append(str_lit("("), string_append(d, string_append(str_lit(" "), string_append(show_tys(s, args), str_lit(")")))))
            }
        }
        Ty::TyShape(p, ls, ts) => {
            string_append(if p {
                str_lit("(productof")
            } else {
                str_lit("(sumof")
            }, string_append(show_fields(s, ls, ts), str_lit(")")))
        }
        Ty::TyFlat(e, r) => {
            string_append(str_lit("(flatarrayof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRef(e, r) => {
            string_append(str_lit("(ref "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyTag(a, h, d, r) => {
            string_append(str_lit("(prompt-tag "), string_append(show_ty(s, a), string_append(str_lit(" "), string_append(show_ty(s, h), string_append(str_lit(" "), string_append(show_effs(d), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))))))
        }
        Ty::TyProc(es, ps, r) => {
            string_append(str_lit("(subr "), string_append(show_effs(es), string_append(str_lit(" ("), string_append(show_tys(s, ps), string_append(str_lit(") "), string_append(show_ty(s, r), str_lit(")")))))))
        }
        Ty::TyVar(n) => {
            written_binder(n)
        }
        Ty::TyMeta(k) => {
            string_append(str_lit("?"), i64_to_string(k))
        }
    }
}

pub fn show_mitem(s: &'static St, x: &'static Ty) -> Str {
    let (k, n, args) = (mitem_kind(x), mitem_name(x), {
        let tagcase_ = x;
        match *tagcase_ {
            Ty::TyData(d, a) => {
                a
            }
            _ => {
                let other = tagcase_;
                nil::<&'static Ty>()
            }
        }
    });
    if string_eq_p(k, str_lit("%abs")) {
        string_append(str_lit("(abs "), string_append(n, str_lit(" type)")))
    } else if string_eq_p(k, str_lit("%edesc")) {
        string_append(str_lit("(desc "), string_append(n, string_append(str_lit(" "), string_append({
            let tagcase_ = car(args);
            match *tagcase_ {
                Ty::TyProc(es, ps, r) => {
                    show_effs(es)
                }
                _ => {
                    let other = tagcase_;
                    str_lit("?")
                }
            }
        }, str_lit(")")))))
    } else {
        string_append(str_lit("("), string_append(after_prefix(k, str_lit("%")), string_append(str_lit(" "), string_append(n, string_append(str_lit(" "), string_append(show_ty(s, car(args)), str_lit(")")))))))
    }
}

/// A specified procedure type (C162): its parameters by their names where
/// it has clauses, and its clauses after its result.
pub fn show_specified(s: &'static St, d: Str, t: &'static Ty) -> Str {
    let split = latent_split(spec_ensures(d));
    let clauses = spec_clauses_shown(d, if null_p(split) {
        spec_ensures(d)
    } else {
        third(split)
    });
    let inner = walk(s, t);
    let conv = {
        let tagcase_ = inner;
        match *tagcase_ {
            Ty::TyData(c, args) => {
                if (string_eq_p(c, str_lit("%fx")) || string_eq_p(c, str_lit("%native"))) {
                    string_append(str_lit("(conv "), string_append(after_prefix(c, str_lit("%")), str_lit(") ")))
                } else {
                    str_lit("")
                }
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    let tagcase_ = procedure_within(inner);
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            string_append(str_lit("(subr "), string_append(conv, string_append(show_effs(es), string_append(str_lit(" ("), string_append(if string_eq_p(clauses, str_lit("")) {
                show_tys(s, ps)
            } else {
                show_named(s, ps, spec_param_names(d))
            }, string_append(str_lit(") "), string_append(if null_p(split) {
                show_ty(s, r)
            } else {
                latent_shown(split)
            }, string_append(clauses, str_lit(")")))))))))
        }
        _ => {
            let other = tagcase_;
            show_ty(s, t)
        }
    }
}

pub fn show_named(s: &'static St, ps: Tys, names: Strings) -> Str {
    if null_p(ps) {
        str_lit("")
    } else {
        string_append({
            let n = if null_p(names) {
                str_lit("%none")
            } else {
                car(names)
            };
            if string_eq_p(n, str_lit("%none")) {
                show_ty(s, car(ps))
            } else {
                string_append(str_lit("("), string_append(n, string_append(str_lit(" "), string_append(show_ty(s, car(ps)), str_lit(")")))))
            }
        }, if null_p(cdr(ps)) {
            str_lit("")
        } else {
            string_append(str_lit(" "), show_named(s, cdr(ps), if null_p(names) {
                nil::<Str>()
            } else {
                cdr(names)
            }))
        })
    }
}

pub fn show_fields(s: &'static St, ls: Strings, ts: Tys) -> Str {
    if (null_p(ls) || null_p(ts)) {
        str_lit("")
    } else {
        string_append(str_lit(" ("), string_append(car(ls), string_append(str_lit(" "), string_append(show_ty(s, car(ts)), string_append(str_lit(")"), show_fields(s, cdr(ls), cdr(ts)))))))
    }
}

pub fn show_tys(s: &'static St, ts: Tys) -> Str {
    if null_p(ts) {
        str_lit("")
    } else if null_p(cdr(ts)) {
        show_ty(s, car(ts))
    } else {
        string_append(show_ty(s, car(ts)), string_append(str_lit(" "), show_tys(s, cdr(ts))))
    }
}

/// `t`, its inference variable replaced by its solution, if it has one.
pub fn walk(mut s: &'static St, mut t: &'static Ty) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyMeta(k) => {
                let tagcase_ = s;
                match *tagcase_ {
                    St::St(subst, next, fs) => {
                        let found = lookup_meta(k, subst);
                        if null_p(found) {
                            return t;
                        } else {
                            t = car(found);
                            continue;
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return t;
            }
        }
    }
}

pub fn lookup_meta(mut k: i64, mut subst: Sbs) -> Tys {
    loop {
        if null_p(subst) {
            return nil::<&'static Ty>();
        } else {
            let tagcase_ = car(subst);
            match *tagcase_ {
                Sb::Sb(j, t) => {
                    if i64_eq(j, k) {
                        return kayak_rt::heap_cons(t, kayak_rt::nil());
                    } else {
                        subst = cdr(subst);
                        continue;
                    }
                }
            }
        }
    }
}

/// Whether `t` has an inference variable not solved yet.
pub fn has_meta_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(k) => {
            true
        }
        Ty::TyList(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyFlat(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1s(move |x: &'static Ty| {
                has_meta_p(s, x)
            }), ts)
        }
        Ty::TyTag(a, h, d, r) => {
            (has_meta_p(s, a) || has_meta_p(s, h) || has_meta_p(s, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1s(move |x: &'static Ty| {
                has_meta_p(s, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyProc(es, ps, r) => {
            (has_meta_p(s, r) || any_p(lambda1s(move |p: &'static Ty| {
                has_meta_p(s, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A new inference variable.
pub fn fresh(s: &'static St) -> &'static Res {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            res(ty_meta(next), nil::<Str>(), st(subst, i64_plus(next, 1i64), fs))
        }
    }
}

pub fn note_fact(s: &'static St, file: Str, pos: i64, what: Str) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(subst, next, kayak_rt::heap_cons(fact(file, pos, what), fs))
        }
    }
}

/// What FX-26 has and KFX has not, for Rust (front-end.md stage 2, C154):
/// not refused here but noted, a fact of the file `%kfx`, for kfx's
/// restriction pass to refuse (restrict.kfx), where and as the checker
/// would have; the engine, which runs no such pass, checks on.
pub fn kfx_restricted(v: &'static Cv, s: &'static St, message: Str) -> &'static St {
    note_fact(s, str_lit("%kfx"), 0i64, string_append(str_lit("kfx-refuses "), refusal_text(v, message)))
}

pub fn st_facts(s: &'static St) -> Facts {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            fs
        }
    }
}

pub fn st_next(s: &'static St) -> i64 {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            next
        }
    }
}

// Inference variables said by their binders' names (C98): an instance's
// made in a REPL's draft or entry each noted as the binder it stands for,
// a fact of the file `%meta` at its number; and a message about it says
// `t` where it would say `?3`, a second variable of the same name primed,
// `t'`, as Fixpt says them. No fact is noted in a file's checking, so no
// file's messages change.
pub enum Said {
    Said(i64, Str),
}

pub fn said(f0: i64, f1: Str) -> &'static Said {
    kayak_rt::heap_alloc(Said::Said(f0, f1))
}

pub type Saids = List<&'static Said>;

pub fn binders_noted(mut s: &'static St, mut tvars: Strings, mut k: i64) -> &'static St {
    loop {
        if null_p(tvars) {
            return s;
        } else {
            (s, tvars, k) = (note_fact(s, str_lit("%meta"), k, string_append(str_lit("binder "), car(tvars))), cdr(tvars), i64_plus(k, 1i64));
            continue;
        }
    }
}

pub fn binder_of(mut fs: Facts, mut k: i64) -> Str {
    loop {
        if null_p(fs) {
            return str_lit("");
        } else {
            let tagcase_ = car(fs);
            match *tagcase_ {
                Fact::Fact(f, p, w) => {
                    if (i64_eq(p, k) && string_eq_p(f, str_lit("%meta"))) {
                        return after_prefix(w, str_lit("binder "));
                    } else {
                        fs = cdr(fs);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn said_as(mut ss: Saids, mut k: i64) -> Str {
    loop {
        if null_p(ss) {
            return str_lit("");
        } else {
            let tagcase_ = car(ss);
            match *tagcase_ {
                Said::Said(j, n) => {
                    if i64_eq(j, k) {
                        return n;
                    } else {
                        ss = cdr(ss);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn said_by_p(ss: Saids, n: Str) -> bool {
    (not(null_p(ss)) && {
        let tagcase_ = car(ss);
        match *tagcase_ {
            Said::Said(j, m) => {
                (string_eq_p(m, n) || said_by_p(cdr(ss), n))
            }
        }
    })
}

pub fn unsaid(mut ss: Saids, mut n: Str) -> Str {
    loop {
        if said_by_p(ss, n) {
            n = string_append(n, str_lit("'"));
            continue;
        } else {
            return n;
        }
    }
}

pub fn digits_after(mut cs: Chars, mut k: i64) -> i64 {
    loop {
        if (not(null_p(cs)) && char_numeric_p(car(cs))) {
            (cs, k) = (cdr(cs), i64_plus(i64_star(k, 10i64), i64_minus(char_to_i64(car(cs)), 48i64)));
            continue;
        } else {
            return k;
        }
    }
}

pub fn past_digits(mut cs: Chars) -> Chars {
    loop {
        if (not(null_p(cs)) && char_numeric_p(car(cs))) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

pub fn metas_said(mut fs: Facts, mut cs: Chars, mut ss: Saids, mut acc: Str) -> Str {
    loop {
        if null_p(cs) {
            return acc;
        } else if (char_eq_p(car(cs), '?') && not(null_p(cdr(cs))) && char_numeric_p(car(cdr(cs)))) {
            let k = digits_after(cdr(cs), 0i64);
            let was = said_as(ss, k);
            let binder = binder_of(fs, k);
            if not(string_eq_p(was, str_lit(""))) {
                (cs, acc) = (past_digits(cdr(cs)), string_append(acc, was));
                continue;
            } else if string_eq_p(binder, str_lit("")) {
                (cs, acc) = (past_digits(cdr(cs)), string_append(acc, meta_name(k)));
                continue;
            } else {
                let n = unsaid(ss, binder);
                (cs, ss, acc) = (past_digits(cdr(cs)), kayak_rt::heap_cons(said(k, n), ss), string_append(acc, n));
                continue;
            }
        } else {
            (cs, acc) = (cdr(cs), string_append(acc, char_to_string(car(cs))));
            continue;
        }
    }
}

pub fn metas_named(s: &'static St, message: Str) -> Str {
    let fs = st_facts(s);
    if any_p(lambda1s(move |f: &'static Fact| {
        let tagcase_ = f;
        match *tagcase_ {
            Fact::Fact(file, p, w) => {
                string_eq_p(file, str_lit("%meta"))
            }
        }
    }), fs) {
        metas_said(fs, string_chars(message), nil::<&'static Said>(), str_lit(""))
    } else {
        message
    }
}

/// A refusal whose types' inference variables are said by their binders'
/// names, where a draft's instance noted them.
pub fn refuse_named(v: &'static Cv, s: &'static St, message: Str) -> Void {
    match refuse(v, metas_named(s, message)) {}
}

pub fn solve(s: &'static St, k: i64, t: &'static Ty) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(kayak_rt::heap_cons(sb(k, t), subst), next, fs)
        }
    }
}

pub fn occurs_p(s: &'static St, k: i64, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(j) => {
            i64_eq(j, k)
        }
        Ty::TyList(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyFlat(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1s(move |x: &'static Ty| {
                occurs_p(s, k, x)
            }), ts)
        }
        Ty::TyTag(a, h, d, r) => {
            (occurs_p(s, k, a) || occurs_p(s, k, h) || occurs_p(s, k, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1s(move |x: &'static Ty| {
                occurs_p(s, k, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyProc(es, ps, r) => {
            (occurs_p(s, k, r) || any_p(lambda1s(move |p: &'static Ty| {
                occurs_p(s, k, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn same_base_p(a: &'static Ty, e: &'static Ty) -> bool {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyI64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyI64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyInt() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyInt() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyNat() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyNat() => {
                    true
                }
                Ty::TyInt() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyF64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyF64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyBool() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyBool() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyChar() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyChar() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyUnit() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyUnit() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyString() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyString() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn repeat_ty(t: &'static Ty, n: i64) -> Tys {
    if i64_lt(n, 1i64) {
        nil::<&'static Ty>()
    } else {
        kayak_rt::heap_cons(t, repeat_ty(t, i64_minus(n, 1i64)))
    }
}

/// Whether a value of type `t` crosses between kayak's values and native
/// code's (C116, kayak-rt's `Native`): as the same word in both, or
/// copied, which no KFX program can tell of a list or a string, since
/// none tells pairs apart (`eq?`) nor writes through one (`set-car!`).
pub fn native_crossing_p(mut s: &'static St, mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyInt() => {
                return true;
            }
            Ty::TyNat() => {
                return true;
            }
            Ty::TyI64() => {
                return true;
            }
            Ty::TyBool() => {
                return true;
            }
            Ty::TyUnit() => {
                return true;
            }
            Ty::TyChar() => {
                return true;
            }
            Ty::TyString() => {
                return true;
            }
            Ty::TyList(x, r) => {
                t = x;
                continue;
            }
            Ty::TyData(d, args) => {
                // A bloblet whose fields cross, copied each way (kayak-rt's `Native`,
                // which says what a copy cannot see).
                return (string_eq_p(d, str_lit("%bloblet")) && i64_lt(size(args), 6i64) && not(any_p(lambda1s(move |x: &'static Ty| {
                    not(native_crossing_p(s, x))
                }), cdr(args))));
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

/// Whether a value of type `t` may be given to native code: one that
/// crosses, or a procedure of the fx convention whose parameters and
/// result cross, which native code calls back by `foreign` (C116).
pub fn native_given_p(s: &'static St, t: &'static Ty) -> bool {
    (native_crossing_p(s, t) || {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyData(d, args) => {
                (string_eq_p(d, str_lit("%fx")) && native_given_p(s, car(args)))
            }
            Ty::TyFlat(e, r) => {
                // An `i64` flat array, shared, laid out as Fixpt's (C126):
                // native code reads and writes the elements KFX does.
                let tagcase_ = walk(s, e);
                match *tagcase_ {
                    Ty::TyI64() => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }
            Ty::TyProc(es, ps, r) => {
                // A procedure of KFX's own, as one of the fx convention is: in a
                // code bloblet's field, made code calls it by `foreign`.
                (i64_lt(size(ps), 4i64) && native_crossing_p(s, r) && not(escapes_p(es)) && not(suspends_p(es)) && not(any_p(lambda1s(move |p: &'static Ty| {
                    not(native_crossing_p(s, p))
                }), ps)))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    })
}

/// A variadic procedure called with `n` arguments, as the procedure of `n`
/// `T`s it is then (C71); a native one, its procedure (C116); any other
/// type, itself.
pub fn vsubr_as_proc(t: &'static Ty, n: i64) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%vsubr")) {
                ty_proc({
                    let tagcase_ = car(args);
                    match *tagcase_ {
                        Ty::TyProc(es, ps, r) => {
                            es
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                }, repeat_ty(car(cdr(args)), n), car(cdr(cdr(args))))
            } else if (string_eq_p(d, str_lit("%native")) || string_eq_p(d, str_lit("%fx"))) {
                // A procedure of a convention (C116), called as any is.
                car(args)
            } else if has_prefix_p(d, str_lit("%spec ")) {
                // A specified procedure (C162), called as any is.
                procedure_within(t)
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn region_string(s: &'static St, r: &'static Ty) -> Str {
    let tagcase_ = walk(s, r);
    match *tagcase_ {
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            meta_name(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

/// A composable continuation as the procedure it is (C60): of its `D`, and
/// control on its region; any other type, itself.
pub fn composable_as_proc(s: &'static St, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if (string_eq_p(d, str_lit("%composable")) || string_eq_p(d, str_lit("%oneshot"))) {
                let r = region_string(s, car(cdr(cdr(cdr(args)))));
                ty_proc(effs_union(kayak_rt::heap_cons(string_append(str_lit("goto:"), r), kayak_rt::heap_cons(string_append(str_lit("comefrom:"), r), kayak_rt::nil())), {
                    let tagcase_ = car(cdr(cdr(args)));
                    match *tagcase_ {
                        Ty::TyProc(es, ps, x) => {
                            es
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                }), kayak_rt::heap_cons(car(args), kayak_rt::nil()), car(cdr(args)))
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// The number of an inference variable's name, `?k`.
pub fn meta_number(r: Str) -> i64 {
    i64_minus(0i64, digits_value(cdr(string_chars(r)), 0i64, str_lit(""), 0i64))
}

pub fn chars_after_colon(mut cs: Chars) -> Str {
    loop {
        if null_p(cs) {
            return str_lit("");
        } else if char_eq_p(car(cs), ':') {
            return rev_to_string(rev_onto(cdr(cs), nil::<char>()));
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn effect_region(e: Str) -> Str {
    chars_after_colon(string_chars(e))
}

/// Whether `t` has an inference variable not solved yet, a latent
/// effect's region too (`(goto ?k)`): as FX-26 counts what a parameter's
/// type mentions that is not known.
pub fn open_effects_p(mut s: &'static St, mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyProc(es, ps, r) => {
                return (any_p(lambda1s(move |e: Str| {
                    let at = effect_region(e);
                    (has_prefix_p(at, str_lit("?")) && {
                        let tagcase_ = walk(s, ty_meta(meta_number(at)));
                        match *tagcase_ {
                            Ty::TyMeta(k) => {
                                true
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    })
                }), es) || open_effects_p(s, r) || any_p(lambda1s(move |p: &'static Ty| {
                    open_effects_p(s, p)
                }), ps));
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyData(d, args) => {
                return any_p(lambda1s(move |x: &'static Ty| {
                    open_effects_p(s, x)
                }), args);
            }
            Ty::TyShape(p, ls, ts) => {
                return any_p(lambda1s(move |x: &'static Ty| {
                    open_effects_p(s, x)
                }), ts);
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

pub fn has_open_p(s: &'static St, t: &'static Ty) -> bool {
    (has_meta_p(s, t) || open_effects_p(s, t))
}

/// An effect atom, its region an inference variable solved replaced by
/// the region found.
pub fn resolve_atom(s: &'static St, x: Str) -> Str {
    if region_atom_p(x) {
        let r = atom_region(x);
        if char_eq_p(string_ref_i64(r, 0i64), '?') {
            string_append(atom_kind(x), region_string(s, ty_meta(meta_number(r))))
        } else {
            x
        }
    } else {
        x
    }
}

/// `t`, every inference variable in it replaced by its solution.
pub fn zonk(s: &'static St, t: &'static Ty) -> &'static Ty {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyList(e, r) => {
            ty_list(zonk(s, e), zonk(s, r))
        }
        Ty::TyFlat(e, r) => {
            ty_flat(zonk(s, e), zonk(s, r))
        }
        Ty::TyShape(p, ls, ts) => {
            ty_shape(p, ls, map(lambda1s(move |x: &'static Ty| {
                zonk(s, x)
            }), ts))
        }
        Ty::TyTag(a, h, d, r) => {
            ty_tag(zonk(s, a), zonk(s, h), d, zonk(s, r))
        }
        Ty::TyData(d, args) => {
            ty_data(d, map(lambda1s(move |x: &'static Ty| {
                zonk(s, x)
            }), args))
        }
        Ty::TyRef(e, r) => {
            ty_ref(zonk(s, e), zonk(s, r))
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(es, map(lambda1s(move |p: &'static Ty| {
                zonk(s, p)
            }), ps), zonk(s, r))
        }
        _ => {
            let other = tagcase_;
            other
        }
    }
}

pub fn region_ty(r: Str) -> &'static Ty {
    if char_eq_p(string_ref_i64(r, 0i64), '?') {
        ty_meta(meta_number(r))
    } else if char_eq_p(string_ref_i64(r, 0i64), '\'') {
        ty_var(r)
    } else {
        ty_rconst(r)
    }
}

/// Of the effect `es`, an atom of the kind of `x` whose region is an
/// inference variable not solved: that variable can stand for `x`'s
/// region.
pub fn open_atom(mut s: &'static St, mut x: Str, mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if {
            let y = resolve_atom(s, car(es));
            (region_atom_p(y) && string_eq_p(atom_kind(y), atom_kind(x)) && char_eq_p(string_ref_i64(atom_region(y), 0i64), '?'))
        } {
            return kayak_rt::heap_cons(resolve_atom(s, car(es)), kayak_rt::nil());
        } else {
            es = cdr(es);
            continue;
        }
    }
}

// Effect variables (C46): a poly's effect binder is an atom `~e`; at a
// call, an inference variable, `~?k`, solved to a row: `(ty-proc atoms nil
// unit)` holds its atoms, the last of which may be another variable, open
// for more.
pub fn effect_meta_p(x: Str) -> bool {
    has_prefix_p(x, str_lit("~?"))
}

/// `es`, each effect variable solved replaced by its atoms.
pub fn expand_effs(s: &'static St, es: Strings) -> Strings {
    if null_p(es) {
        nil::<Str>()
    } else {
        effs_union(if effect_meta_p(car(es)) {
            let tagcase_ = walk(s, ty_meta(meta_number(after_prefix(car(es), str_lit("~")))));
            match *tagcase_ {
                Ty::TyProc(r#as, ps, r) => {
                    expand_effs(s, r#as)
                }
                _ => {
                    let other = tagcase_;
                    kayak_rt::heap_cons(car(es), kayak_rt::nil())
                }
            }
        } else {
            kayak_rt::heap_cons(car(es), kayak_rt::nil())
        }, expand_effs(s, cdr(es)))
    }
}

/// The effect variables of `es`, expanded: those not solved.
pub fn open_row(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if effect_meta_p(car(es)) {
            return kayak_rt::heap_cons(car(es), open_row(cdr(es)));
        } else {
            es = cdr(es);
            continue;
        }
    }
}

pub fn closed_row(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if effect_meta_p(car(es)) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), closed_row(cdr(es)));
        }
    }
}

/// A call's effect: its effect variables' atoms, and none for a variable
/// nothing said, as FX-26 instantiates an effect binder no argument
/// names (pure).
pub fn close_effs(s: &'static St, es: Strings) -> Strings {
    closed_row(expand_effs(s, es))
}

/// Whether effect `a` is within `e`, an inference variable for a region
/// in `e` solved for one in `a` if need be, and one for an effect in `e`
/// grown to hold an atom of `a` (C46): the state, or none.
pub fn fit_effs(s: &'static St, a: Strings, e: Strings) -> List<&'static St> {
    if null_p(a) {
        kayak_rt::heap_cons(s, kayak_rt::nil())
    } else {
        fit_expanded(s, expand_effs(s, a), e, map(lambda1s(move |y: Str| {
            resolve_atom(s, y)
        }), expand_effs(s, e)))
    }
}

/// `fit-effs`, `a` and `e` expanded in `s` (`ax`, `es`): kept while `s`
/// is, as expanding them again would give the same (C143).
pub fn fit_expanded(mut s: &'static St, mut ax: Strings, mut e: Strings, mut es: Strings) -> List<&'static St> {
    loop {
        if null_p(ax) {
            return kayak_rt::heap_cons(s, kayak_rt::nil());
        } else {
            let x = resolve_atom(s, car(ax));
            if effs_within_p(kayak_rt::heap_cons(x, kayak_rt::nil()), es) {
                ax = cdr(ax);
                continue;
            } else if string_eq_p(x, str_lit("alloc:acyclic")) {
                // Made at `acyclic`, frozen from its making, which nothing sees
                // (`list`'s `(alloc r)`, `r` acyclic): within any effect (C156).
                ax = cdr(ax);
                continue;
            } else if effect_meta_p(x) {
                // An effect variable of `a` not solved, that `e` does not hold:
                // nothing more, the least it may be.
                return fit_effs(solve(s, meta_number(after_prefix(x, str_lit("~"))), effect_row(nil::<Str>())), cdr(ax), e);
            } else if not(null_p(open_atom(s, x, e))) {
                let tagcase_ = region_ty(atom_region(car(open_atom(s, x, e))));
                match *tagcase_ {
                    Ty::TyMeta(k) => {
                        return fit_effs(solve(s, k, region_ty(atom_region(x))), cdr(ax), e);
                    }
                    _ => {
                        let other = tagcase_;
                        return nil::<&'static St>();
                    }
                }
            } else if not(null_p(open_row(es))) {
                let tagcase_ = fresh(s);
                match *tagcase_ {
                    Res::Res(m, u, s) => {
                        let tagcase_ = m;
                        match *tagcase_ {
                            Ty::TyMeta(j) => {
                                return fit_effs(solve(s, meta_number(after_prefix(car(open_row(es)), str_lit("~"))), effect_row(kayak_rt::heap_cons(x, kayak_rt::heap_cons(string_append(str_lit("~"), meta_name(j)), kayak_rt::nil())))), cdr(ax), e);
                            }
                            _ => {
                                let other = tagcase_;
                                return nil::<&'static St>();
                            }
                        }
                    }
                }
            } else {
                return nil::<&'static St>();
            }
        }
    }
}

/// Effects `a` and `b` the same, each within the other, an effect variable
/// on either side solved to make them so (C60): the side open grown first,
/// so that its variable is not taken for the least it may be.
pub fn same_effs(s: &'static St, a: Strings, b: Strings) -> List<&'static St> {
    let grown = fit_effs(s, b, a);
    if (not(null_p(grown)) && not(null_p(fit_effs(car(grown), a, b)))) {
        fit_effs(car(grown), a, b)
    } else {
        let other = fit_effs(s, a, b);
        if null_p(other) {
            nil::<&'static St>()
        } else {
            fit_effs(car(other), b, a)
        }
    }
}

pub fn datum_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            string_eq_p(d, str_lit("datum"))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

// The facts in scope (C157), and whether they show `goal >= 0`: each
// local `nat` and each size variable not negative.
pub enum Sfacts {
    Sfacts(Lins, Lins),
}

pub fn sfacts(f0: Lins, f1: Lins) -> &'static Sfacts {
    kayak_rt::heap_alloc(Sfacts::Sfacts(f0, f1))
}

/// The facts in scope, `>= 0` and `/= 0`: each of a binding of no name a
/// program writes, unless a name it mentions has been bound again
/// since (a narrowing names the same value).
pub fn size_facts_from(mut bs: Binds, mut seen: Strings, mut ges: Lins, mut nes: Lins) -> &'static Sfacts {
    loop {
        if null_p(bs) {
            return sfacts(ges, nes);
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    if (string_eq_p(n, str_lit("%size-fact")) && has_prefix_p(w, str_lit("fact "))) {
                        let ws = cdr(text_words(w));
                        let kind = car(ws);
                        let l = lin_read(cdr(ws));
                        if any_p(lambda1s(move |m: Str| {
                            string_member_p(m, seen)
                        }), lin_names(l)) {
                            bs = cdr(bs);
                            continue;
                        } else if string_eq_p(kind, str_lit("ge")) {
                            (bs, ges) = (cdr(bs), kayak_rt::heap_cons(l, ges));
                            continue;
                        } else if string_eq_p(kind, str_lit("eq")) {
                            (bs, ges) = (cdr(bs), kayak_rt::heap_cons(l, kayak_rt::heap_cons(lin_scaled(l, -1i64), ges)));
                            continue;
                        } else {
                            (bs, nes) = (cdr(bs), kayak_rt::heap_cons(l, nes));
                            continue;
                        }
                    } else if string_eq_p(w, str_lit("narrowed")) {
                        bs = cdr(bs);
                        continue;
                    } else {
                        (bs, seen) = (cdr(bs), kayak_rt::heap_cons(n, seen));
                        continue;
                    }
                }
            }
        }
    }
}

/// `l`, each inference variable in it that is solved replaced by its size.
pub fn lin_resolved(s: &'static St, l: &'static Lin) -> &'static Lin {
    let tagcase_ = l;
    match *tagcase_ {
        Lin::Lin(c, ts) => {
            if null_p(ts) {
                l
            } else {
                let tagcase_ = car(ts);
                match *tagcase_ {
                    Lterm::Lterm(n, k) => {
                        let rest = lin_resolved(s, lin(c, cdr(ts)));
                        if has_prefix_p(n, str_lit("?")) {
                            let found = size_lin(s, ty_meta(string_to_i64(after_prefix(n, str_lit("?")))));
                            if (null_p(found) || string_eq_p(lin_text(car(found)), lin_text(lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil()))))) {
                                lin_add(rest, lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil())), k)
                            } else {
                                lin_add(rest, lin_resolved(s, car(found)), k)
                            }
                        } else {
                            lin_add(rest, lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil())), k)
                        }
                    }
                }
            }
        }
    }
}

/// Each of `ns` a size variable, or a local `nat`: `n >= 0`.
pub fn nat_bounds(v: &'static Cv, s: &'static St, ns: Strings) -> Lins {
    concat(map(lambda1s(move |n: Str| {
        let b = find_bind(n, cv_binds(v));
        if (has_prefix_p(n, str_lit("#")) || has_prefix_p(n, str_lit("?")) || (not(null_p(b)) && {
            let tagcase_ = car(b);
            match *tagcase_ {
                Bind::Bind(m, sc, w) => {
                    let tagcase_ = sc;
                    match *tagcase_ {
                        Scheme::Scheme(tv, t) => {
                            let tagcase_ = walk(s, t);
                            match *tagcase_ {
                                Ty::TyNat() => {
                                    true
                                }
                                _ => {
                                    let other = tagcase_;
                                    false
                                }
                            }
                        }
                    }
                }
            }
        })) {
            the::<Lins>(kayak_rt::heap_cons(lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil())), kayak_rt::nil()))
        } else {
            nil::<&'static Lin>()
        }
    }), ns))
}

/// Whether the facts in scope show `goal >= 0`.
pub fn size_shown_p(v: &'static Cv, s: &'static St, goal0: &'static Lin) -> bool {
    let tagcase_ = size_facts_from(cv_binds(v), nil::<Str>(), nil::<&'static Lin>(), nil::<&'static Lin>());
    match *tagcase_ {
        Sfacts::Sfacts(ges0, nes0) => {
            let goal = lin_resolved(s, goal0);
            let ges = map(lambda1s(move |l: &'static Lin| {
                lin_resolved(s, l)
            }), ges0);
            let nes = map(lambda1s(move |l: &'static Lin| {
                lin_resolved(s, l)
            }), nes0);
            let names = concat(map(&lin_names, kayak_rt::heap_cons(goal, onto(ges, nes))));
            lin_shown_p(onto(nat_bounds(v, s, names), ges), nes, goal)
        }
    }
}

/// The first inference variable of `ts` of coefficient 1 or -1, if any:
/// one to solve for.
pub fn lone_meta(ts: List<&'static Lterm>) -> List<&'static Lterm> {
    let ms = filter(lambda1s(move |t: &'static Lterm| {
        let tagcase_ = t;
        match *tagcase_ {
            Lterm::Lterm(n, k) => {
                (has_prefix_p(n, str_lit("?")) && (i64_eq(k, 1i64) || i64_eq(k, -1i64)))
            }
        }
    }), ts);
    if null_p(ms) {
        nil::<&'static Lterm>()
    } else {
        kayak_rt::heap_cons(car(ms), kayak_rt::nil())
    }
}

pub fn sized_p(t: &'static Ty, d: Str) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(x, args) => {
            string_eq_p(x, d)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn sized_elem(t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            car(args)
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn sized_size(t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%natof")) {
                car(args)
            } else {
                car(cdr(args))
            }
        }
        _ => {
            let other = tagcase_;
            size_finite()
        }
    }
}

/// A `%nlist`'s type of one element fewer: `finite`'s is `finite`.
pub fn sized_less(t: &'static Ty, s: &'static St) -> &'static Ty {
    let l = size_lin(s, sized_size(t));
    ty_data(str_lit("%nlist"), kayak_rt::heap_cons(sized_elem(t), kayak_rt::heap_cons(if null_p(l) {
        size_finite()
    } else {
        size_of_lin(lin_add(car(l), lin(-1i64, nil::<&'static Lterm>()), 1i64))
    }, kayak_rt::nil())))
}

/// That a value of type `actual` may stand where `expected` is: the two
/// the same, inference variables solved to make them so, but for
/// `void`, which fits anything, and a procedure, whose latent effect
/// may be within the one expected.
pub fn fits(v: &'static Cv, s: &'static St, actual: &'static Ty, expected: &'static Ty) -> &'static St {
    let (a, e) = (walk(s, actual), walk(s, expected));
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyVoid() => {
            s
        }
        Ty::TyMeta(k) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if i64_eq(j, k) {
                        s
                    } else {
                        solve(s, k, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    if occurs_p(s, k, e) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, k, e)
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if occurs_p(s, j, a) {
                        mismatch(v, s, a, e)
                    } else if {
                        let tagcase_ = a;
                        match *tagcase_ {
                            Ty::TyNat() => {
                                true
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    } {
                        // A `nat` met by an inference variable makes it an `int`: FX-26's
                        // is the variable's own `(nat v)`, which no other `nat` is.
                        solve(s, j, ty_int())
                    } else {
                        solve(s, j, a)
                    }
                }
                _ => {
                    let other = tagcase_;
                    fits_shapes(v, s, a, e)
                }
            }
        }
    }
}

pub fn fits_shapes(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    if (not(string_eq_p(spec_of(a), str_lit(""))) || not(string_eq_p(spec_of(e), str_lit("")))) {
        // A specified procedure (C162): the procedure within, then behavioural
        // subtyping, Fixpt's `logic::spec_within`: it requires no more than
        // the one expected, and ensures no less.
        let s2 = fits(v, s, unspecified(a), unspecified(e));
        if spec_within_p(spec_of(a), spec_of(e)) {
            s2
        } else {
            match refuse_named(v, s, string_append(str_lit("a "), string_append(show_ty(s, a), string_append(str_lit(" is here, where a "), string_append(show_ty(s, e), str_lit(" is expected: it requires more, or ensures less, than is expected, as far as the prover can tell")))))) {}
        }
    } else if (sized_p(a, str_lit("%natof")) && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyNat() => {
                true
            }
            Ty::TyInt() => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `(nat s)` below `nat` and `int` (C158).
        s
    } else if (sized_p(a, str_lit("%nlist")) && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                (string_eq_p(d, str_lit("%pairof")) && sized_p(walk(s, car(cdr(args))), str_lit("%nlist")))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A pair whose tail is a list of a size, at `acyclic`, as the list it
        // is (C68, C158).
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                fits(v, fits(v, fits(v, s, sized_elem(a), car(args)), a, car(cdr(args))), car(cdr(cdr(args))), ty_rconst(str_lit("acyclic")))
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (sized_p(a, str_lit("%nlist")) && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(y, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A list of a size below a list, at `acyclic` (C158): frozen, it ends.
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(y, r) => {
                fits(v, fits(v, s, sized_elem(a), y), ty_rconst(str_lit("acyclic")), r)
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (sized_p(e, str_lit("%nlist")) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A list at `acyclic` below a list of a size not known, `finite`: one
        // that is frozen and ends (C158).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                if size_finite_p(s, sized_size(e)) {
                    fits(v, s, a, ty_list(sized_elem(e), ty_rconst(str_lit("acyclic"))))
                } else {
                    mismatch(v, s, a, e)
                }
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (sized_p(e, str_lit("%nlist")) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("nil"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `nil` below a list of a size shown 0 (C158).
        size_fits(v, s, size_of_lin(lin(0i64, nil::<&'static Lterm>())), sized_size(e), a, e)
    } else if (sized_p(e, str_lit("%nlist")) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("%pairof"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A pair, frozen, below a list of size `s`: its tail of size `s - 1`, `s`
        // shown not 0 (C158).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                let z = sized_size(e);
                if (not(size_finite_p(s, z)) && not(size_shown_p(v, s, lin_add(car(size_lin(s, z)), lin(-1i64, nil::<&'static Lterm>()), 1i64)))) {
                    mismatch(v, s, a, e)
                } else {
                    fits(v, fits(v, fits(v, s, car(args), sized_elem(e)), car(cdr(args)), sized_less(e, s)), car(cdr(cdr(args))), ty_rconst(str_lit("acyclic")))
                }
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (datum_p(a) && datum_p(e)) {
        s
    } else if (datum_p(e) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A list below `datum` (C77): its elements are, at `acyclic`; so a
        // list of datums is one, as FX-26 has it, and is given as it is.
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                fits(v, fits(v, s, x, e), r, ty_rconst(str_lit("acyclic")))
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if string_eq_p(shape_of(a), str_lit("union")) {
        // A union below `e`: each member is (C62).
        fits_each_member(v, s, members_of(a), e)
    } else if (string_eq_p(shape_of(e), str_lit("union")) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && null_p(member_of_shape(members_of(e), str_lit("list")))) {
        // A list where a union of `nil` and a pair is expected: each of the
        // two it is (C69).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                fits(v, fits(v, s, ty_data(str_lit("nil"), nil::<&'static Ty>()), e), ty_data(str_lit("%pairof"), kayak_rt::heap_cons(x, kayak_rt::heap_cons(a, kayak_rt::heap_cons(r, kayak_rt::nil())))), e)
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (string_eq_p(shape_of(e), str_lit("union")) && not(string_eq_p(shape_of(a), str_lit("")))) {
        // A member below its union: the member of its shape (C62).
        let m = member_of_shape(members_of(e), shape_of(a));
        if null_p(m) {
            mismatch(v, s, a, e)
        } else {
            fits(v, s, a, car(m))
        }
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("false"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyBool() => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `false` below `bool`.
        s
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("nil"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `nil` below a list (C68).
        s
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("%pairof"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A pair whose tail is the list, below the list (C68).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                let tagcase_ = e;
                match *tagcase_ {
                    Ty::TyList(x, r) => {
                        fits(v, fits(v, fits(v, s, car(args), x), car(cdr(args)), e), car(cdr(cdr(args))), r)
                    }
                    _ => {
                        let other = tagcase_;
                        mismatch(v, s, a, e)
                    }
                }
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else {
        fits_shapes_of(v, s, a, e)
    }
}

pub fn fits_each_member(mut v: &'static Cv, mut s: &'static St, mut ms: Tys, mut e: &'static Ty) -> &'static St {
    loop {
        if null_p(ms) {
            return s;
        } else {
            (s, ms) = (fits(v, s, car(ms), e), cdr(ms));
            continue;
        }
    }
}

pub fn fits_shapes_of(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyList(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyList(y, yr) => {
                    // A list at `acyclic` is frozen, so its elements' type may be
                    // below the one expected (C78); at a region that may be
                    // written, the same, as FX-26 has it.
                    let s = fits(v, s, xr, yr);
                    if {
                        let tagcase_ = walk(s, yr);
                        match *tagcase_ {
                            Ty::TyRconst(n) => {
                                (string_eq_p(n, str_lit("acyclic")) || string_eq_p(n, str_lit("const")))
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    } {
                        fits(v, s, x, y)
                    } else {
                        fits(v, fits(v, s, x, y), y, x)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyFlat(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyFlat(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyShape(p, ls, ts) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyShape(q, ms, us) => {
                    if (if p {
                        q
                    } else {
                        not(q)
                    } && strings_eq_p(ls, ms) && i64_eq(size(ts), size(us))) {
                        fits_each(v, s, ts, us)
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRef(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRef(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRconst(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRconst(y) => {
                    if (string_eq_p(x, y) || (string_eq_p(y, str_lit("const")) && (string_eq_p(x, str_lit("acyclic")) || string_eq_p(x, str_lit("%fresh"))))) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyTag(xa, xh, xd, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyTag(ya, yh, yd, yr) => {
                    // A tag's bound the same both ways, its effect variables solved to
                    // make it so (C60: a primitive's tag at FX-26's poly type).
                    let two = same_effs(s, xd, yd);
                    if null_p(two) {
                        mismatch(v, s, a, e)
                    } else {
                        fits(v, fits(v, fits(v, car(two), xa, ya), xh, yh), xr, yr)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyData(x, xs) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyData(y, ys) => {
                    if (string_eq_p(x, str_lit("%native")) && string_eq_p(y, str_lit("%fx"))) {
                        // A native procedure where one of any convention is (C116).
                        fits(v, s, car(xs), car(ys))
                    } else if (string_eq_p(x, str_lit("%mtype")) && string_eq_p(y, str_lit("%mtype"))) {
                        mtype_fits(v, kfx_restricted(v, s, str_lit("a module value, FX-26's first-class modules', which KFX has not yet (C170)")), a, e)
                    } else if (string_eq_p(x, str_lit("%mtype")) && has_prefix_p(y, str_lit("%module "))) {
                        mtype_fits(v, kfx_restricted(v, s, str_lit("a module value, FX-26's first-class modules', which KFX has not yet (C170)")), a, module_alias_type(v, y))
                    } else if (has_prefix_p(x, str_lit("%module ")) && string_eq_p(y, str_lit("%mtype"))) {
                        mtype_fits(v, kfx_restricted(v, s, str_lit("a module value, FX-26's first-class modules', which KFX has not yet (C170)")), module_alias_type(v, x), e)
                    } else if (string_eq_p(x, str_lit("%bloblet")) && string_eq_p(y, str_lit("%bloblet")) && i64_gt(size(xs), size(ys))) {
                        // A bloblet of more fields where one of fewer is wanted (C167; Fixpt's
                        // `TODO.md` §77): its fields count from the suffix, so each keeps its
                        // offset; the region and those wanted the same. Not KFX's, whose
                        // bloblet's Rust type is its fields'.
                        if any_p(lambda1s(move |f: &'static Ty| {
                            not(forgettable_p(s, car(xs), f))
                        }), fields_after(cdr(xs), i64_minus(size(ys), 1i64))) {
                            mismatch(v, s, a, e)
                        } else {
                            kfx_restricted(v, fits_all(v, s, fields_first(xs, size(ys)), ys), str_lit("a bloblet of more fields where one of fewer is expected, FX-26's width, which KFX has not yet (C167)"))
                        }
                    } else if not((string_eq_p(x, y) && i64_eq(size(xs), size(ys)))) {
                        mismatch(v, s, a, e)
                    } else if string_eq_p(x, str_lit("%poly")) {
                        // Two poly types (C107): the one's binders the other's, then their bodies.
                        fits(v, s, poly_body(xs), poly_instance(ys, map(lambda1s(move |n: Str| {
                            ty_var(n)
                        }), poly_binders_of(xs))))
                    } else if (string_eq_p(x, str_lit("%composable")) || string_eq_p(x, str_lit("%oneshot"))) {
                        // Its bound `D` the same both ways, as a tag's (C60).
                        let xd = {
                            let tagcase_ = car(cdr(cdr(xs)));
                            match *tagcase_ {
                                Ty::TyProc(es, ps, r) => {
                                    es
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        };
                        let yd = {
                            let tagcase_ = car(cdr(cdr(ys)));
                            match *tagcase_ {
                                Ty::TyProc(es, ps, r) => {
                                    es
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        };
                        let two = same_effs(s, xd, yd);
                        if null_p(two) {
                            mismatch(v, s, a, e)
                        } else {
                            fits(v, fits(v, fits(v, car(two), car(xs), car(ys)), car(cdr(xs)), car(cdr(ys))), car(cdr(cdr(cdr(xs)))), car(cdr(cdr(cdr(ys)))))
                        }
                    } else if (string_eq_p(x, str_lit("%nlist")) || string_eq_p(x, str_lit("%natof"))) {
                        // A size the same, or the one expected `finite` (C158).
                        if string_eq_p(x, str_lit("%nlist")) {
                            size_fits(v, fits(v, s, car(xs), car(ys)), car(cdr(xs)), car(cdr(ys)), a, e)
                        } else {
                            size_fits(v, s, car(xs), car(ys), a, e)
                        }
                    } else if string_eq_p(x, str_lit("%vsubr")) {
                        // Its element and result first, then its effect, which they may solve
                        // a region of: `list`'s `(alloc r)`, `r` acyclic, is pure (C156).
                        fits(v, fits(v, fits(v, s, car(cdr(xs)), car(cdr(ys))), car(cdr(cdr(xs))), car(cdr(cdr(ys)))), car(xs), car(ys))
                    } else {
                        fits_all(v, s, xs, ys)
                    }
                }
                Ty::TyProc(ees, eps, er) => {
                    // A composable continuation where a procedure is expected (C60).
                    if (string_eq_p(x, str_lit("%composable")) || string_eq_p(x, str_lit("%oneshot"))) {
                        fits(v, s, composable_as_proc(s, a), e)
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyVar(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyVar(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyProc(aes, aps, ar) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyProc(ees, eps, er) => {
                    if not(i64_eq(size(aps), size(eps))) {
                        mismatch(v, s, a, e)
                    } else if null_p(fit_effs(s, aes, ees)) {
                        // A region of `a`'s effect not solved yet, which its parameters solve,
                        // as where a module's poly value fits its module type's (C119): the
                        // parameters first, then the effects.
                        let s2 = fits_all(v, s, eps, aps);
                        let fitted = fit_effs(s2, aes, ees);
                        if null_p(fitted) {
                            mismatch(v, s, a, e)
                        } else {
                            fits(v, car(fitted), ar, er)
                        }
                    } else {
                        fits(v, fits_all(v, car(fit_effs(s, aes, ees)), eps, aps), ar, er)
                    }
                }
                Ty::TyData(d, args) => {
                    if string_eq_p(d, str_lit("%fx")) {
                        fits(v, s, a, car(args))
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        _ => {
            let other = tagcase_;
            if same_base_p(a, e) {
                s
            } else {
                mismatch(v, s, a, e)
            }
        }
    }
}

/// Fields, or a sum's members: each actual's type standing for the
/// expected's, covariant.
pub fn fits_each(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

/// The module type a `define-type` of a moduleof names (C24), as a module
/// value's is (C170).
pub fn module_alias_type(v: &'static Cv, d: Str) -> &'static Ty {
    let found = find_alias(after_prefix(d, str_lit("%module ")), cv_aliases(v));
    if null_p(found) {
        ty_unit()
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Alias::Alias(n, ps, body) => {
                parse_type(v, nil::<Str>(), body)
            }
        }
    }
}

/// A module of type `a` where one of `e` is wanted (C170; Fixpt's M4):
/// each abstract type `e` names given by `a`, abstract or described;
/// each description the same; each value fitting; `a` may give more.
pub fn mtype_fits(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    let eabs = filter(lambda1s(move |x: &'static Ty| {
        string_eq_p(mitem_kind(x), str_lit("%abs"))
    }), mtype_items(e));
    let froms = map(lambda1s(move |x: &'static Ty| {
        let tagcase_ = abs_ref(x);
        match *tagcase_ {
            Ty::TyData(n, args) => {
                n
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    }), eabs);
    let tos = map(lambda1s(move |x: &'static Ty| {
        mtype_provided(v, a, mitem_name(x))
    }), eabs);
    let e2 = data_replaced(froms, tos, e);
    mitems_fit(v, s, a, filter(lambda1s(move |x: &'static Ty| {
        not(string_eq_p(mitem_kind(x), str_lit("%abs")))
    }), mtype_items(e2)))
}

pub fn mtype_provided(v: &'static Cv, a: &'static Ty, n: Str) -> &'static Ty {
    let (ab, de) = (mtype_find(a, str_lit("%abs"), n), mtype_find(a, str_lit("%desc"), n));
    if not(null_p(ab)) {
        abs_ref(car(ab))
    } else if not(null_p(de)) {
        let tagcase_ = car(de);
        match *tagcase_ {
            Ty::TyData(d, args) => {
                car(args)
            }
            _ => {
                let other = tagcase_;
                ty_unit()
            }
        }
    } else {
        match refuse(v, string_append(str_lit("a module that gives no type "), n)) {}
    }
}

pub fn mitems_fit(mut v: &'static Cv, mut s: &'static St, mut a: &'static Ty, mut xs: Tys) -> &'static St {
    loop {
        if null_p(xs) {
            return s;
        } else {
            let x = car(xs);
            let k = mitem_kind(x);
            let n = mitem_name(x);
            let mine = mtype_find(a, k, n);
            let want = {
                let tagcase_ = x;
                match *tagcase_ {
                    Ty::TyData(d, args) => {
                        car(args)
                    }
                    _ => {
                        let other = tagcase_;
                        ty_unit()
                    }
                }
            };
            if null_p(mine) {
                return match refuse(v, string_append(str_lit("a module that gives no "), string_append(if string_eq_p(k, str_lit("%val")) {
                    str_lit("value ")
                } else {
                    str_lit("type ")
                }, n))) {};
            } else if string_eq_p(k, str_lit("%edesc")) {
                xs = cdr(xs);
                continue;
            } else {
                let got = {
                    let tagcase_ = car(mine);
                    match *tagcase_ {
                        Ty::TyData(d, args) => {
                            car(args)
                        }
                        _ => {
                            let other = tagcase_;
                            ty_unit()
                        }
                    }
                };
                (s, xs) = (if string_eq_p(k, str_lit("%desc")) {
                    fits(v, fits(v, s, got, want), want, got)
                } else {
                    fits(v, s, got, want)
                }, cdr(xs));
                continue;
            }
        }
    }
}

pub fn fields_after(mut ts: Tys, mut n: i64) -> Tys {
    loop {
        if (null_p(ts) || i64_lt_eq(n, 0i64)) {
            return ts;
        } else {
            (ts, n) = (cdr(ts), i64_minus(n, 1i64));
            continue;
        }
    }
}

/// Whether a bloblet at region `r` may forget a field of type `t` (Fixpt's
/// `bloblet/width-*.fx`): no procedure, no type variable, and no region
/// but `r`'s own, `acyclic` and `const`, so that the wider type says all
/// the storage it holds and no knot.
pub fn forgettable_p(s: &'static St, r: &'static Ty, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVar(n) => {
            (has_prefix_p(n, str_lit("'")) && same_region_p(s, r, t))
        }
        Ty::TyMeta(k) => {
            false
        }
        Ty::TyRconst(n) => {
            (string_eq_p(n, str_lit("acyclic")) || string_eq_p(n, str_lit("const")) || same_region_p(s, r, t))
        }
        Ty::TyProc(es, ps, rt) => {
            false
        }
        Ty::TyList(x, xr) => {
            (forgettable_p(s, r, x) && forgettable_p(s, r, xr))
        }
        Ty::TyRef(x, xr) => {
            (forgettable_p(s, r, x) && same_region_p(s, r, xr))
        }
        Ty::TyFlat(x, xr) => {
            (forgettable_p(s, r, x) && same_region_p(s, r, xr))
        }
        Ty::TyShape(p, ls, ts) => {
            not(any_p(lambda1s(move |x: &'static Ty| {
                not(forgettable_p(s, r, x))
            }), ts))
        }
        Ty::TyData(d, args) => {
            (not((string_eq_p(d, str_lit("%fx")) || string_eq_p(d, str_lit("%native")) || has_prefix_p(d, str_lit("%spec ")) || string_eq_p(d, str_lit("%vsubr")) || string_eq_p(d, str_lit("%poly")) || string_eq_p(d, str_lit("%composable")) || string_eq_p(d, str_lit("%oneshot")))) && not(any_p(lambda1s(move |x: &'static Ty| {
                not(forgettable_p(s, r, x))
            }), args)))
        }
        Ty::TyTag(x, h, es, rr) => {
            false
        }
        _ => {
            let other = tagcase_;
            true
        }
    }
}

pub fn same_region_p(s: &'static St, a: &'static Ty, b: &'static Ty) -> bool {
    let tagcase_ = walk(s, a);
    match *tagcase_ {
        Ty::TyRconst(n) => {
            let tagcase_ = walk(s, b);
            match *tagcase_ {
                Ty::TyRconst(m) => {
                    string_eq_p(n, m)
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyVar(n) => {
            let tagcase_ = walk(s, b);
            match *tagcase_ {
                Ty::TyVar(m) => {
                    string_eq_p(n, m)
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn fields_first(ts: Tys, n: i64) -> Tys {
    if (null_p(ts) || i64_lt_eq(n, 0i64)) {
        nil::<&'static Ty>()
    } else {
        kayak_rt::heap_cons(car(ts), fields_first(cdr(ts), i64_minus(n, 1i64)))
    }
}

/// Parameters: each expected parameter's type stands for the actual's.
pub fn fits_all(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

/// That size `za` may stand for `ze` (C158), in types `a` and `e`: `ze`
/// `finite`; else the two shown equal by the facts in scope, an
/// inference variable alone in one solved to make them so, its size
/// shown not negative.
pub fn size_fits(v: &'static Cv, s: &'static St, za: &'static Ty, ze: &'static Ty, a: &'static Ty, e: &'static Ty) -> &'static St {
    let (la, le) = (size_lin(s, za), size_lin(s, ze));
    if {
        let tagcase_ = walk(s, ze);
        match *tagcase_ {
            Ty::TyMeta(k) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } {
        // A size binder may be instantiated with `finite` too (Fixpt's sizes.md),
        // unless it sizes more than one argument, or something inside one.
        let tagcase_ = walk(s, ze);
        match *tagcase_ {
            Ty::TyMeta(k) => {
                if {
                    let tagcase_ = walk(s, za);
                    match *tagcase_ {
                        Ty::TyMeta(j) => {
                            i64_eq(j, k)
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                } {
                    s
                } else if (null_p(la) && any_p(lambda1s(move |f: &'static Fact| {
                    let tagcase_ = f;
                    match *tagcase_ {
                        Fact::Fact(fl, p, w) => {
                            (string_eq_p(fl, str_lit("%sizes")) && i64_eq(p, k) && string_eq_p(w, str_lit("not-finite")))
                        }
                    }
                }), st_facts(s))) {
                    match refuse_named(v, s, str_lit("a size cannot be finite here: it is the size of more than one argument, or of something inside one, and finite would not keep them the same")) {}
                } else {
                    solve(s, k, za)
                }
            }
            _ => {
                let other = tagcase_;
                s
            }
        }
    } else if null_p(le) {
        s
    } else if {
        let tagcase_ = walk(s, za);
        match *tagcase_ {
            Ty::TyMeta(k) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } {
        let tagcase_ = walk(s, za);
        match *tagcase_ {
            Ty::TyMeta(k) => {
                solve(s, k, ze)
            }
            _ => {
                let other = tagcase_;
                s
            }
        }
    } else if null_p(la) {
        mismatch(v, s, a, e)
    } else {
        let d = lin_resolved(s, lin_add(car(la), car(le), -1i64));
        let m = {
            let tagcase_ = d;
            match *tagcase_ {
                Lin::Lin(c, ts) => {
                    lone_meta(ts)
                }
            }
        };
        if null_p(m) {
            if (size_shown_p(v, s, d) && size_shown_p(v, s, lin_scaled(d, -1i64))) {
                s
            } else {
                mismatch(v, s, a, e)
            }
        } else {
            let tagcase_ = car(m);
            match *tagcase_ {
                Lterm::Lterm(n, k) => {
                    let solved = lin_scaled(lin_add(d, lin(0i64, kayak_rt::heap_cons(lterm(n, 1i64), kayak_rt::nil())), i64_minus(0i64, k)), i64_minus(0i64, k));
                    if (any_p(lambda1s(move |x: Str| {
                        has_prefix_p(x, str_lit("?"))
                    }), lin_names(solved)) || size_shown_p(v, s, solved)) {
                        solve(s, string_to_i64(after_prefix(n, str_lit("?"))), size_of_lin(solved))
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
            }
        }
    }
}

pub fn mismatch(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    match refuse_named(v, s, string_append(str_lit("a "), string_append(show_ty(s, a), string_append(str_lit(" is here, where a "), string_append(show_ty(s, e), str_lit(" is expected")))))) {}
}

/// How often type variable `n` is in `t`.
pub fn var_count(n: Str, t: &'static Ty) -> i64 {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyVar(m) => {
            if string_eq_p(m, n) {
                1i64
            } else {
                0i64
            }
        }
        Ty::TyList(e, r) => {
            i64_plus(var_count(n, e), var_count(n, r))
        }
        Ty::TyFlat(e, r) => {
            i64_plus(var_count(n, e), var_count(n, r))
        }
        Ty::TyRef(e, r) => {
            i64_plus(var_count(n, e), var_count(n, r))
        }
        Ty::TyData(d, args) => {
            vars_count(n, args)
        }
        Ty::TyTag(a, h, es, r) => {
            i64_plus(var_count(n, a), i64_plus(var_count(n, h), var_count(n, r)))
        }
        Ty::TyProc(es, ps, r) => {
            i64_plus(vars_count(n, ps), var_count(n, r))
        }
        Ty::TyShape(p, ls, ts) => {
            vars_count(n, ts)
        }
        _ => {
            let other = tagcase_;
            0i64
        }
    }
}

pub fn vars_count(n: Str, ts: List<&'static Ty>) -> i64 {
    if null_p(ts) {
        0i64
    } else {
        i64_plus(var_count(n, car(ts)), vars_count(n, cdr(ts)))
    }
}

/// Whether `t` has a region variable (named with a `'` first), past its
/// latent effects: a letrena's, a place's, a region binder's (C42).
pub fn region_var_in_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVar(m) => {
            has_prefix_p(m, str_lit("'"))
        }
        Ty::TyList(e, r) => {
            (region_var_in_p(s, e) || region_var_in_p(s, r))
        }
        Ty::TyFlat(e, r) => {
            (region_var_in_p(s, e) || region_var_in_p(s, r))
        }
        Ty::TyRef(e, r) => {
            (region_var_in_p(s, e) || region_var_in_p(s, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1s(move |x: &'static Ty| {
                region_var_in_p(s, x)
            }), args)
        }
        Ty::TyTag(a, h, es, r) => {
            (region_var_in_p(s, a) || (region_var_in_p(s, h) || region_var_in_p(s, r)))
        }
        Ty::TyProc(es, ps, r) => {
            (any_p(lambda1s(move |x: &'static Ty| {
                region_var_in_p(s, x)
            }), ps) || region_var_in_p(s, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1s(move |x: &'static Ty| {
                region_var_in_p(s, x)
            }), ts)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

// `cwcc`'s `spin` (C168; Fixpt's `k-may-spin?`): a continuation called after
// `cwcc` returns comes back to it as often as it is called; only a receiver
// `(lambda (k) ...)` whose `k` is only called, so can only leave while
// `cwcc` runs, and which captures no continuation itself, needs none.
pub fn sexp_mentions_p(e: &'static Sexp, n: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(m, f, p) => {
            string_eq_p(m, n)
        }
        Sexp::Lst(xs, f, l, p) => {
            any_p(lambda1s(move |x: &'static Sexp| {
                sexp_mentions_p(x, n)
            }), xs)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// Whether `k` is in `e` only as a call's operator, never inside a
/// procedure made there (conservatively: never mentioned in one).
pub fn only_called_p(e: &'static Sexp, k: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(m, f, p) => {
            not(string_eq_p(m, k))
        }
        Sexp::Lst(xs, f, l, p) => {
            if null_p(xs) {
                true
            } else if {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(h, f2, p2) => {
                        string_member_p(h, kayak_rt::heap_cons(str_lit("lambda"), kayak_rt::heap_cons(str_lit("plambda"), kayak_rt::heap_cons(str_lit("rlambda"), kayak_rt::heap_cons(str_lit("letrec"), kayak_rt::heap_cons(str_lit("prompt"), kayak_rt::heap_cons(str_lit("module"), kayak_rt::heap_cons(str_lit("with"), kayak_rt::heap_cons(str_lit("quote"), kayak_rt::heap_cons(str_lit("define-rec"), kayak_rt::heap_cons(str_lit("vlambda"), kayak_rt::nil())))))))))))
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } {
                not(sexp_mentions_p(e, k))
            } else if sym_is_p(car(xs), k) {
                not(any_p(lambda1s(move |x: &'static Sexp| {
                    not(only_called_p(x, k))
                }), cdr(xs)))
            } else {
                not(any_p(lambda1s(move |x: &'static Sexp| {
                    not(only_called_p(x, k))
                }), xs))
            }
        }
        _ => {
            let other = tagcase_;
            true
        }
    }
}

/// Whether `cwcc`'s arguments are one receiver that can only leave.
pub fn escape_only_p(args: Sexps) -> bool {
    (not(null_p(args)) && null_p(cdr(args)) && {
        let r = car(args);
        if (head_is_p(r, str_lit("the")) && i64_eq(size(items(r)), 3i64)) {
            escape_only_p(cdr(cdr(items(r))))
        } else if (head_is_p(r, str_lit("lambda")) && i64_gt(size(items(r)), 2i64)) {
            let ps = items(second(items(r)));
            (i64_eq(size(ps), 1i64) && {
                let k = {
                    let tagcase_ = car(ps);
                    match *tagcase_ {
                        Sexp::Sym(n, f, p) => {
                            n
                        }
                        Sexp::Lst(ys, f, l, p) => {
                            if null_p(ys) {
                                str_lit("")
                            } else {
                                let tagcase_ = car(ys);
                                match *tagcase_ {
                                    Sexp::Sym(n, f2, p2) => {
                                        n
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        str_lit("")
                                    }
                                }
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                };
                (not(string_eq_p(k, str_lit(""))) && not(sexp_mentions_p(r, str_lit("cwcc"))) && not(any_p(lambda1s(move |b: &'static Sexp| {
                    not(only_called_p(b, k))
                }), cdr(cdr(items(r))))))
            })
        } else {
            false
        }
    })
}

pub fn cwcc_spin(name: Str, args: Sexps) -> Strings {
    if (string_eq_p(name, str_lit("cwcc")) && not(escape_only_p(args))) {
        the::<Strings>(kayak_rt::heap_cons(str_lit("spin"), kayak_rt::nil()))
    } else {
        nil::<Str>()
    }
}

/// Whether size binder `n` of a procedure's type `t` may be instantiated
/// with `finite`: it is in its parameters once, the size of one of them,
/// itself (Fixpt's rule: else `finite` would not keep two sizes the same).
pub fn finite_may_p(n: Str, t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            (i64_eq(vars_count(n, ps), 1i64) && any_p(lambda1s(move |p: &'static Ty| {
                (sized_p(p, str_lit("%nlist")) && {
                    let tagcase_ = sized_size(p);
                    match *tagcase_ {
                        Ty::TyVar(m) => {
                            string_eq_p(m, n)
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                })
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

// A scheme's instance: each variable an inference variable; those for
// regions are kept, so that a call's effect can name the regions found.
pub enum Inst {
    Inst(&'static Ty, &'static St, List<i64>, List<i64>),
}

pub fn inst(f0: &'static Ty, f1: &'static St, f2: List<i64>, f3: List<i64>) -> &'static Inst {
    kayak_rt::heap_alloc(Inst::Inst(f0, f1, f2, f3))
}

pub fn instantiate(s: &'static St, sc: &'static Scheme) -> &'static Inst {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            instantiate_vars(s, tvars, t, nil::<i64>(), nil::<i64>())
        }
    }
}

/// Each binder an inference variable; a region's and an effect's (C46)
/// kept apart from a type's.
pub fn instantiate_vars(s: &'static St, tvars: Strings, t: &'static Ty, regions: List<i64>, effects: List<i64>) -> &'static Inst {
    if null_p(tvars) {
        inst(t, s, regions, effects)
    } else {
        let tagcase_ = fresh(s);
        match *tagcase_ {
            Res::Res(m, es, s) => {
                let tagcase_ = m;
                match *tagcase_ {
                    Ty::TyMeta(k) => {
                        instantiate_vars(if (has_prefix_p(car(tvars), str_lit("#")) && not(finite_may_p(car(tvars), t))) {
                            note_fact(s, str_lit("%sizes"), k, str_lit("not-finite"))
                        } else {
                            s
                        }, cdr(tvars), replace_var(car(tvars), m, t), if char_eq_p(string_ref_i64(car(tvars), 0i64), '\'') {
                            kayak_rt::heap_cons(k, regions)
                        } else {
                            regions
                        }, if char_eq_p(string_ref_i64(car(tvars), 0i64), '~') {
                            kayak_rt::heap_cons(k, effects)
                        } else {
                            effects
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        inst(t, s, regions, effects)
                    }
                }
            }
        }
    }
}

/// `sc`'s instance; in a REPL's draft or entry, its inference variables
/// noted as their binders' names, to be said by them (C98).
pub fn named_instance(v: &'static Cv, s: &'static St, sc: &'static Scheme) -> &'static Inst {
    if {
        let tagcase_ = v;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                (string_eq_p(file, str_lit("<draft>")) || has_prefix_p(file, str_lit("<fx26:")))
            }
        }
    } {
        let tagcase_ = instantiate(s, sc);
        match *tagcase_ {
            Inst::Inst(t, s2, regions, effects) => {
                inst(t, binders_noted(s2, {
                    let tagcase_ = sc;
                    match *tagcase_ {
                        Scheme::Scheme(tvars, u) => {
                            tvars
                        }
                    }
                }, st_next(s)), regions, effects)
            }
        }
    } else {
        instantiate(s, sc)
    }
}

// The names in scope
/// FX-26's keywords, which name nothing (fixpt's top.rs, KEYWORDS).
pub fn keyword_p(name: Str) -> bool {
    (string_eq_p(name, str_lit("lambda")) || string_eq_p(name, str_lit("plambda")) || string_eq_p(name, str_lit("proj")) || string_eq_p(name, str_lit("if")) || string_eq_p(name, str_lit("letrec")) || string_eq_p(name, str_lit("let")) || string_eq_p(name, str_lit("begin")) || string_eq_p(name, str_lit("define")) || string_eq_p(name, str_lit("define*")) || string_eq_p(name, str_lit("define-type")) || string_eq_p(name, str_lit("define-generative")) || string_eq_p(name, str_lit("subr")) || string_eq_p(name, str_lit("poly")) || string_eq_p(name, str_lit("ref")) || string_eq_p(name, str_lit("pairof")) || string_eq_p(name, str_lit("dletrec")) || string_eq_p(name, str_lit("void")) || string_eq_p(name, str_lit("pure")) || string_eq_p(name, str_lit("maxeff")) || string_eq_p(name, str_lit("read")) || string_eq_p(name, str_lit("write")) || string_eq_p(name, str_lit("alloc")) || string_eq_p(name, str_lit("goto")) || string_eq_p(name, str_lit("comefrom")) || string_eq_p(name, str_lit("region")) || string_eq_p(name, str_lit("effect")) || string_eq_p(name, str_lit("type")) || string_eq_p(name, str_lit("prompt")) || string_eq_p(name, str_lit("prompt-tag")) || string_eq_p(name, str_lit("composable")) || string_eq_p(name, str_lit("mark-key")) || string_eq_p(name, str_lit("listof")) || string_eq_p(name, str_lit("cond")) || string_eq_p(name, str_lit("case")) || string_eq_p(name, str_lit("else")) || string_eq_p(name, str_lit("and")) || string_eq_p(name, str_lit("or")) || string_eq_p(name, str_lit("let*")) || string_eq_p(name, str_lit("define-effect")) || string_eq_p(name, str_lit("module-parameters")) || string_eq_p(name, str_lit("the")) || string_eq_p(name, str_lit("bloblet")) || string_eq_p(name, str_lit("fields")) || string_eq_p(name, str_lit("frozen")) || string_eq_p(name, str_lit("arrayof")) || string_eq_p(name, str_lit("icell")) || string_eq_p(name, str_lit("await")) || string_eq_p(name, str_lit("define-rec")) || string_eq_p(name, str_lit("letrena")) || string_eq_p(name, str_lit("letreap")) || string_eq_p(name, str_lit("rlambda")) || string_eq_p(name, str_lit("quote")) || string_eq_p(name, str_lit("productof")) || string_eq_p(name, str_lit("sumof")) || string_eq_p(name, str_lit("product")) || string_eq_p(name, str_lit("extract")) || string_eq_p(name, str_lit("sum")) || string_eq_p(name, str_lit("tagcase")) || string_eq_p(name, str_lit("module")) || string_eq_p(name, str_lit("moduleof")) || string_eq_p(name, str_lit("with")) || string_eq_p(name, str_lit("select")) || string_eq_p(name, str_lit("load-module")) || string_eq_p(name, str_lit("define-datatype")) || string_eq_p(name, str_lit("make-bloblet")) || string_eq_p(name, str_lit("bloblet-ref")) || string_eq_p(name, str_lit("bloblet-set!")) || string_eq_p(name, str_lit("bloblet-freeze")) || string_eq_p(name, str_lit("bloblet-byte")) || string_eq_p(name, str_lit("bloblet-set-byte!")) || string_eq_p(name, str_lit("bloblet-bytes")) || string_eq_p(name, str_lit("rmake-bloblet")) || string_eq_p(name, str_lit("dlambda")) || string_eq_p(name, str_lit("=>")) || string_eq_p(name, str_lit("blobref-at")) || string_eq_p(name, str_lit("blobref+")) || string_eq_p(name, str_lit("blobref-owner")) || string_eq_p(name, str_lit("blobref-offset")) || string_eq_p(name, str_lit("blobref-get")) || string_eq_p(name, str_lit("blobref-set!")) || string_eq_p(name, str_lit("blobref-index")) || string_eq_p(name, str_lit("blobref-variant!")))
}

/// FX-26's forms of processes that are calls (C101): typed as procedures
/// are, but a call headed by one is the form, whatever binds its name.
pub fn process_call_p(h: Str) -> bool {
    string_member_p(h, kayak_rt::heap_cons(str_lit("send"), kayak_rt::heap_cons(str_lit("receive"), kayak_rt::heap_cons(str_lit("icell-get"), kayak_rt::heap_cons(str_lit("icell-put!"), kayak_rt::nil())))))
}

/// FX-26's forms of processes and `par` (C101), each a form wherever it
/// heads a list, whatever binds its name.
pub fn process_form_p(h: Str) -> bool {
    (process_call_p(h) || string_member_p(h, kayak_rt::heap_cons(str_lit("spawn"), kayak_rt::heap_cons(str_lit("par"), kayak_rt::heap_cons(str_lit("pselect"), kayak_rt::nil())))))
}

pub fn bind_onto(mut xs: Binds, mut ys: Binds) -> Binds {
    loop {
        if null_p(xs) {
            return ys;
        } else {
            (xs, ys) = (cdr(xs), kayak_rt::heap_cons(car(xs), ys));
            continue;
        }
    }
}

/// `v`, checking a list that began at `line` of `file`, at offset `pos`.
pub fn near(v: &'static Cv, file: Str, line: i64, pos: i64) -> &'static Cv {
    if i64_eq(line, 0i64) {
        v
    } else {
        let tagcase_ = v;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, f, l, fs, tv, at) => {
                cv(bs, ds, als, es, here, group, file, line, fs, tv, pos)
            }
        }
    }
}

pub fn cv_facts(v: &'static Cv) -> Facts {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            fs
        }
    }
}

pub fn cv_file(v: &'static Cv) -> Str {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            file
        }
    }
}

pub fn cv_pos(v: &'static Cv) -> i64 {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            at
        }
    }
}

/// `v`, its refusals said at offset `pos`, a datum inside the list it checks.
pub fn at_offset(v: &'static Cv, pos: i64) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            cv(bs, ds, als, es, here, group, file, line, fs, tv, pos)
        }
    }
}

pub fn tys_first(ts: List<&'static Ty>, n: i64) -> List<&'static Ty> {
    if (null_p(ts) || i64_lt_eq(n, 0i64)) {
        nil::<&'static Ty>()
    } else {
        kayak_rt::heap_cons(car(ts), tys_first(cdr(ts), i64_minus(n, 1i64)))
    }
}

pub fn words_joined(xs: Strings, between: Str) -> Str {
    if null_p(xs) {
        str_lit("")
    } else if null_p(cdr(xs)) {
        car(xs)
    } else {
        string_append(car(xs), string_append(between, words_joined(cdr(xs), between)))
    }
}

/// Whether `e` is the hole the REPL puts where the next item of a draft
/// goes, to ask what may go there (live-repl.kfx, C97): `%hole`, in a
/// `<draft>` only, so that no file's meaning changes.
pub fn draft_hole_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            (string_eq_p(n, str_lit("%hole")) && string_eq_p(f, str_lit("<draft>")))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// `v`, its refusals said to be in `here`.
pub fn said_in(v: &'static Cv, here: Str) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, h, group, file, line, fs, tv, at) => {
            cv(bs, ds, als, es, here, group, file, line, fs, tv, at)
        }
    }
}

/// `xs` to the REPL's hole, which ends them: what follows it fills a
/// form's later parts, and is no call's argument.
pub fn through_hole(xs: Sexps) -> Sexps {
    if null_p(xs) {
        nil::<&'static Sexp>()
    } else if draft_hole_p(car(xs)) {
        kayak_rt::heap_cons(car(xs), kayak_rt::nil())
    } else {
        kayak_rt::heap_cons(car(xs), through_hole(cdr(xs)))
    }
}

/// `v`, its refusals said at `e`, if `e` is in a REPL's draft: where an
/// argument is refused, underlined (C97). Elsewhere `v`, so that no fact's
/// place changes.
pub fn in_draft(v: &'static Cv, e: &'static Sexp) -> &'static Cv {
    if string_eq_p(datum_file(e), str_lit("<draft>")) {
        at_offset(v, datum_pos(e))
    } else {
        v
    }
}

pub fn operator_char_p(c: char) -> bool {
    has_char_in_p(str_lit("?!<>=+*/%"), c)
}

/// Whether another name might mangle as `n` does: one with an operator's
/// character, or one whose mangling has what such a character's has.
pub fn might_clash_p(n: Str) -> bool {
    (any_p(&operator_char_p, string_chars(n)) || {
        let m = mangle(n);
        any_p(lambda1s(move |part: Str| {
            string_has_p(m, part)
        }), kayak_rt::heap_cons(str_lit("_p"), kayak_rt::heap_cons(str_lit("_x"), kayak_rt::heap_cons(str_lit("_to_"), kayak_rt::heap_cons(str_lit("_plus"), kayak_rt::heap_cons(str_lit("_star"), kayak_rt::heap_cons(str_lit("_slash"), kayak_rt::heap_cons(str_lit("_lt"), kayak_rt::heap_cons(str_lit("_gt"), kayak_rt::heap_cons(str_lit("_eq"), kayak_rt::heap_cons(str_lit("_pct"), kayak_rt::heap_cons(str_lit("_minus"), kayak_rt::nil()))))))))))))
    })
}

/// Another name in scope, spelled otherwise, that Rust names as `n`: two
/// KFX names one Rust name, one hiding the other (C27).
pub fn mangled_clash(n: Str, bs: Binds) -> Strings {
    if (has_prefix_p(n, str_lit("%")) || has_char_in_p(n, ' ') || not(might_clash_p(n))) {
        nil::<Str>()
    } else {
        let m = mangle(n);
        concat(map(lambda1s(move |b: &'static Bind| {
            let tagcase_ = b;
            match *tagcase_ {
                Bind::Bind(x, sc, w) => {
                    if (not(string_eq_p(x, n)) && not(has_prefix_p(x, str_lit("%"))) && not(has_char_in_p(x, ' ')) && i64_eq(mangled_length(x), string_length_i64(m)) && string_eq_p(mangle(x), m)) {
                        the::<Strings>(kayak_rt::heap_cons(string_append(n, string_append(str_lit(" and "), x)), kayak_rt::nil()))
                    } else {
                        nil::<Str>()
                    }
                }
            }
        }), bs))
    }
}

/// `bs` but the first of them named as `b`: the others bound with it.
pub fn remove_bind(b: &'static Bind, bs: Binds) -> Binds {
    if null_p(bs) {
        nil::<&'static Bind>()
    } else if {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                let tagcase_ = b;
                match *tagcase_ {
                    Bind::Bind(m, sc2, w2) => {
                        string_eq_p(n, m)
                    }
                }
            }
        }
    } {
        cdr(bs)
    } else {
        kayak_rt::heap_cons(car(bs), remove_bind(b, cdr(bs)))
    }
}

/// `v` with the names `more` binds; none with a `_`: KFX writes `-`, and
/// every Rust name kfx and kayak-rt write that a KFX name could meet has
/// a `_` (`i64_plus`, `tagcase_`), so none is ever hidden.
pub fn with_binds(v: &'static Cv, more: Binds) -> &'static Cv {
    if any_p(lambda1s(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                (not(has_prefix_p(n, str_lit("%"))) && not(has_char_in_p(n, ' ')) && not(string_eq_p(w, str_lit("prim"))) && not(kfx_name_p(n)))
            }
        }
    }), more) {
        match refuse(v, string_append(str_lit("a name KFX's names are not (lower case, digits, `-` and `?!<>=+*/%`, no `--`, none Rust writes): "), car(concat(map(lambda1s(move |b: &'static Bind| {
            let tagcase_ = b;
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    if kfx_name_p(n) {
                        nil::<Str>()
                    } else {
                        the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                    }
                }
            }
        }), more))))) {}
    } else {
        let clash = onto(concat(map(lambda1s(move |b: &'static Bind| {
            let tagcase_ = b;
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    mangled_clash(n, cv_binds(v))
                }
            }
        }), more)), concat(map(lambda1s(move |b: &'static Bind| {
            let tagcase_ = b;
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    mangled_clash(n, remove_bind(b, more))
                }
            }
        }), more)));
        if not(null_p(clash)) {
            match refuse(v, string_append(str_lit("two names that are one in Rust: "), car(clash))) {}
        } else {
            let tagcase_ = v;
            match *tagcase_ {
                Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                    cv(bind_onto(more, bs), ds, als, es, here, group, file, line, fs, tv, at)
                }
            }
        }
    }
}

/// A local may be named by a keyword, as FX-26 has it; it may not then be
/// called, since FX-26 reads such a call as its form (`synth-call`). A
/// module's, its abstract types named for it (C170).
pub fn local(v: &'static Cv, name: Str, t: &'static Ty) -> &'static Bind {
    bind(name, scheme(nil::<Str>(), mtype_named(name, t)), str_lit("local"))
}

/// A local narrowed by a test (C62): the same Rust local, its type known
/// better, unboxed where it is named if a union's (C75).
pub fn narrowed(v: &'static Cv, name: Str, t: &'static Ty) -> &'static Bind {
    bind(name, scheme(nil::<Str>(), t), str_lit("narrowed"))
}

/// The type of the binding of `name` a narrowing narrows, as a list of
/// one, or none.
pub fn bind_origin(mut name: Str, mut bs: Binds) -> Tys {
    loop {
        if null_p(bs) {
            return nil::<&'static Ty>();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    if (string_eq_p(n, name) && not(string_eq_p(wher, str_lit("narrowed")))) {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tv, t) => {
                                return kayak_rt::heap_cons(t, kayak_rt::nil());
                            }
                        }
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

// Expressions
pub fn with_effs(r: &'static Res, es: Strings) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            res(t, effs_union(es, es0), s)
        }
    }
}

/// A procedure's type: KFX's own, or one of any convention (C116), which a
/// lambda is checked against as its procedure.
pub fn proc_type_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            true
        }
        Ty::TyData(d, args) => {
            (string_eq_p(d, str_lit("%fx")) || has_prefix_p(d, str_lit("%spec ")))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What naming a name does: a global is read; a member of the group being
/// defined, named as a value, may be called by whoever is given it, and so
/// loop: `spin`, as FX-26 has it. A global defined before cannot be, since
/// nothing it reaches is defined after it (KFX defines each name once); a
/// `letrec` member that may not end can.
pub fn naming_effs(s: &'static St, name: Str, wher: Str, t: &'static Ty, group: Strings) -> Strings {
    if string_eq_p(wher, str_lit("rec")) {
        kayak_rt::heap_cons(str_lit("spin"), kayak_rt::nil())
    } else if not(string_eq_p(wher, str_lit("global"))) {
        nil::<Str>()
    } else if (proc_type_p(s, t) && string_member_p(name, group)) {
        kayak_rt::heap_cons(str_lit("spin"), kayak_rt::heap_cons(string_append(str_lit("g:"), name), kayak_rt::nil()))
    } else {
        kayak_rt::heap_cons(string_append(str_lit("g:"), name), kayak_rt::nil())
    }
}

/// Whether a value of `t` may hold a procedure: in a list, a cell, a
/// shape, a datatype's fields, a generative type's representation (one
/// not known, cautiously, yes); or `t` is not known yet.
pub fn holds_procedure_p(mut v: &'static Cv, mut s: &'static St, mut t: &'static Ty, mut seen: Strings) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyProc(es, ps, r) => {
                return true;
            }
            Ty::TyMeta(k) => {
                return true;
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyFlat(e, r) => {
                return false;
            }
            Ty::TyTag(a, h, d, r) => {
                return (holds_procedure_p(v, s, a, seen) || holds_procedure_p(v, s, h, seen));
            }
            Ty::TyShape(p, ls, ts) => {
                return any_p(lambda1s(move |x: &'static Ty| {
                    holds_procedure_p(v, s, x, seen)
                }), ts);
            }
            Ty::TyData(d, args) => {
                return (any_p(lambda1s(move |x: &'static Ty| {
                    holds_procedure_p(v, s, x, seen)
                }), args) || (not(string_member_p(d, seen)) && {
                    let found = find_family(d, cv_dts(v));
                    if kayak_rt::value::null_p(found) {
                        false
                    } else {
                        let tagcase_ = kayak_rt::value::unbox_other::<&'static Dt>(found);
                        match *tagcase_ {
                            Dt::Dt(n, ps, vs) => {
                                if null_p(vs) {
                                    let down = conversion_bind(string_append(str_lit("down-"), d), cv_binds(v));
                                    if null_p(down) {
                                        not(has_prefix_p(d, str_lit("%module ")))
                                    } else {
                                        let tagcase_ = car(down);
                                        match *tagcase_ {
                                            Bind::Bind(n2, sc, w) => {
                                                let tagcase_ = sc;
                                                match *tagcase_ {
                                                    Scheme::Scheme(tv, tt) => {
                                                        let tagcase_ = tt;
                                                        match *tagcase_ {
                                                            Ty::TyProc(es, xs, r) => {
                                                                holds_procedure_p(v, s, substitute(ps, args, r), kayak_rt::heap_cons(d, seen))
                                                            }
                                                            _ => {
                                                                let other = tagcase_;
                                                                true
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                } else {
                                    any_p(lambda1s(move |x: &'static Variant| {
                                        let tagcase_ = x;
                                        match *tagcase_ {
                                            Variant::Variant(tag, fs) => {
                                                any_p(lambda1s(move |f: &'static Ty| {
                                                    holds_procedure_p(v, s, substitute(ps, args, f), kayak_rt::heap_cons(d, seen))
                                                }), fs)
                                            }
                                        }
                                    }), vs)
                                }
                            }
                        }
                    }
                }));
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

// Whether a procedure of a type could be given itself (C81), FX-26's
// `cyclic` (Fixpt's infer.rs): a cycle in the type runs through a
// procedure's parameter. A type merely recursive, as a list or a `datum`
// is, lets nothing loop. In KFX only a datatype, or `datum`, can be met
// again on the way down: the trail is their names, each with whether a
// parameter was crossed on the way to it from the one before.
pub enum Trail {
    Trail(Str, bool),
}

pub fn trail(f0: Str, f1: bool) -> &'static Trail {
    kayak_rt::heap_alloc(Trail::Trail(f0, f1))
}

pub type Trails = List<&'static Trail>;

/// Whether a parameter was crossed on the way from `n`, met before, to here.
pub fn crossed_since_p(mut n: Str, mut ts: Trails) -> bool {
    loop {
        if null_p(ts) {
            return false;
        } else if {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Trail::Trail(m, p) => {
                    string_eq_p(m, n)
                }
            }
        } {
            return false;
        } else if {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Trail::Trail(m, p) => {
                    p
                }
            }
        } {
            return true;
        } else {
            ts = cdr(ts);
            continue;
        }
    }
}

pub fn on_trail_p(n: Str, ts: Trails) -> bool {
    any_p(lambda1s(move |t: &'static Trail| {
        let tagcase_ = t;
        match *tagcase_ {
            Trail::Trail(m, p) => {
                string_eq_p(m, n)
            }
        }
    }), ts)
}

pub fn cyclic_walk(mut v: &'static Cv, mut s: &'static St, mut t: &'static Ty, mut crossed: bool, mut ts: Trails) -> bool {
    loop {
        if i64_gt(size(ts), 64i64) {
            return true;
        } else {
            let x = walk(s, t);
            let tagcase_ = x;
            match *tagcase_ {
                Ty::TyProc(es, ps, r) => {
                    return (any_p(lambda1s(move |p: &'static Ty| {
                        cyclic_walk(v, s, p, true, ts)
                    }), ps) || cyclic_walk(v, s, r, crossed, ts));
                }
                Ty::TyList(e, r) => {
                    t = e;
                    continue;
                }
                Ty::TyRef(e, r) => {
                    t = e;
                    continue;
                }
                Ty::TyFlat(e, r) => {
                    t = e;
                    continue;
                }
                Ty::TyShape(p, ls, fs) => {
                    return any_p(lambda1s(move |f: &'static Ty| {
                        cyclic_walk(v, s, f, crossed, ts)
                    }), fs);
                }
                Ty::TyTag(a, h, d, r) => {
                    return (cyclic_walk(v, s, a, crossed, ts) || cyclic_walk(v, s, h, crossed, ts));
                }
                Ty::TyData(d, args) => {
                    let named = (string_eq_p(d, str_lit("datum")) || dt_named_p(d, cv_dts(v)));
                    if (named && on_trail_p(d, ts)) {
                        return (crossed || crossed_since_p(d, ts));
                    } else if named {
                        // Its fields; what it was given, cautiously, as if taken as a
                        // parameter, as FX-26 has it.
                        let (ts2, kids) = (the::<Trails>(kayak_rt::heap_cons(trail(d, crossed), ts)), if string_eq_p(d, str_lit("datum")) {
                            datum_members()
                        } else {
                            let found = find_family(d, cv_dts(v));
                            if kayak_rt::value::null_p(found) {
                                nil::<&'static Ty>()
                            } else {
                                let tagcase_ = kayak_rt::value::unbox_other::<&'static Dt>(found);
                                match *tagcase_ {
                                    Dt::Dt(n, ps, vs) => {
                                        concat(map(lambda1s(move |x: &'static Variant| {
                                            let tagcase_ = x;
                                            match *tagcase_ {
                                                Variant::Variant(tag, fs) => {
                                                    fs
                                                }
                                            }
                                        }), vs))
                                    }
                                }
                            }
                        });
                        return (any_p(lambda1s(move |k: &'static Ty| {
                            cyclic_walk(v, s, k, false, ts2)
                        }), kids) || any_p(lambda1s(move |k: &'static Ty| {
                            cyclic_walk(v, s, k, true, ts2)
                        }), args));
                    } else if (string_eq_p(d, str_lit("%composable")) || string_eq_p(d, str_lit("%oneshot"))) {
                        return (cyclic_walk(v, s, car(args), true, ts) || any_p(lambda1s(move |k: &'static Ty| {
                            cyclic_walk(v, s, k, crossed, ts)
                        }), cdr(args)));
                    } else {
                        return any_p(lambda1s(move |k: &'static Ty| {
                            cyclic_walk(v, s, k, crossed, ts)
                        }), args);
                    }
                }
                _ => {
                    let other = tagcase_;
                    return false;
                }
            }
        }
    }
}

/// Whether a call of a procedure of type `t`, not known, may loop with no
/// recursive call: FX-26 says `spin` for one whose type is recursive
/// through a parameter (C81; KFX had said it, more cautiously, for any
/// procedure that might hold a procedure).
pub fn self_applicable_p(v: &'static Cv, s: &'static St, t: &'static Ty) -> bool {
    cyclic_walk(v, s, t, false, nil::<&'static Trail>())
}

pub fn void_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVoid() => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What the branches after one of type `t` are checked against: the type
/// expected, if known; else nothing, each found by itself and then joined
/// (`join-state`), as FX-26 has it: a literal in one is an `int` though
/// another is an `i64`.
pub fn next_expected(s: &'static St, t: &'static Ty, expected: Tys) -> Tys {
    if null_p(expected) {
        nil::<&'static Ty>()
    } else {
        expected
    }
}

/// A `with`'s or a `letregion`'s body, found by itself, as FX-26 finds it,
/// then fitted to the type expected.
pub fn found_then_fitted(v: &'static Cv, r: &'static Res, expected: Tys) -> &'static Res {
    if null_p(expected) {
        r
    } else {
        let tagcase_ = r;
        match *tagcase_ {
            Res::Res(t, es, s) => {
                res(car(expected), es, fits(v, s, t, car(expected)))
            }
        }
    }
}

/// Branches found by themselves agree: the rest's type fits the first's.
pub fn join_state(v: &'static Cv, s: &'static St, t: &'static Ty, rest: &'static Ty, expected: Tys) -> &'static St {
    if (not(null_p(expected)) || void_p(s, t) || void_p(s, rest)) {
        s
    } else {
        fits(v, s, rest, t)
    }
}

/// The type of branches, the first of type `t` and the rest of `rest`.
pub fn joined(s: &'static St, t: &'static Ty, rest: &'static Ty, expected: Tys) -> &'static Ty {
    if not(null_p(expected)) {
        car(expected)
    } else if void_p(s, t) {
        rest
    } else {
        t
    }
}

/// A region, solved: one no argument nor expected type said is `acyclic`,
/// as FX-26's fresh region for it, masked where it is not seen, is pure.
pub fn region_of(v: &'static Cv, s: &'static St, r: &'static Ty) -> &'static Res {
    let tagcase_ = walk(s, r);
    match *tagcase_ {
        Ty::TyMeta(k) => {
            res(ty_rconst(str_lit("acyclic")), nil::<Str>(), solve(s, k, ty_rconst(str_lit("acyclic"))))
        }
        _ => {
            let other = tagcase_;
            res(other, nil::<Str>(), s)
        }
    }
}

/// A call's latent effect, its regions' inference variables replaced by
/// the regions the arguments and the type expected found, or `acyclic`.
pub fn name_regions(v: &'static Cv, s: &'static St, es: Strings, regions: List<i64>) -> &'static Res {
    if null_p(regions) {
        res(ty_unit(), es, s)
    } else {
        let tagcase_ = region_of(v, s, ty_meta(car(regions)));
        match *tagcase_ {
            Res::Res(r, rn, s) => {
                name_regions(v, s, rename_atoms(es, meta_name(car(regions)), region_string(s, r)), cdr(regions))
            }
        }
    }
}

/// Effects, those on region `r` removed.
pub fn masked(mut es: Strings, mut r: Str) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if (region_atom_p(car(es)) && string_eq_p(atom_region(car(es)), r)) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), masked(cdr(es), r));
        }
    }
}

/// Whether type `t` mentions region `r`, latent effects included.
pub fn mentions_p(s: &'static St, t: &'static Ty, r: Str) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVar(n) => {
            string_eq_p(n, r)
        }
        Ty::TyList(e, x) => {
            (mentions_p(s, e, r) || mentions_p(s, x, r))
        }
        Ty::TyFlat(e, x) => {
            (mentions_p(s, e, r) || mentions_p(s, x, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1s(move |x: &'static Ty| {
                mentions_p(s, x, r)
            }), ts)
        }
        Ty::TyTag(a, h, d, x) => {
            (mentions_p(s, a, r) || mentions_p(s, h, r) || mentions_p(s, x, r) || not(string_eq_p(words_of(masked(d, r)), words_of(d))))
        }
        Ty::TyRef(e, x) => {
            (mentions_p(s, e, r) || mentions_p(s, x, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1s(move |a: &'static Ty| {
                mentions_p(s, a, r)
            }), args)
        }
        Ty::TyProc(es, ps, x) => {
            (not(string_eq_p(words_of(masked(es, r)), words_of(es))) || mentions_p(s, x, r) || any_p(lambda1s(move |p: &'static Ty| {
                mentions_p(s, p, r)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// The operations whose result is a `nat` when their operands are, as
/// FX-26 keeps a `nat` through them: a sum. (A product, a larger, a smaller
/// are `int`s to FX-26's checker.)
pub fn nat_op_p(h: Str) -> bool {
    string_eq_p(h, str_lit("+"))
}

pub fn prim_p(b: &'static Bind) -> bool {
    let tagcase_ = b;
    match *tagcase_ {
        Bind::Bind(n, sc, wher) => {
            string_eq_p(wher, str_lit("prim"))
        }
    }
}

pub fn nat_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyNat() => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// Whether `t`, as written (no variable solved looked through), has an
/// inference variable in it.
pub fn holds_meta_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyMeta(k) => {
            true
        }
        Ty::TyList(e, r) => {
            (holds_meta_p(e) || holds_meta_p(r))
        }
        Ty::TyRef(e, r) => {
            (holds_meta_p(e) || holds_meta_p(r))
        }
        Ty::TyData(d, args) => {
            any_p(&holds_meta_p, args)
        }
        Ty::TyProc(es, ps, r) => {
            (holds_meta_p(r) || any_p(&holds_meta_p, ps))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(&holds_meta_p, ts)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// `nil` given for a parameter that is, as instantiated, an inference
/// variable; and a lambda one of whose parameters has no type written,
/// given for a procedure one of whose parameters' is such a variable (C74:
/// FX-26 hears lambdas last, and the emitter writes the closure's
/// parameters' types the checker found, so rustc need not find them):
/// decided before any argument is checked, so both passes agree.
pub fn deferred_p(arg: &'static Sexp, param: &'static Ty) -> bool {
    (({
        let tagcase_ = param;
        match *tagcase_ {
            Ty::TyMeta(k) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && sym_is_p(arg, str_lit("nil"))) || (head_is_p(arg, str_lit("lambda")) && any_p(lambda1s(move |p: &'static Sexp| {
        let tagcase_ = p;
        match *tagcase_ {
            Sexp::Sym(n, f, x) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }), items(second(items(arg)))) && {
        let tagcase_ = param;
        match *tagcase_ {
            Ty::TyProc(es, ps, r) => {
                any_p(&holds_meta_p, ps)
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }))
}

pub fn eqv_bool_p(a: bool, b: bool) -> bool {
    if a {
        b
    } else {
        not(b)
    }
}

pub fn masked_goto(mut es: Strings, mut r: Str) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if string_eq_p(car(es), string_append(str_lit("goto:"), r)) {
            es = cdr(es);
            continue;
        } else if string_eq_p(car(es), string_append(str_lit("comefrom:"), r)) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), masked_goto(cdr(es), r));
        }
    }
}

/// Every name in `e`, bound in it or not.
pub fn names_in(e: &'static Sexp) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, at_file, at_pos) => {
            kayak_rt::heap_cons(n, kayak_rt::nil())
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            names_in_all(xs)
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

pub fn names_in_all(es: Sexps) -> Strings {
    if null_p(es) {
        nil::<Str>()
    } else {
        onto(names_in(car(es)), names_in_all(cdr(es)))
    }
}

/// Whether `body` may reach a tag of region `r` but `tag`: whether a
/// name in it, but `tag`'s if it is one, has a type that mentions `r`; a
/// module's name, whether anything it gives has (C116: `(with m f)`, a
/// K1 breach found by Fixpt's checker's modules, its `goto` masked).
pub fn reaches_p(v: &'static Cv, s: &'static St, body: &'static Sexp, tag: &'static Sexp, r: Str) -> bool {
    let tag_name = {
        let tagcase_ = tag;
        match *tagcase_ {
            Sexp::Sym(n, at_file, at_pos) => {
                n
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    any_p(lambda1s(move |n: Str| {
        (not(string_eq_p(n, tag_name)) && {
            let found = find_bind(n, cv_binds(v));
            (not(null_p(found)) && {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Bind::Bind(b, sc, wher) => {
                        if string_eq_p(wher, str_lit("module")) {
                            any_p(lambda1s(move |x: &'static Bind| {
                                let tagcase_ = x;
                                match *tagcase_ {
                                    Bind::Bind(xn, xsc, xw) => {
                                        (has_prefix_p(xn, string_append(n, str_lit(" "))) && {
                                            let tagcase_ = xsc;
                                            match *tagcase_ {
                                                Scheme::Scheme(tvars, t) => {
                                                    mentions_p(s, t, r)
                                                }
                                            }
                                        })
                                    }
                                }
                            }), cv_binds(v))
                        } else {
                            let tagcase_ = sc;
                            match *tagcase_ {
                                Scheme::Scheme(tvars, t) => {
                                    mentions_p(s, t, r)
                                }
                            }
                        }
                    }
                }
            })
        })
    }), names_in(body))
}

pub fn binds_prefixed(mut prefix: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    if (string_eq_p(wher, str_lit("export")) && has_prefix_p(n, prefix)) {
                        return kayak_rt::heap_cons(bind(after_prefix(n, prefix), sc, str_lit("item")), binds_prefixed(prefix, cdr(bs)));
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

/// Module `m`'s values, as items, named as `m` names them (the prefix made
/// once, C92: a module including another asks it often).
pub fn opened_binds(m: Str, bs: Binds) -> Binds {
    binds_prefixed(string_append(m, str_lit(" ")), bs)
}

// Whether an expression's value is a pair `cons` makes: FX-26 types one a
// `(pairof ...)`, never a `(listof ...)`, so that branches of which some
// are and some are not do not join where nothing is expected (KFX's
// `cons` is a list: `pairs-mixed?`, a K1 breach found 2026-10-16).
pub fn pair_made_p(mut e: &'static Sexp) -> bool {
    loop {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                if null_p(xs) {
                    return false;
                } else if sym_is_p(car(xs), str_lit("cons")) {
                    return true;
                } else if ((sym_is_p(car(xs), str_lit("let")) || sym_is_p(car(xs), str_lit("let*")) || sym_is_p(car(xs), str_lit("letrec")) || sym_is_p(car(xs), str_lit("begin"))) && i64_gt(size(xs), 1i64)) {
                    e = car(the::<Sexps>(reverse(xs)));
                    continue;
                } else if (sym_is_p(car(xs), str_lit("if")) && i64_eq(size(xs), 4i64)) {
                    return (pair_made_p(third(xs)) && pair_made_p(fourth(xs)));
                } else {
                    return false;
                }
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

/// The expressions whose values a branching form gives: an `if`'s two;
/// the last of each clause of a `cond`, `case`, `tagcase`, `typecase`.
pub fn branch_values(h: Str, xs: Sexps) -> Sexps {
    if string_eq_p(h, str_lit("if")) {
        if i64_eq(size(xs), 3i64) {
            cdr(xs)
        } else {
            nil::<&'static Sexp>()
        }
    } else if string_eq_p(h, str_lit("cond")) {
        concat(map(lambda1s(move |c: &'static Sexp| {
            let tagcase_ = c;
            match *tagcase_ {
                Sexp::Lst(ys, f, l, p) => {
                    if null_p(ys) {
                        nil::<&'static Sexp>()
                    } else {
                        the::<Sexps>(kayak_rt::heap_cons(car(the::<Sexps>(reverse(ys))), kayak_rt::nil()))
                    }
                }
                _ => {
                    let other = tagcase_;
                    nil::<&'static Sexp>()
                }
            }
        }), xs))
    } else if (string_eq_p(h, str_lit("case")) || string_eq_p(h, str_lit("tagcase")) || string_eq_p(h, str_lit("typecase"))) {
        if null_p(xs) {
            nil::<&'static Sexp>()
        } else {
            concat(map(lambda1s(move |c: &'static Sexp| {
                let tagcase_ = c;
                match *tagcase_ {
                    Sexp::Lst(ys, f, l, p) => {
                        if i64_lt(size(ys), 2i64) {
                            nil::<&'static Sexp>()
                        } else {
                            the::<Sexps>(kayak_rt::heap_cons(car(the::<Sexps>(reverse(ys))), kayak_rt::nil()))
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<&'static Sexp>()
                    }
                }
            }), cdr(xs)))
        }
    } else {
        nil::<&'static Sexp>()
    }
}

/// Whether a branching form's branches, nothing expected, mix a pair
/// `cons` makes with what is not one (`pair-made?`).
pub fn pairs_mixed_p(h: Str, xs: Sexps) -> bool {
    let vs = branch_values(h, xs);
    (any_p(&pair_made_p, vs) && any_p(lambda1s(move |x: &'static Sexp| {
        not(pair_made_p(x))
    }), vs))
}

/// Whether a control form has the parts it needs, before they are taken.
pub fn well_formed_p(h: Str, xs: Sexps) -> bool {
    let lists_p = lambda3s(move |x: &'static Sexp, n: i64, exact: bool| {
        (draft_hole_p(x) || ({
            let tagcase_ = x;
            match *tagcase_ {
                Sexp::Lst(ys, f, l, p) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        } && if exact {
            i64_eq(size(items(x)), n)
        } else {
            not(i64_lt(size(items(x)), n))
        }))
    });
    if string_eq_p(h, str_lit("if")) {
        i64_eq(size(xs), 3i64)
    } else if string_eq_p(h, str_lit("cond")) {
        (not(null_p(xs)) && not(any_p(lambda1s(move |c: &'static Sexp| {
            not(lists_p(c, 2i64, false))
        }), xs)))
    } else if (string_eq_p(h, str_lit("let")) || string_eq_p(h, str_lit("let*"))) {
        (i64_gt(size(xs), 1i64) && lists_p(car(xs), 0i64, false) && not(any_p(lambda1s(move |b: &'static Sexp| {
            not(lists_p(b, 2i64, true))
        }), items(car(xs)))))
    } else if string_eq_p(h, str_lit("letrec")) {
        (i64_gt(size(xs), 1i64) && lists_p(car(xs), 0i64, false) && not(any_p(lambda1s(move |b: &'static Sexp| {
            not(lists_p(b, 3i64, true))
        }), items(car(xs)))))
    } else if (string_eq_p(h, str_lit("case")) || string_eq_p(h, str_lit("tagcase"))) {
        (i64_gt(size(xs), 1i64) && not(any_p(lambda1s(move |c: &'static Sexp| {
            not(lists_p(c, 2i64, false))
        }), cdr(xs))))
    } else if (string_eq_p(h, str_lit("with")) || string_eq_p(h, str_lit("letregion"))) {
        i64_gt(size(xs), 1i64)
    } else {
        true
    }
}

